window.MIT_COURSE_PARTS=window.MIT_COURSE_PARTS||[];window.MIT_COURSE_PARTS.push([{"code":"1.000","title":"Introduction to Computer Programming and Numerical Methods for Engineering Applications","level":"U","description":"Presents the fundamentals of computing and computer programming (procedural and object-oriented programming) in an engineering context. Introduces logical operations, floating-point arithmetic, data structures, induction, iteration, and recursion. Computational methods for interpolation, regression, root finding, sorting, searching, and the solution of linear systems of equations and ordinary differential equations. Control of sensors and visualization of scientific data. Draws examples from engineering and scientific applications. Students use the Python programming environment to complete weekly assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"10:30","room":"5-234"}]},{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"10:30","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.000","terms":["fall"],"rating":5.99,"hours":8.41,"inClassHours":3.79,"outOfClassHours":4.62,"prerequisites":"","corequisites":"18.03","recommendedPreparation":""},{"code":"1.009","title":"Climate Change","level":"U","description":"Provides an introduction to global climate change processes, drivers, and impacts. Offers exposure to exciting MIT research on climate change. Students explore why and how the world should solve this global problem and how they can contribute to the solutions. Students produce a mini-project on the topic. Subject can count toward the 6-unit discovery-focused credit limit for first year students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"48-308"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.009","terms":["fall"],"rating":6.34,"hours":2.88,"inClassHours":1.34,"outOfClassHours":1.54,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.010A","title":"Probability: Concepts and Applications","level":"U","description":"Introduces probability with an emphasis on probabilistic systems analysis. Readings about conceptual and mathematical background are given in advanced of each class. Classes revise background and are centered on developing problem-solving skills. The course is exam-based and focused on the analysis of probabilistic outcomes, estimating what can happen under uncertain environments. Topics include random events and their probability, combinatorial analysis, conditional analysis, random vectors, functions of random vectors, propagation of uncertainty, and prediction analysis.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"1-242"}]},{"type":"Recitation","options":[{"days":["W"],"start":"14:30","end":"15:30","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.010A","terms":["fall"],"rating":5.33,"hours":8.91,"inClassHours":3.9,"outOfClassHours":5.01,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":""},{"code":"1.010B","title":"Causal Inference for Data Analysis","level":"U","description":"Introduces causal inference with an emphasis on probabilistic systems analysis. Readings about conceptual and mathematical background are given in advanced of each class. Focused on understanding theory based on real-world applications. The subject is project-based and focused on cause-effect relationships, understanding why probabilistic outcomes happen. Topics include correlation analysis, Reichenbach's principle, Simpson's paradox, structural causal models and graphs, interventions, do-calculus, average causal effects, dealing with missing information, mediation, and hypothesis testing. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"1-242"}]},{"type":"Recitation","options":[{"days":["W"],"start":"14:30","end":"15:30","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.010B","terms":["fall"],"rating":5.84,"hours":9.7,"inClassHours":3.64,"outOfClassHours":6.06,"prerequisites":"1.010A/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.013","title":"Senior Civil and Environmental Engineering Design","level":"U","description":"Students engage with faculty around a topic of mutual interest, building on the knowledge/skills gained throughout their program. Synthesizes prior coursework and experiences through a semester-long design project and related assignments. Students form teams and work on projects advised by faculty representatives from each core in the 1-ENG curriculum. Teams demonstrate creativity in applying theories and methodologies while considering their project's technical, environmental and social feasibility. Includes lectures on a variety of related engineering concepts, as well as scholarship and engineering practice and ethics. Provides instruction and practice in oral and written communication.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"16:00","room":"1-134"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.013","terms":["fall","spring"],"rating":5.41,"hours":6.51,"inClassHours":1.71,"outOfClassHours":4.8,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.018","title":"Fundamentals of Ecology","level":"U","description":"Fundamentals of ecology, considering Earth as an integrated dynamic living system. Coevolution of the biosphere and geosphere, biogeochemical cycles, metabolic diversity, primary productivity, competition and the niche, trophic dynamics and food webs, population growth and limiting factors. Population modeling, global carbon cycle, climate change, geoengineering, theories of resource competition and mutualism, allometric scaling, ecological genomics, niche theory, human population growth. Applied ecology.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"48-316"}]},{"type":"Recitation","options":[{"days":["M"],"start":"15:00","end":"16:00","room":"48-316"},{"days":["F"],"start":"11:00","end":"12:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.018","terms":["fall"],"rating":6.18,"hours":7.11,"inClassHours":3.44,"outOfClassHours":3.67,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.018A","title":"Fundamentals of Ecology I","level":"U","description":"Fundamentals of ecology, considering Earth as an integrated dynamic living system. Coevolution of the biosphere and geosphere, biogeochemical cycles, metabolic diversity, primary productivity, competition and the niche, trophic dynamics and food webs, population growth and limiting factors. Combination of 1.018A and 1.018B counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"1-242"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"48-316"},{"days":["R"],"start":"16:00","end":"17:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.018A","terms":["fall"],"rating":5.06,"hours":9.07,"inClassHours":4.06,"outOfClassHours":5.01,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.018B","title":"Fundamentals of Ecology II","level":"U","description":"Advanced topics in Ecology. Population modeling, global carbon cycle, climate change, geoengineering, theories of resource competition and mutualism, allometric scaling, ecological genomics, niche theory, human population growth. Applied ecology. Combination of 1.018A and 1.018B counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"1-242"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"48-316"},{"days":["R"],"start":"16:00","end":"17:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.018B","terms":["fall"],"rating":5.7,"hours":8.94,"inClassHours":4.27,"outOfClassHours":4.67,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.032","title":"Advanced Soil Mechanics","level":"U","description":"Covers topics in the characterization and nature of soils as multi-phase materials; the principle of effective stress; hydraulic conductivity and groundwater seepage; shear strength and stability analyses; stress-deformation properties, consolidation theory and calculation of settlements for clays and sands. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:30","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.032","terms":["fall"],"rating":6.12,"hours":17.82,"inClassHours":5.52,"outOfClassHours":12.3,"prerequisites":"1.037","corequisites":"","recommendedPreparation":""},{"code":"1.036","title":"Structural Mechanics and Design","level":"U","description":"Familiarizes students with structural systems, loads, and basis for structural design, including analysis of determinate and indeterminate structures (trusses, beams, frames, cables, and arches). Covers mechanical properties of construction materials, including concrete, steel, and composites. Studies concrete and steel structures through application of principles of structural mechanics. Evaluates behavior and design of reinforced concrete structural elements using limit strength design and serviceability principles. Introduces plastic analysis and design, and load factor design of structural steel members and connections. Team project emphasizes material covered through behavior and problem-based learning.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"13:00","end":"16:00","room":"1-242"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-277"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.036","terms":["fall"],"rating":6.21,"hours":9.11,"inClassHours":3.73,"outOfClassHours":5.38,"prerequisites":"","corequisites":"1.050","recommendedPreparation":""},{"code":"1.044","title":"Applied Category Theory for Engineering Design","level":"U","description":"Considers the multiple trade-offs at various abstraction levels and scales when designing complex, multi-component systems. Covers topics from foundational principles to advanced applications, emphasizing the role of compositional thinking in engineering. Introduces category theory as a mathematical framework for abstraction and composition, enabling a unified and modular approach to modeling, analyzing, and designing interconnected systems. Showcases successful applications in areas such as dynamical systems and automated system design optimization, with a focus on autonomous robotics and mobility. Offers students the opportunity to work on their own application through a dedicated project in the second half of the term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-234"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.044","terms":["fall"],"rating":6.5,"hours":8.3,"inClassHours":3.5,"outOfClassHours":4.8,"prerequisites":"(GIR:CAL2, 18.06)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.050","title":"Solid Mechanics","level":"U","description":"Introduction to statics and the principles of mechanics to describe the behavior of structures. Topics include free body diagrams, static equilibrium, force analysis of slender members, concept of stress and strain, linear elasticity, principal stresses and strains, Mohr's circle, and failure modes. Application to engineering structures such as bars, beams, frames, and trusses.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"1-371"}]},{"type":"Lab","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"1-371"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.050","terms":["fall"],"rating":6.51,"hours":8.88,"inClassHours":4.67,"outOfClassHours":4.21,"prerequisites":"GIR:PHY1","corequisites":"GIR:CAL2","recommendedPreparation":""},{"code":"1.051","title":"Sustainable Cement and Concrete","level":"U","description":"Delves into the sustainability and advanced engineering of cementitious materials, emphasizing their environmental impact, cutting-edge innovations, and performance in the built environment. Covers a broad spectrum of topics, including: ancient and modern cementitious materials, materials selection and optimization, advanced materials characterization, durability and deterioration mechanisms, carbon footprint reduction, and comprehensive life cycle assessment. Students apply rigorous design thinking, collaborate on lab experiences, and conduct research-oriented projects through a concrete mix competition. Prepares students to solve real-world challenges in cement and concrete science, equipping them to meet the demands of sustainable engineering. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"10:00","end":"12:00","room":"5-233"}]},{"type":"Lab","options":[{"days":["R"],"start":"09:00","end":"12:00","room":"1-050"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.051","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.053","title":"Dynamics and Control I","level":"U","description":"Introduction to the dynamics and vibrations of lumped-parameter models of mechanical systems. Kinematics. Force-momentum formulation for systems of particles and rigid bodies in planar motion. Work-energy concepts.  Virtual displacements and virtual work. Lagrange's equations for systems of particles and rigid bodies in planar motion. Linearization of equations of motion. Linear stability analysis of mechanical systems. Free and forced vibration of linear multi-degree of freedom models of mechanical systems; matrix eigenvalue problems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"10-250"}]},{"type":"Recitation","options":[{"days":["R"],"start":"12:00","end":"13:00","room":"1-371"},{"days":["R"],"start":"13:00","end":"14:00","room":"1-379"},{"days":["R"],"start":"14:00","end":"15:00","room":"1-379"},{"days":["F"],"start":"10:00","end":"11:00","room":"5-217"},{"days":["F"],"start":"11:00","end":"12:00","room":"5-217"},{"days":["F"],"start":"12:00","end":"13:00","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.053","terms":["fall","spring"],"rating":5.71,"hours":9.82,"inClassHours":3.73,"outOfClassHours":6.09,"prerequisites":"GIR:PHY2","corequisites":"2.087/18.03","recommendedPreparation":""},{"code":"1.058","title":"Structural Dynamics","level":"U","description":"Examines response of structures to dynamic excitation: free vibration, harmonic loads, pulses and earthquakes. Covers systems of single- and multiple-degree-of-freedom, up to the continuum limit, by exact and approximate methods. Includes applications to buildings, ships, aircraft and offshore structures. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.058","terms":["fall"],"rating":5.74,"hours":8.72,"inClassHours":2.86,"outOfClassHours":5.86,"prerequisites":"18.03/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.074","title":"Data Science Fundamentals","level":"U","description":"Introduction to statistical multivariate analysis methods and their applications to analyze data and mathematical models. Topics include sampling, experimental design, regression analysis, specification testing, dimension reduction, categorical data analysis, classification and clustering.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"11:00","room":"1-273"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:00","room":"1-371"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.074","terms":["fall"],"rating":6.19,"hours":6.41,"inClassHours":1.95,"outOfClassHours":4.46,"prerequisites":"1.000, 1.010A","corequisites":"","recommendedPreparation":""},{"code":"1.082","title":"Ethics for Engineers","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies alongside key readings by foundational ethical thinkers from Aristotle to Martin Luther King, Jr., and investigate which ethical approaches are best and how to apply them. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based, with the aim of introducing students to new ways of thinking. All sections cover the same core ethical frameworks, but some sections have a particular focus for case studies, such as bioengineering, or have an in-depth emphasis on particular thinkers. The subject is taught in separate sections. Students are eligible to take any section regardless of their registered subject number. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.082","terms":["fall","spring"],"rating":6.41,"hours":5.01,"inClassHours":2.06,"outOfClassHours":2.95,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.084","title":"Applied Microbiology","level":"U","description":"Introductory microbiology from a systems perspective - considers microbial diversity and the integration of data from a molecular, cellular, organismal, and ecological context to understand the interaction of microbial organisms with their environment. Special emphasis on specific viral, bacterial, and eukaryotic microorganisms and their interaction with animal hosts with focus on contemporary problems in areas such as vaccination, emerging disease, antimicrobial drug resistance, and toxicology.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"26-168"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.084","terms":["fall"],"rating":6.8,"hours":6.02,"inClassHours":3.0,"outOfClassHours":3.02,"prerequisites":"GIR:BIOL, GIR:CHEM","corequisites":"","recommendedPreparation":""},{"code":"1.087","title":"Adaptation to Climate Change","level":"U","description":"Addresses how to design adaptation solutions in response to regional climate change. Two specific case studies from Africa (Morocco) and Asia (Bangladesh) provide context. Covers the theory and observations of global climate change, regional climates for the two cases, and projections of its impact on the climate in the two regions during the 21st century. Presents ongoing research at MIT in designing climate change adaptation solutions to address emerging challenges regarding water availability, soil salinity, cyclones, and extreme heatwaves. Students engage in projects focusing on the two case studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:30","end":"14:30","room":"48-308"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.087","terms":["fall"],"rating":7.0,"hours":8.27,"inClassHours":3.0,"outOfClassHours":5.27,"prerequisites":"1.071/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.10","title":"Causal Inference for Data Analysis","level":"G","description":"Introduces causal inference with an emphasis on probabilistic systems analysis. Readings about conceptual and mathematical background are given in advanced of each class. Focused on understanding theory based on real-world applications. The subject is project-based and focused on cause-effect relationships, understanding why probabilistic outcomes happen. Topics include correlation analysis, Reichenbach's principle, Simpson's paradox, structural causal models and graphs, interventions, do-calculus, average causal effects, dealing with missing information, mediation, and hypothesis testing. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"1-242"}]},{"type":"Recitation","options":[{"days":["W"],"start":"14:30","end":"15:30","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.10","terms":["fall"],"rating":6.0,"hours":8.4,"inClassHours":3.7,"outOfClassHours":4.7,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.101","title":"Introduction to Civil and Environmental Engineering Design","level":"U","description":"Introduces the creative design process in the context of civil and environmental engineering. Emphasizes the idea-to-product trajectory: identification of a design question/problem, evaluation of requirements/constraints set by the application and/or client, and implementation into a concrete product deliverable. Fosters active learning through open-ended, student-driven projects in which teams apply the design process to a design/planning problem. In labs, students design and build a working model or an experiment that addresses a specific engineering aspect of their project. In addition to written and oral presentations, students start a web-based portfolio. Satisfies 6 units of Institute Laboratory credit. Enrollment limited; preference to Course 1 majors and minors.","groups":[{"type":"Lab","options":[{"days":["T","R"],"start":"13:00","end":"15:00","room":"1-050"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.101","terms":["fall"],"rating":4.69,"hours":6.46,"inClassHours":3.9,"outOfClassHours":2.56,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.105","title":"Environmental Biology Laboratory","level":"U","description":"Laboratory and data analysis techniques and their application to problems in the environmental life sciences. Design and execution of experiments testing the interactive effects of environmental variables on the growth, physiology, metabolism, and reproduction of plants and microbes. Emphasis on applications in agriculture, vegetation-mediated latent heat flux, and biotechnology. Satisfies 6 units of Institute Laboratory credit.  Enrollment limited; preference to 1-ENG and 1-12 majors.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"13:00","end":"17:00","room":"48-109"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.105","terms":["fall"],"rating":7.0,"hours":5.5,"inClassHours":4.0,"outOfClassHours":1.5,"prerequisites":"GIR:BIOL","corequisites":"","recommendedPreparation":""},{"code":"1.125","title":"Architecting and Engineering Software Systems","level":"G","description":"Software architecting and design of cloud-based software-intensive systems. Targeted at future engineering managers who must understand both the business and technical issues involved in architecting enterprise-scale systems. Student teams confront technically challenging problems. Introduces modern dev-ops concepts and cloud-computing, including cloud orchestration for machine learning. Also discusses cyber-security issues of key management and use of encrypted messaging for distributed ledgers, e.g., blockchain. Students face problem solving in an active learning lab setting, completing in-class exercises and weekly assignments leading to a group project. Some programming experience preferred. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.125","terms":["fall"],"rating":6.29,"hours":11.96,"inClassHours":3.34,"outOfClassHours":8.62,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.127","title":"Reinforcement Learning: Foundations and Methods","level":"G","description":"Examines reinforcement learning (RL) as a methodology for approximately solving sequential decision-making under uncertainty, with foundations in optimal control and machine learning. Provides a mathematical introduction to RL, including dynamic programming, statistical, and empirical perspectives, and special topics. Core topics include: dynamic programming, special structures, finite and infinite horizon Markov Decision Processes, value and policy iteration, Monte Carlo methods, temporal differences, Q-learning, stochastic approximation, and bandits. Also covers approximate dynamic programming, including value-based methods and policy space methods. Applications and examples drawn from diverse domains. Focus is mathematical, but is supplemented with computational exercises. An analysis prerequisite is suggested but not required; mathematical maturity is necessary.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"34-101"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"26-210"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-142"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-314"},{"days":["F"],"start":"14:00","end":"15:00","room":"26-314"},{"days":["F"],"start":"15:00","end":"16:00","room":"26-314"},{"days":["F"],"start":"16:00","end":"17:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.127","terms":["fall"],"rating":5.29,"hours":15.15,"inClassHours":3.56,"outOfClassHours":11.59,"prerequisites":"6.3700/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.144","title":"Applied Category Theory for Engineering Design","level":"G","description":"Considers the multiple trade-offs at various abstraction levels and scales when designing complex, multi-component systems. Covers topics from foundational principles to advanced applications, emphasizing the role of compositional thinking in engineering. Introduces category theory as a mathematical framework for abstraction and composition, enabling a unified and modular approach to modeling, analyzing, and designing interconnected systems. Showcases successful applications in areas such as dynamical systems and automated system design optimization, with a focus on autonomous robotics and mobility. Offers students the opportunity to work on their own application through a dedicated project in the second half of the term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-234"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.144","terms":["fall"],"rating":6.5,"hours":8.3,"inClassHours":3.5,"outOfClassHours":4.8,"prerequisites":"(GIR:CAL2, 18.06)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.146","title":"System Design and Management for a Changing World: Combined","level":"G","description":"Practical-oriented subject that builds upon theory and methods and culminates in extended application. Covers methods to identify, value, and implement flexibility in design (real options). Topics include definition of uncertainties, simulation of performance for scenarios, screening models to identify desirable flexibility, decision analysis, and multidimensional economic evaluation. Students demonstrate proficiency through an extended application to a system design of their choice. Complements research or thesis projects. Class is 'flipped' to maximize student engagement and learning. Meets with IDS.333 in the first half of term. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/m1a.html#1.146","terms":["fall"],"rating":6.19,"hours":11.16,"inClassHours":3.04,"outOfClassHours":8.12,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.174","title":"Data Science Fundamentals","level":"G","description":"Introduction to statistical multivariate analysis methods and their applications to analyze data and mathematical models. Topics include sampling, experimental design, regression analysis, specification testing, dimension reduction, categorical data analysis, classification and clustering. Students taking graduate version will complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"11:00","room":"1-273"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:00","room":"1-371"}]}],"url":"http://student.mit.edu/catalog/m1b.html#1.174","terms":["fall"],"rating":6.4,"hours":6.2,"inClassHours":1.9,"outOfClassHours":4.3,"prerequisites":"(1.000, 1.010A)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.205","title":"Advanced Demand Modeling","level":"G","description":"Advanced theories and applications of models for analysis and forecasting of users' behavior and demand for facilities, services, and products. Topics vary each year and typically include linear and nonlinear latent variable models, including structural equations and latent class models; estimation techniques with multiple data sources; joint discrete and continuous choice models; dynamic models; analysis of panel data; analysis of complex choices; estimation and forecasting with large choice sets; multidimensional probabilistic choice models; advanced choice models, including probit, logit mixtures, treatment of endogeneity, hybrid choice models, hidden Markov models, Monte Carlo simulation, Bayesian methods, survey design, sampling, model transferability, use of stated preferences data, and discrete choice models with machine learning. Term paper required.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"2-105"}]}],"url":"http://student.mit.edu/catalog/m1b.html#1.205","terms":["fall"],"rating":5.42,"hours":11.0,"inClassHours":3.0,"outOfClassHours":8.0,"prerequisites":"1.202/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.232","title":"The Airline Industry","level":"G","description":"Overview of the global airline industry and its economic and operational foundations. Examines interactions among key stakeholders in the aviation system, including airlines, airports, and air traffic management. Introduces fundamentals of airline economics, including demand, cost structures, pricing, competition, and regulatory frameworks. Covers operational and strategic decision-making such as fleet and network planning and airline operations. Considers system-level challenges including safety, environmental sustainability, and evolving global market dynamics. Students analyze industry performance, market developments, and emerging operational challenges in aviation.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m1b.html#1.232","terms":["fall"],"rating":6.65,"hours":9.04,"inClassHours":3.04,"outOfClassHours":6.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.260","title":"Logistics Systems","level":"G","description":"Provides an introduction to supply chain management from both analytical and practical perspectives. Taking a unified approach, students develop a framework for making intelligent decisions within the supply chain. Covers key logistics functions, such as demand planning, procurement, inventory theory and control, transportation planning and execution, reverse logistics, and flexible contracting. Explores concepts such as postponement, portfolio management, and dual sourcing. Emphasizes skills necessary to recognize and manage risk, analyze various tradeoffs, and model logistics systems. SCM.271 meets with SCM.260, but has fewer assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m1b.html#1.260","terms":["fall"],"rating":4.69,"hours":9.12,"inClassHours":3.23,"outOfClassHours":5.89,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.361","title":"Advanced Soil Mechanics","level":"G","description":"Covers topics in the characterization and nature of soils as multi-phase materials; the principle of effective stress; hydraulic conductivity and groundwater seepage; shear strength and stability analyses; stress-deformation properties, consolidatoin theory and calculation of settlements for clays and sands.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:30","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m1b.html#1.361","terms":["fall"],"rating":6.12,"hours":17.82,"inClassHours":5.52,"outOfClassHours":12.3,"prerequisites":"1.036","corequisites":"","recommendedPreparation":""},{"code":"1.364","title":"Advanced Geotechnical Engineering","level":"G","description":"Methodology for site characterization and geotechnical aspects of the design and construction of foundation systems.  Topics include site investigation (with emphasis on in situ testing), shallow (footings and raftings) and deep (piles and caissons) foundations, excavation support systems, groundwater control, slope stability, soil improvement (compaction, soil reinforcement, etc.), and construction monitoring.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:30","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m1b.html#1.364","terms":["fall"],"rating":6.9,"hours":18.9,"inClassHours":5.81,"outOfClassHours":13.09,"prerequisites":"1.361","corequisites":"","recommendedPreparation":""},{"code":"1.462","title":"Entrepreneurship in the Built Environment","level":"G","description":"Introduction to entrepreneurship and how it shapes the world we live in. Through experiential learning in a workshop setting, students start to develop entrepreneurial mindset and skills. Through a series of workshops, students are introduced to the concept of Venture Design to create new venture proposals for the built environment as a method to understand the role of the entrepreneur in the fields of design, planning, real estate, and other related industries.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"11:00","room":"W41-1401"}]}],"url":"http://student.mit.edu/catalog/m1b.html#1.462","terms":["fall"],"rating":6.48,"hours":5.21,"inClassHours":2.14,"outOfClassHours":3.07,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.511","title":"Sustainable Cement and Concrete","level":"G","description":"Delves into the sustainability and advanced engineering of cementitious materials, emphasizing their environmental impact, cutting-edge innovations, and performance in the built environment. Covers a broad spectrum of topics, including: ancient and modern cementitious materials, materials selection and optimization, advanced materials characterization, durability and deterioration mechanisms, carbon footprint reduction, and comprehensive life cycle assessment. Students apply rigorous design thinking, collaborate on lab experiences, and conduct research-oriented projects through a concrete mix competition. Prepares students to solve real-world challenges in cement and concrete science, equipping them to meet the demands of sustainable engineering. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"10:00","end":"12:00","room":"5-233"}]},{"type":"Lab","options":[{"days":["R"],"start":"09:00","end":"12:00","room":"1-050"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.511","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.545","title":"Atomistic Modeling and Simulation of Materials and Structures","level":"G","description":"Covers multiscale atomistic modeling and simulation methods, with focus on mechanical properties (elasticity, plasticity, creep, fracture, fatigue) of a range of materials (metals, ceramics, proteins, biological materials, biomaterials). Topics include mechanics of materials (energy principles, nano-/micromechanics, deformation mechanisms, size effects, hierarchical biological structures) and atomistic modeling (chemistry, interatomic potentials, chemical reactivity and first-principles methods, visualization, data analysis, numerical methods, supercomputing, data-driven algorithms). Includes interactive computational projects and cloud-based computing. Part I – Basic atomistic and multiscale methods, Part II – Interatomic potentials, Part III – Mechanical properties at multiple scales, Part IV – Materiomics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.545","terms":["fall"],"rating":6.4,"hours":11.4,"inClassHours":3.0,"outOfClassHours":8.4,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.550","title":"Engineering Mechanics","level":"G","description":"Introduction to engineering mechanics, including dimensional analysis, stresses and strength, deformation and strain, elasticity and thermodynamics of reversible processes, energy bounds in linear elasticity, perspectives on elastic instability, fracture and yield design. Focus is on underlying physics laws (conservation of momentum, thermodynamic of reversible and irreversible processes) as applied to truss, beam, and continuum systems.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"1-134"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"15:00","end":"16:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.550","terms":["fall"],"rating":6.87,"hours":9.53,"inClassHours":4.6,"outOfClassHours":4.93,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.562","title":"Structural Design Project I","level":"G","description":"Students work in teams to design a long-span structure, emphasizing conceptual design and advanced structural analysis. Subject covers structural systems and construction methods, interdisciplinary collaboration, design strategies for resistance to static and dynamic loading, and simplified calculation methods to validate numerical simulations. Emphasis on oral and visual communication of engineering concepts and students present their projects to leading engineers for feedback.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"1-134"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.562","terms":["fall"],"rating":5.44,"hours":13.64,"inClassHours":3.03,"outOfClassHours":10.61,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.564","title":"Environmental Technologies in Buildings","level":"G","description":"Introduction to the study of the thermal and luminous behavior of buildings. Examines the basic scientific principles underlying these phenomena and introduces students to a range of technologies and analysis techniques for designing comfortable indoor environments. Challenges students to apply these techniques and explore the role energy and light can play in shaping architecture. Additional work required of students taking the graduate version.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"3-133"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"W41-1402"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.564","terms":["fall"],"rating":6.23,"hours":11.92,"inClassHours":4.93,"outOfClassHours":6.99,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.573","title":"Structural Mechanics","level":"G","description":"Applies solid mechanics fundamentals to the analysis of marine, civil, and mechanical structures.  Continuum concepts of stress, deformation, constitutive response and boundary conditions are reviewed in selected examples. The principle of virtual work guides mechanics modeling of slender structural components (e.g., beams; shafts; cables, frames; plates; shells), leading to appropriate simplifying assumptions. Introduction to elastic stability.  Material limits to stress in design. Variational methods for computational structural mechanics analysis.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"2-105"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.573","terms":["fall"],"rating":4.58,"hours":11.7,"inClassHours":4.2,"outOfClassHours":7.5,"prerequisites":"2.002","corequisites":"","recommendedPreparation":""},{"code":"1.575","title":"Computational Structural Design and Optimization","level":"G","description":"Research seminar focusing on emerging applications of computation for creative, early-stage structural design and optimization for architecture. Incorporates computational design fundamentals, including problem parameterization and formulation; design space exploration strategies, including interactive, heuristic, and gradient-based optimization; and computational structural analysis methods, including the finite element method, graphic statics, and approximation techniques. Programing experience and familiarity with structural mechanics necessary. Additional work required of students taking graduate version. Limited to 25 total for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"W41-1216"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.575","terms":["fall"],"rating":6.41,"hours":13.65,"inClassHours":3.0,"outOfClassHours":10.65,"prerequisites":"((1.000/(6.100A, 6.100B)), (1.050/2.001/4.462))/''permission of instructor''","corequisites":"","recommendedPreparation":"Programing experience and familiarity with structural mechanics necessary."},{"code":"1.581","title":"Structural Dynamics","level":"G","description":"Examines response of structures to dynamic excitation: free vibration, harmonic loads, pulses and earthquakes. Covers systems of single- and multiple-degree-of-freedom, up to the continuum limit, by exact and approximate methods. Includes applications to buildings, ships, aircraft and offshore structures. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.581","terms":["fall"],"rating":5.74,"hours":8.72,"inClassHours":2.86,"outOfClassHours":5.86,"prerequisites":"18.03/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.583","title":"Topology Optimization of Structures","level":"G","description":"Covers free-form topology design of structures using formal optimization methods and mathematical programs, including design of structural systems, mechanisms, and material architectures. Strong emphasis on designing with gradient-based optimizers, finite element methods, and design problems governed by structural mechanics. Incorporates optimization theory and computational mechanics fundamentals, problem formulation, sensitivity analysis; and introduces cutting-edge extensions, including to other and multiple physics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-273"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.583","terms":["fall"],"rating":6.54,"hours":17.87,"inClassHours":4.14,"outOfClassHours":13.73,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.813","title":"Technology, Globalization, and Sustainable Development","level":"G","description":"Investigates sustainable development, taking a broad view to include not only a healthy economic base, but also a sound environment, stable and rewarding employment, adequate purchasing power and earning capacity, distributional equity, national self-reliance, and maintenance of cultural integrity. Explores national, multinational, and international political and legal mechanisms to further sustainable development through transformation of the industrial state. Addresses the importance of technological innovation and the financial crisis of 2008 and the emergence of the Covid-19 pandemic, Russia's invasion of Ukraine, and inflation, as well as governmental interventions to reduce inequality.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"18:30","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.813","terms":["fall"],"rating":5.58,"hours":8.25,"inClassHours":2.62,"outOfClassHours":5.63,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.818","title":"Sustainable Energy","level":"G","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal) energy types, along with storage, transmission, and conservation issues. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"10-250"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.818","terms":["fall"],"rating":5.65,"hours":8.07,"inClassHours":3.13,"outOfClassHours":4.94,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.83","title":"Environmental Organic Chemistry","level":"G","description":"Focuses on the processes affecting organic compounds in the environment. Uses physical chemical properties to predict chemical transfers between environmental compartments (air, water, sediments, and biota). Uses molecular structure-reactivity relationships to estimate chemical, photochemical, and biochemical transformation rates. Resulting process models are combined to predict environmental concentrations (and related biological exposures) of anthropogenic and natural organic compounds.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"48-308"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"48-311"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.83","terms":["fall"],"rating":5.87,"hours":9.36,"inClassHours":3.87,"outOfClassHours":5.49,"prerequisites":"5.601, 5.602, 18.03","corequisites":"","recommendedPreparation":""},{"code":"1.84","title":"Atmospheric Chemistry","level":"G","description":"Provides a detailed overview of the chemical transformations that control the abundances of key trace species in the Earth's atmosphere. Emphasizes the effects of human activity on air quality and climate. Topics include photochemistry, kinetics, and thermodynamics important to the chemistry of the atmosphere; stratospheric ozone depletion; oxidation chemistry of the troposphere; photochemical smog; aerosol chemistry; and sources and sinks of greenhouse gases and other climate forcers.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"35-308"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.84","terms":["fall"],"rating":6.85,"hours":11.11,"inClassHours":3.01,"outOfClassHours":8.1,"prerequisites":"5.601, 5.602","corequisites":"","recommendedPreparation":""},{"code":"1.86","title":"Methods and Problems in Microbiology","level":"G","description":"Students will read and discuss primary literature covering key areas of microbial research with emphasis on methods and approaches used to understand and manipulate microbes. Preference to first-year Microbiology and Biology students.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"15:30","room":"68-156"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.86","terms":["fall"],"rating":6.65,"hours":6.96,"inClassHours":3.0,"outOfClassHours":3.96,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.87","title":"Microbial Genetics and Evolution","level":"G","description":"Covers aspects of microbial genetic and genomic analyses, central dogma, horizontal gene transfer, and evolution.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:30","room":"66-160"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.87","terms":["fall"],"rating":6.36,"hours":9.65,"inClassHours":4.23,"outOfClassHours":5.42,"prerequisites":"7.03/7.05/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.877","title":"Adaptation to Climate Change","level":"G","description":"Addresses how to design adaptation solutions in response to regional climate change. Two specific case studies from Africa (Morocco) and Asia (Bangladesh) provide context. Covers the theory and observations of global climate change, regional climates for the two cases, and projections of its impact on the climate in the two regions during the 21st century. Presents ongoing research at MIT in designing climate change adaptation solutions to address emerging challenges regarding water availability, soil salinity, cyclones, and extreme heatwaves. Students engage in projects focusing on the two case studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:30","end":"14:30","room":"48-308"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.877","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"1.771/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.976","title":"Graduate Professional Development Seminar","level":"G","description":"Covers professional development topics and provides hands-on practice of these skills. Students participate in a series of written and oral communication workshops. Other topics include networking skills, work-life balance, mentoring, and career planning. Features an alumni panel showcasing a range of post-PhD careers. Limited to second-year graduate students in CEE.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.976","terms":["fall"],"rating":6.04,"hours":4.47,"inClassHours":2.07,"outOfClassHours":2.4,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.C25","title":"Real World Computation with Julia","level":"U","description":"Focuses on algorithms and techniques for writing and using modern technical software in a job, lab, or research group environment that may consist of interdisciplinary teams, where performance may be critical, and where the software needs to be flexible and adaptable. Topics include automatic differentiation, matrix calculus, scientific machine learning, parallel and GPU computing, and performance optimization with introductory applications to climate science, economics, agent-based modeling, and other areas. Labs and projects focus on performant, readable, composable algorithms, and software. Programming will be in Julia. Expects students to have some familiarity with Python, Matlab, or R. No Julia experience necessary.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.C25","terms":["fall"],"rating":6.3,"hours":7.33,"inClassHours":3.1,"outOfClassHours":4.23,"prerequisites":"6.100A, 18.03, 18.06","corequisites":"","recommendedPreparation":"Expects students to have some familiarity with Python, Matlab, or R."},{"code":"1.C57","title":"Optimization Methods","level":"G","description":"Introduction to the methods and applications of optimization. Topics include linear optimization, duality, non-linear optimization, integer optimization, and optimization under uncertainty. Instruction provided in modeling techniques to address problems arising in practice, mathematical theory to understand the structure of optimization problems, computational algorithms to solve complex optimization problems, and practical applications. Covers several examples and in-depth case studies based on real-world data to showcase impactful applications of optimization across management and engineering. Computational exercises based on the Julia-based programming language JuMP. Includes a term project. Basic competency in computational programming and linear algebra recommended. Students taking graduate version complete additional assignments. This subject was previously listed as 15.093/6.7200/IDS.200. One section primarily reserved for Sloan students; check syllabus for details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-345"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E25-111"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-345"},{"days":["F"],"start":"13:00","end":"14:00","room":"45-230"},{"days":["F"],"start":"14:00","end":"15:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.C57","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"18.C06/''permission of instructor''","corequisites":"","recommendedPreparation":"Basic competency in computational programming and linear algebra recommended."},{"code":"1.C571","title":"Optimization Methods","level":"U","description":"Introduction to the methods and applications of optimization. Topics include linear optimization, duality, non-linear optimization, integer optimization, and optimization under uncertainty. Instruction provided in modeling techniques to address problems arising in practice, mathematical theory to understand the structure of optimization problems, computational algorithms to solve complex optimization problems, and practical applications. Covers several examples and in-depth case studies based on real-world data to showcase impactful applications of optimization across management and engineering. Computational exercises based on the Julia-based programming language JuMP. Includes a term project. Basic competency in computational programming and linear algebra recommended. Students taking graduate version complete additional assignments. This subject was previously listed as 6.7201.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-345"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E25-111"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-345"},{"days":["F"],"start":"13:00","end":"14:00","room":"45-230"},{"days":["F"],"start":"14:00","end":"15:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.C571","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"18.C06/''permission of instructor''","corequisites":"","recommendedPreparation":"Basic competency in computational programming and linear algebra recommended."},{"code":"1.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.EPE","terms":["fall","spring"],"rating":5.75,"hours":1.75,"inClassHours":1.0,"outOfClassHours":0.75,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"1.S977","title":"Special Graduate Subject in Civil and Environmental Engineering","level":"G","description":"Graduate subjects taught experimentally; subjects offered by visiting faculty; and seminars on topics of current interest not included in the regular curriculum.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.S977","terms":["fall","spring"],"rating":6.92,"hours":3.34,"inClassHours":2.04,"outOfClassHours":1.3,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.S978","title":"Special Graduate Subject in Civil and Environmental Engineering","level":"G","description":"Graduate subjects taught experimentally; subjects offered by visiting faculty; and seminars on topics of current interest not included in the regular curriculum. 1.978 is taught P/D/F.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"12:00","end":"13:00","room":"1-131"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.S978","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"1.S980","title":"Special Graduate Subject in Civil and Environmental Engineering","level":"G","description":"Graduate subjects taught experimentally; subjects offered by visiting faculty; and seminars on topics of current interest not included in the the regular curriculum.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m1c.html#1.S980","terms":["fall"],"rating":6.92,"hours":9.36,"inClassHours":3.48,"outOfClassHours":5.88,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.01","title":"Ethics for Engineers","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies alongside key readings by foundational ethical thinkers from Aristotle to Martin Luther King, Jr., and investigate which ethical approaches are best and how to apply them. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based, with the aim of introducing students to new ways of thinking. All sections cover the same core ethical frameworks, but some sections have a particular focus for case studies, such as bioengineering, or have an in-depth emphasis on particular thinkers. The subject is taught in separate sections. Students are eligible to take any section regardless of their registered subject number. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.01","terms":["fall","spring"],"rating":6.41,"hours":5.01,"inClassHours":2.06,"outOfClassHours":2.95,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.10","title":"Introduction to Chemical Engineering","level":"U","description":"Explores the diverse applications of chemical engineering through example problems designed to build computer skills and familiarity with the elements of engineering design. Solutions require application of fundamental concepts of mass and energy conservation to batch and continuous systems involving chemical and biological processes. Problem-solving exercises distributed among lectures and recitation.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["T"],"start":"11:00","end":"12:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.10","terms":["fall"],"rating":5.22,"hours":11.13,"inClassHours":3.88,"outOfClassHours":7.25,"prerequisites":"GIR:CHEM, GIR:PHY1","corequisites":"18.03","recommendedPreparation":"Explores the diverse applications of chemical engineering through example problems designed to build computer skills and familiarity with the elements of engineering design."},{"code":"10.28","title":"Chemical-Biological Engineering Laboratory","level":"U","description":"Introduces the complete design of the bioprocess: from vector selection to production, separation, and characterization of recombinant products. Utilize concepts from many fields, such as, chemical and electrical engineering, and biology. Student teams work through parallel modules spanning microbial fermentation and animal cell culture. With the bioreactor at the core of the experiments, students study cell metabolism and biological pathways, kinetics of cell growth and product formation, oxygen mass transport, scale-up and techniques for the design of process control loops. Introduces novel bioreactors and powerful analytical instrumentation. Downstream processing and recombinant product purification also included. Credit cannot also be received for 10.28A. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"E18-676C"}]},{"type":"Lab","options":[{"days":["W","F"],"start":"13:00","end":"17:00","room":"E18-676"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.28","terms":["fall"],"rating":3.96,"hours":16.25,"inClassHours":9.24,"outOfClassHours":7.01,"prerequisites":"((5.07/7.05), (5.310/7.003))/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.291","title":"Introduction to Sustainable Energy","level":"U","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various renewable and conventional energy production technologies, energy end-use practices and alternatives, and consumption practices in different countries. Investigates their attributes within a quantitative analytical framework for evaluation of energy technology system proposals. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments. Limited to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"10-250"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.291","terms":["fall"],"rating":5.65,"hours":8.07,"inClassHours":3.13,"outOfClassHours":4.94,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.302","title":"Transport Processes","level":"U","description":"Principles of heat and mass transfer. Steady and transient conduction and diffusion. Radiative heat transfer. Convective transport of heat and mass in both laminar and turbulent flows. Emphasis on the development of a physical understanding of the underlying phenomena and upon the ability to solve real heat and mass transfer problems of engineering significance.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"66-160"},{"days":["F"],"start":"11:00","end":"12:00","room":"66-160"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.302","terms":["fall"],"rating":5.74,"hours":10.61,"inClassHours":3.73,"outOfClassHours":6.88,"prerequisites":"(5.601, 10.213, 10.301)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.321","title":"Design Principles in Mammalian Systems and Synthetic Biology","level":"U","description":"Focuses on the layers of design, from molecular to large networks, in mammalian biology. Formally introduces concepts in the emerging fields of mammalian systems and synthetic biology, including engineering principles in neurobiology and stem cell biology. Exposes advanced students from quantitative backgrounds to problem-solving opportunities at the interface of molecular biology and engineering. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.321","terms":["fall"],"rating":6.43,"hours":6.4,"inClassHours":3.07,"outOfClassHours":3.33,"prerequisites":"7.05, 18.03","corequisites":"","recommendedPreparation":""},{"code":"10.34","title":"Numerical Methods Applied to Chemical Engineering","level":"G","description":"Numerical methods for solving problems arising in heat and mass transfer, fluid mechanics, chemical reaction engineering, and molecular simulation. Topics: numerical linear algebra, solution of nonlinear algebraic equations and ordinary differential equations, solution of partial differential equations (e.g., Navier-Stokes), numerical methods in molecular simulation (dynamics, geometry optimization). All methods are presented within the context of chemical engineering problems. Familiarity with structured programming is assumed.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"66-110"}]},{"type":"Recitation","options":[{"days":["M"],"start":"17:00","end":"18:00","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.34","terms":["fall"],"rating":5.54,"hours":16.99,"inClassHours":4.46,"outOfClassHours":12.53,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":"Familiarity with structured programming is assumed."},{"code":"10.354","title":"Process Data Analytics","level":"U","description":"Provides an introduction to data analytics for manufacturing processes. Topics include chemometrics, discriminant analysis, hyperspectral imaging, machine learning, big data, Bayesian methods, experimental design, feature spaces, and pattern recognition as relevant to manufacturing process applications (e.g., output estimation, process control, and fault detection, identification and diagnosis). Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.354","terms":["fall"],"rating":6.24,"hours":8.45,"inClassHours":3.09,"outOfClassHours":5.36,"prerequisites":"18.03/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.367","title":"Topics in Applied Microfluidics","level":"U","description":"Provides an introduction to the field of microfluidics. Reviews fundamental concepts in transport phenomena and dimensional analysis, focusing on new phenomena which arise at small scales. Discusses current applications, with an emphasis on the contributions engineers bring to the field. Local and visiting experts in the field discuss their work. Students taking graduate version complete additional assignments. Limited to 30.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.367","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"10.301/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.384","title":"High-Throughput Platforms for Drug Discovery","level":"U","description":"Focuses on the fundamentals and applications of high-throughput systems for drug discovery. Formally introduces concepts in scalable platforms to identify molecules with desired biological activity, including topics such as single-cell genomics, protein display, directed evolution, proteomics, structural analysis, and robotics. Considerations in large-scale data analysis, machine learning, and molecular design for enhanced drug discovery discussed. Explores the theory and fundamentals of drug discovery from a quantitative perspective. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.384","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"7.05, 18.03","corequisites":"","recommendedPreparation":""},{"code":"10.391","title":"Sustainable Energy","level":"G","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal) energy types, along with storage, transmission, and conservation issues. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"10-250"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.391","terms":["fall"],"rating":5.65,"hours":8.07,"inClassHours":3.13,"outOfClassHours":4.94,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.40","title":"Chemical Engineering Thermodynamics","level":"G","description":"Basic postulates of classical thermodynamics. Application to transient open and closed systems. Criteria of stability and equilibria. Constitutive property models of pure materials and mixtures emphasizing molecular-level effects using the formalism of statistical mechanics. Phase and chemical equilibria of multicomponent systems. Applications emphasized through extensive problem work relating to practical cases.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"66-110"}]},{"type":"Recitation","options":[{"days":["M"],"start":"11:00","end":"12:00","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.40","terms":["fall"],"rating":5.1,"hours":17.23,"inClassHours":5.82,"outOfClassHours":11.41,"prerequisites":"10.213","corequisites":"","recommendedPreparation":""},{"code":"10.490","title":"Integrated Chemical Engineering","level":"U","description":"Presents and solves chemical engineering problems in an industrial context. Emphasis on the integration of fundamental concepts with approaches in process design, and on problems that demand synthesis, economic analysis, and process design; consideration of safety analysis, process dynamics and the use of process simulators and related tools to approach such problems. The specific application of these fundamental concepts will vary each term, and may include chemical, electrochemical, pharmaceutical, biopharmaceutical (biologic) or related processes, operated in batch, semi-batch, continuous or hybrid mode. May be repeated once for credit with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.490","terms":["fall","spring"],"rating":4.79,"hours":12.26,"inClassHours":2.95,"outOfClassHours":9.31,"prerequisites":"10.37","corequisites":"","recommendedPreparation":""},{"code":"10.492A","title":"Integrated Chemical Engineering Topics I","level":"U","description":"Chemical engineering problems presented and analyzed in an industrial context. Emphasizes the integration of fundamentals with material property estimation, process control, product development, and computer simulation. Integration of societal issues, such as engineering ethics, environmental and safety considerations, and impact of technology on society are addressed in the context of case studies. 10.37 and 10.302 required for certain topic modules. See departmental website for individual ICE-T module descriptions.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.492A","terms":["fall"],"rating":6.25,"hours":7.86,"inClassHours":3.71,"outOfClassHours":4.15,"prerequisites":"10.301, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.50","title":"Analysis of Transport Phenomena","level":"G","description":"Unified treatment of heat transfer, mass transfer, and fluid mechanics, emphasizing scaling concepts in formulating models and analytical methods for obtaining solutions. Topics include conduction and diffusion, laminar flow regimes, convective heat and mass transfer, and simultaneous heat and mass transfer with chemical reaction or phase change.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"66-110"}]},{"type":"Recitation","options":[{"days":["W"],"start":"17:00","end":"19:00","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.50","terms":["fall"],"rating":4.97,"hours":17.89,"inClassHours":6.04,"outOfClassHours":11.85,"prerequisites":"10.301, 10.302","corequisites":"","recommendedPreparation":""},{"code":"10.521","title":"Design Principles in Mammalian Systems and Synthetic Biology","level":"G","description":"Focuses on the layers of design, from molecular to large networks, in mammalian biology. Formally introduces concepts in the emerging fields of mammalian systems and synthetic biology, including engineering principles in neurobiology and stem cell biology. Exposes advanced students from quantitative backgrounds to problem-solving opportunities at the interface of molecular biology and engineering. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.521","terms":["fall"],"rating":6.43,"hours":6.4,"inClassHours":3.07,"outOfClassHours":3.33,"prerequisites":"(7.05, 18.03)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.538","title":"Principles of Molecular Bioengineering","level":"G","description":"Provides an introduction to the mechanistic analysis and engineering of biomolecules and biomolecular systems. Covers methods for measuring, modeling, and manipulating systems, including biophysical experimental tools, computational modeling approaches, and molecular design. Equips students to take systematic and quantitative approaches to the investigation of a wide variety of biological phenomena.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"16-220"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.538","terms":["fall"],"rating":4.7,"hours":16.52,"inClassHours":4.06,"outOfClassHours":12.46,"prerequisites":"7.06, 18.03","corequisites":"","recommendedPreparation":""},{"code":"10.539","title":"Fields, Forces, and Flows in Biological Systems","level":"G","description":"Molecular diffusion, diffusion-reaction, conduction, convection in biological systems; fields in heterogeneous media; electrical double layers; Maxwell stress tensor, electrical forces in physiological systems. Fluid and solid continua: equations of motion useful for porous, hydrated biological tissues. Case studies of membrane transport, electrode interfaces, electrical, mechanical, and chemical transduction in tissues, convective-diffusion/reaction, electrophoretic, electroosmotic flows in tissues/MEMs, and ECG. Electromechanical and physicochemical interactions in cells and biomaterials; musculoskeletal, cardiovascular, and other biological and clinical examples. Prior undergraduate coursework in transport recommended.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.539","terms":["fall"],"rating":6.38,"hours":10.51,"inClassHours":3.01,"outOfClassHours":7.5,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":"Prior undergraduate coursework in transport recommended."},{"code":"10.546","title":"Statistical Thermodynamics","level":"G","description":"Develops classical equilibrium statistical mechanical concepts for application to chemical physics problems. Basic concepts of ensemble theory formulated on the basis of thermodynamic fluctuations. Examples of applications include Ising models, lattice models of binding, ionic and non-ionic solutions, liquid theory, polymer and protein conformations, phase transition, and pattern formation. Introduces computational techniques with examples of liquid and polymer simulations.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.546","terms":["fall"],"rating":5.08,"hours":10.46,"inClassHours":3.06,"outOfClassHours":7.4,"prerequisites":"5.601/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.547","title":"Principles and Practice of Drug Development","level":"G","description":"Description and critical assessment of the major issues and stages of developing a pharmaceutical or biopharmaceutical. Drug discovery, preclinical development, clinical investigation, manufacturing and regulatory issues considered for small and large molecules. Economic and financial considerations of the drug development process. Multidisciplinary perspective from faculty in clinical; life; and management sciences; as well as industry guests.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.547","terms":["fall"],"rating":5.31,"hours":7.39,"inClassHours":3.17,"outOfClassHours":4.22,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.548","title":"Tumor Microenvironment and Immuno-Oncology: A Systems Biology Approach","level":"G","description":"Provides theoretical background to analyze and synthesize the most up-to-date findings from both laboratory and clinical investigations into solid tumor pathophysiology. Covers different topics centered on the critical role that the tumor microenvironment plays in the growth, invasion, metastasis and treatment of solid tumors. Develops a systems-level, quantitative understanding of angiogenesis, extracellular matrix, metastatic process, delivery of drugs and immune cells, and response to conventional and novel therapies, including immunotherapies. Discussions provide critical comments on the challenges and the future opportunities in research on cancer and in establishment of novel therapeutic approaches and biomarkers to guide treatment.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:00","end":"19:00","room":"E25-111"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.548","terms":["fall"],"rating":6.28,"hours":7.15,"inClassHours":2.0,"outOfClassHours":5.15,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.554","title":"Process Data Analytics","level":"G","description":"Provides an introduction to data analytics for manufacturing processes. Topics include chemometrics, discriminant analysis, hyperspectral imaging, machine learning, big data, Bayesian methods, experimental design, feature spaces, and pattern recognition as relevant to manufacturing process applications (e.g., output estimation, process control, and fault detection, identification and diagnosis). Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.554","terms":["fall"],"rating":6.24,"hours":8.45,"inClassHours":3.09,"outOfClassHours":5.36,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.568","title":"Physical Chemistry of Polymers","level":"G","description":"Introduction to polymer science from a molecular perspective. Covers topics in macromolecular confirmation and spatial extent, polymer solution thermodynamics and the theta state, linear viscoelasticity, rubber elasticity, and the thermodynamics and kinetics of formation of glasses and semicrystalline solids. Also provides a basic introduction to dynamics of macromolecules in solutions and melts, with entanglements. Presents methods for characterizing the molecular structure of polymers.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"66-160"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.568","terms":["fall"],"rating":5.84,"hours":12.48,"inClassHours":3.16,"outOfClassHours":9.32,"prerequisites":"''Prereq: 10.213''/10.40/(5.601 AND 5.602)","corequisites":"","recommendedPreparation":""},{"code":"10.569","title":"Synthesis of Polymers","level":"G","description":"Studies synthesis of polymeric materials, emphasizing interrelationships of chemical pathways, process conditions, and microarchitecture of molecules produced. Chemical pathways include traditional approaches such as anionic, radical condensation, and ring-opening polymerizations. New techniques, including stable free radicals and atom transfer free radicals, new catalytic approaches to well-defined architectures, and polymer functionalization in bulk and at surfaces. Process conditions include bulk, solution, emulsion, suspension, gas phase, and batch vs continuous fluidized bed. Microarchitecture includes tacticity, molecular-weight distribution, sequence distributions in copolymers, errors in chains such as branches, head-to-head addition, and peroxide incorporation.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.569","terms":["fall"],"rating":3.94,"hours":8.62,"inClassHours":2.88,"outOfClassHours":5.74,"prerequisites":"5.12","corequisites":"","recommendedPreparation":""},{"code":"10.584","title":"High-Throughput Platforms for Drug Discovery","level":"G","description":"Focuses on the fundamentals and applications of high-throughput systems for drug discovery. Formally introduces concepts in scalable platforms to identify molecules with desired biological activity, including topics such as single-cell genomics, protein display, directed evolution, proteomics, structural analysis, and robotics. Considerations in large-scale data analysis, machine learning, and molecular design for enhanced drug discovery discussed. Explores the theory and fundamentals of drug discovery from a quantitative perspective. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.584","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"(7.05, 18.03)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.585","title":"Engineering Nanotechnology","level":"G","description":"Review of fundamental concepts of energy, mass and electron transport in materials confined or geometrically patterned at the nanoscale, where departures from classical laws are dominant.  Specific applications to contemporary engineering challenges are discussed including problems in energy, biology, medicine, electronics, and material design.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"66-110"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.585","terms":["fall"],"rating":6.27,"hours":6.21,"inClassHours":3.19,"outOfClassHours":3.02,"prerequisites":"10.213/10.302/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.586","title":"Crystallization Science and Technology","level":"G","description":"Studies the nucleation and growth of crystals from a melt or a liquid solution and their important role in a wide range of applications, including pharmaeuticals, proteins, and semiconductor materials. Provides background information and covers topics needed to understand, perform experiments, construct and simulate mechanistic models, and design, monitor, and control crystallization processes. Limited to 30.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.586","terms":["fall"],"rating":5.52,"hours":4.56,"inClassHours":3.01,"outOfClassHours":1.55,"prerequisites":"10.213","corequisites":"","recommendedPreparation":"Provides background information and covers topics needed to understand, perform experiments, construct and simulate mechanistic models, and design, monitor, and control crystallization processes."},{"code":"10.625","title":"Electrochemical Energy Conversion and Storage: Fundamentals, Materials and Applications","level":"G","description":"Fundamental concepts, tools, and applications in electrochemical science and engineering. Introduces thermodynamics, kinetics and transport of electrochemical reactions. Describes how materials structure and properties affect electrochemical behavior of particular applications, for instance in lithium rechargeable batteries, electrochemical capacitors, fuel cells, photo electrochemical cells, and electrolytic cells. Discusses state-of-the-art electrochemical energy technologies for portable electronic devices, hybrid and plug-in vehicles, electrical vehicles. Theoretical and experimental exploration of electrochemical measurement techniques in cell testing, and in bulk and interfacial transport measurements (electronic and ionic resistivity and charge transfer cross the electrode-electrolyte interface).","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"3-333"}]},{"type":"Recitation","options":[{"days":["W"],"start":"16:00","end":"17:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.625","terms":["fall"],"rating":4.48,"hours":9.69,"inClassHours":3.19,"outOfClassHours":6.5,"prerequisites":"2.005/3.046/3.53/10.40/(2.051, 2.06)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.677","title":"Topics in Applied Microfluidics","level":"G","description":"Provides an introduction to the field of microfluidics. Reviews fundamental concepts in transport phenomena and dimensional analysis, focusing on new phenomena which arise at small scales. Discusses current applications, with an emphasis on the contributions engineers bring to the field. Local and visiting experts in the field discuss their work. Students taking graduate version complete additional assignments. Limited to 30.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.677","terms":["fall"],"rating":6.67,"hours":5.66,"inClassHours":3.12,"outOfClassHours":2.54,"prerequisites":"10.301/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.7003","title":"Applied Molecular Biology Laboratory","level":"U","description":"Laboratory-based exploration of modern experimental molecular biology. Specific experimental system studied may vary from term to term, depending on instructor. Emphasizes concepts of experimental design, data analysis and communication in biology and how these concepts are applied in the biotechnology industry. Satisfies 6 units of Institute Laboratory credit. Enrollment limited; admittance may be controlled by lottery.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:00","room":"68-181"}]},{"type":"Lab","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"68-074"}]},{"type":"Recitation","options":[{"days":["T"],"start":"11:00","end":"12:30","room":"68-121"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.7003","terms":["fall","spring"],"rating":5.78,"hours":12.54,"inClassHours":8.19,"outOfClassHours":4.35,"prerequisites":"7.002","corequisites":"","recommendedPreparation":""},{"code":"10.702","title":"Introduction to Experimental Biology and Communication","level":"U","description":"Introduction to the experimental concepts and methods of molecular biology, biochemistry, and genetic analysis. Emphasis on experimental design, critical data analysis, and the development of written communications skills. 12 units may be applied to the General Institute Laboratory Requirement. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"4-370"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"13:00","end":"17:00","room":"68-074"}]},{"type":"Recitation","options":[{"days":["M"],"start":"09:00","end":"11:00","room":"68-121"},{"days":["M"],"start":"13:00","end":"15:00","room":"68-121"},{"days":["M"],"start":"13:00","end":"15:00","room":"56-169"},{"days":["T"],"start":"09:00","end":"11:00","room":"66-148"},{"days":["W"],"start":"13:00","end":"15:00","room":"68-156"},{"days":["W"],"start":"09:00","end":"11:00","room":"68-121"},{"days":["M"],"start":"14:30","end":"16:30","room":"68-181"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.702","terms":["fall","spring"],"rating":5.53,"hours":15.11,"inClassHours":8.78,"outOfClassHours":6.33,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.792","title":"Global Operations Leadership Seminar","level":"G","description":"Integrative forum in which worldwide leaders in business, finance, government, sports, and education share their experiences and insights with students aspiring to run global operations. Students play a large role in managing the seminar. Preference to LGO students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.792","terms":["fall","spring"],"rating":5.04,"hours":2.17,"inClassHours":2.0,"outOfClassHours":0.17,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.806","title":"Management in Engineering","level":"U","description":"Introduction and overview of engineering management. Financial principles, management of innovation, technical strategy and best management practices. Case study method of instruction emphasizes participation in class discussion. Focus is on the development of individual skills and management tools. Restricted to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"35-225"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"1-150"},{"days":["T"],"start":"10:00","end":"11:00","room":"1-375"},{"days":["R"],"start":"16:00","end":"17:00","room":"1-375"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.806","terms":["fall"],"rating":4.75,"hours":8.38,"inClassHours":3.99,"outOfClassHours":4.39,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.807","title":"Innovation Teams","level":"G","description":"Introduces skills and capabilities for real-world problem solving to take technology from lab to societal impact: technical and functional exploration, opportunity discovery, market understanding, value economics, scale-up, intellectual property, and communicating/working for impact across disciplines. Students work in multidisciplinary teams formed around MIT research breakthroughs, with extensive in-class coaching and guidance from faculty, lab members, and select mentors. Follows a structured approach to innovating in which everything is a variable and the product, technology, and opportunities for new ventures can be seen as an act of synthesis. Teams gather evidence that permits a fact-based iteration across multiple application domains, markets, functionalities, technologies, and products, leading to a recommendation that maps a space of opportunity and includes actionable next steps to evolve the market and technology.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"15:00","room":"2-146"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.807","terms":["fall","spring"],"rating":6.42,"hours":10.79,"inClassHours":5.64,"outOfClassHours":5.15,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.817","title":"Atmospheric Chemistry","level":"G","description":"Provides a detailed overview of the chemical transformations that control the abundances of key trace species in the Earth's atmosphere. Emphasizes the effects of human activity on air quality and climate. Topics include photochemistry, kinetics, and thermodynamics important to the chemistry of the atmosphere; stratospheric ozone depletion; oxidation chemistry of the troposphere; photochemical smog; aerosol chemistry; and sources and sinks of greenhouse gases and other climate forcers.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"35-308"}]}],"url":"http://student.mit.edu/catalog/m10a.html#10.817","terms":["fall"],"rating":6.85,"hours":11.11,"inClassHours":3.01,"outOfClassHours":8.1,"prerequisites":"5.601, 5.602","corequisites":"","recommendedPreparation":""},{"code":"10.951","title":"Seminar in Biological Systems","level":"G","description":"Students, postdocs, and visitors to present their work on design, construction, and characterization of biological systems expanding on topics in synthetic biology, molecular systems biology, and cellular reprogramming.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:00","end":"11:00","room":"66-319"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.951","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.952","title":"Seminar in Bioelectrochemical Engineering","level":"G","description":"Students, postdocs and visitors present and discuss their research in bioelectrochemistry. Specific topics include electrochemical platform design for diagnostics and screening tools, fundamental studies of metalloproteins and electron transfer-proficient microbes, materials for bioelectronics, and in vitro disease models.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"11:00","room":"66-319"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.952","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.953","title":"Seminar in Heterogeneous Catalysis","level":"G","description":"Students present their research to other students and staff. Research topics include heterogeneous catalysis, design of catalytic materials, biomass conversion, biofuels, and CO2 utilization.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"08:30","end":"10:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.953","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.954","title":"Seminar in Applied Optical Spectroscopy","level":"G","description":"Research seminars given by students, postdocs, and visitors. Topics covered include applied optical spectroscopy and imaging, with particular emphasis on nanomaterials and how they relate to alternative energy technologies.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:00","end":"11:00","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.954","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.955","title":"Seminar in Electrochemical Engineering","level":"G","description":"Designed to allow students to present and discuss their research in the area of electrochemical engineering with a particular emphasis on energy storage and conversion (e.g., batteries, fuel cells, electroreactors).  Specific topics include active materials design, electroanalytical platform development, and integration of electrochemical and imaging techniques.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:00","end":"12:00","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.955","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.956","title":"Seminar in Atomistic Simulation","level":"G","description":"Seminar allows students to present their research to other students and staff. The research topics include electronic structure theory, computational chemistry techniques, and density functional theory with a focus on applications to catalysis and materials science.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"15:00","end":"16:30","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.956","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.957","title":"Seminar in Bioengineering Technology","level":"G","description":"Research seminars presented by students and guest speakers on emerging biotechnologies.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"11:00","room":"46-5305"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.957","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.960","title":"Seminar in Polymers and Soft Matter","level":"G","description":"A series of seminars covering a broad spectrum of topics in polymer science and engineering, featuring both on- and off-campus speakers.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.960","terms":["fall","spring"],"rating":6.16,"hours":1.23,"inClassHours":1.1,"outOfClassHours":0.13,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.962","title":"Seminar in Molecular Cell Engineering","level":"G","description":"Weekly seminar with discussion of ongoing research and relevant literature by graduate students, postdoctoral fellows, and visiting scientists on issues at the interface of chemical engineering with molecular cell biology.  Emphasis is on quantitative aspects of physicochemical mechanisms involved in receptor/ligand interactions, receptor signal transduction processes, receptor-mediated cell behavioral responses, and applications of these in biotechnology and medicine.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"16-220"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.962","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.963","title":"Seminar in Computer-Assisted Molecular Discovery","level":"G","description":"Allows students to present their research and literature reviews to other students and staff. Topics include the use of automation and computational methods for understanding the biological, chemical, and physical properties of molecular structures, as well as the design of new functional molecules and the synthetic processes to produce them.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:00","end":"14:00","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.963","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.964","title":"Seminar on Transport Theory","level":"G","description":"Research seminars presented by students and guest speakers on mathematical modeling of transport phenomena, focusing on electrochemical systems, electrokinetics, and microfluidics.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"13:00","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.964","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.965","title":"Seminar in Biosystems Engineering","level":"G","description":"Advanced topics on the state-of-the-art in design and implementation of analytical processes for biological systems, including single-cell analysis, micro/nanotechnologies, systems biology, biomanufacturing, and process engineering.  Seminars and discussions guided by the research interests of participating graduate students, postdoctoral associates, faculty, and visiting lecturers.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:00","end":"11:00","room":"76-258"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.965","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.966","title":"Seminar in Drug Delivery, Biomaterials, and Tissue Engineering","level":"G","description":"Focuses on presentations by students and staff on current research in the area of drug delivery, biomaterials, and tissue engineering. Includes topics such as nanotherapeutics, intracellular delivery, and therapies for diabetes.","groups":[{"type":"Lecture","options":[{"days":["M","F"],"start":"13:30","end":"14:30","room":"76-659"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.966","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.967","title":"Seminar in Protein-Polymer Materials Engineering","level":"G","description":"Research seminar covers topics on protein-based polymeric materials. Specific topics include bioelectronic materials, protein-polymer hybrids, and nanostructured proteins and polymers.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"11:00","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.967","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.968","title":"Seminar in Biomolecular Engineering","level":"G","description":"Covers research progress in the area of design, testing and mechanistic investigation of novel molecular systems for biotechnological applications.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"16:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.968","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.969","title":"Molecular Engineering Seminar","level":"G","description":"Seminar allows students to present their research to other students and staff.  Research topics include molecular simulations techniques and applications, and molecular engineering of pharmaceutical and biopharmaceutical processes and formulations.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"16:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.969","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.970","title":"Seminar in Molecular Computation","level":"G","description":"Seminar allows students to present their research to other students and staff. The research topics include computational chemistry techniques, kinetics, and catalysis. Focus is on molecular-level understanding of chemical change.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:00","end":"14:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.970","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.971","title":"Seminar in Fluid Mechanics and Transport Phenomena","level":"G","description":"Seminar series on current research on Newtonian and non-Newtonian fluid mechanics and transport phenomena, and applications to materials processing. Seminars given by guest speakers and research students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"18:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.971","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.974","title":"Seminar in Chemical Engineering Nanotechnology","level":"G","description":"Seminar covering topics related to current research in the application of chemical engineering principles to nanotechnology. Limited to 30.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"18:00","room":"66-110"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.974","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.975","title":"Seminar in Polymer Science and Engineering","level":"G","description":"Research seminars, presented by students engaged in thesis work in the field of polymers and by visiting lecturers from industry and academia.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:00","end":"14:00","room":"76-559"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.975","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.976","title":"Process Design, Operations, and Control","level":"G","description":"Seminars on the state of the art in design, operations, and control of processing systems, with emphasis on computer-based tools. Discussions guided by the research interests of participating students. Topics include mathematical and numerical techniques, representational methodologies, and software development.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"17:30","room":"66-319"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.976","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.978","title":"Seminar in Advanced Materials for Energy Applications","level":"G","description":"Students, postdocs, and visitors to present their work on synthesis, design, and characterization of polymeric and inorganic materials for applications related to membrane and adsorption-based separations.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"14:00","room":"66-319"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.978","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.979","title":"Seminar in Biological Soft Matter","level":"G","description":"Students, postdocs, and visitors present their work on understanding and designing soft materials and complex fluids related to human health and medical applications. Both experimental and modeling approaches are discussed, covering topics such as macromolecular transport, microhydrodynamics, biomechanics, microfluidics, and microphysiological systems.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"18:00","end":"19:30","room":"66-319"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.979","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.980","title":"Process Systems Engineering Seminar","level":"G","description":"Covers current research in the field of process systems engineering, including numerical methods, optimization, control theory, process design, machine learning, data science, and their uses in diverse application areas.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"11:00","end":"12:30","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.980","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.981","title":"Seminar in Colloid and Interface Science","level":"G","description":"Review of current topics in colloid and interface science. Topics include statistical mechanics and thermodynamics of micellar solutions, self-assembling systems, and microemulsions; solubilization of simple ions, amino acids, and proteins in reversed micelles; enzymatic reactions in reversed micelles; phase equilibria in colloidal systems; interfacial phenomena in colloidal systems; biomedical aspects of colloidal systems.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.981","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.982","title":"Seminar in Experimental Colloid and Surface Chemistry","level":"G","description":"In-depth discussion of fundamental physical relationships underlying techniques commonly used in the study of colloids and surfaces with a focus on recent advances and experimental applications. Topics have included the application of steady-state and time-resolved fluorescence spectroscopies, infrared spectroscopy, and scanning probe microscopies.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"18:00","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.982","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.985","title":"Advanced Manufacturing Seminar","level":"G","description":"Focuses on the state of the art in the systems engineering of materials products and materials manufacturing processes. Addresses topics such as pharmaceuticals manufacturing, polymeric drug delivery systems, and nano- and microstructured materials. Discussions guided by the research interests of participating students. Includes techniques from applied mathematics and numerical methods, multiscale systems analysis, and control theory.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"16:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.985","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.988","title":"Seminar in Immune Engineering","level":"G","description":"Students, postdocs, and visitors present their work on the discovery of protein drugs and the engineering of immune responses to advance human health and enhance fundamental knowledge of immune systems. Experimental and computational methods are discussed, covering topics such as antibodies, T cell receptors, vaccines, protein therapeutics, infectious diseases, autoimmune mechanisms, and cancer treatments.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"15:00","room":"NE46-1025"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.988","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":"Students, postdocs, and visitors present their work on the discovery of protein drugs and the engineering of immune responses to advance human health and enhance fundamental knowledge of immune systems."},{"code":"10.989","title":"Seminar in Biotechnology","level":"G","description":"Research seminars, presented by graduate students and visitors from industry and academia, covering a broad range of topics of current interest in biotechnology. Discussion focuses on generic questions with potential biotechnological applications and the quest for solutions through a coordinated interdisciplinary approach.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"12:00","end":"14:00","room":"66-360"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.989","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.990","title":"Introduction to Chemical Engineering Research","level":"G","description":"Introduction to research in chemical engineering by faculty of chemical engineering department. Focus is on recent developments and research projects available to new graduate students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:00","room":"66-110"}]},{"type":"Lab","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"66-110"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.990","terms":["fall"],"rating":6.33,"hours":3.82,"inClassHours":2.94,"outOfClassHours":0.88,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.991","title":"Seminar in Chemical Engineering","level":"G","description":"For students working on doctoral theses.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"16:30","room":"66-110"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.991","terms":["fall"],"rating":6.39,"hours":1.44,"inClassHours":1.16,"outOfClassHours":0.28,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.994","title":"Molecular Bioengineering","level":"G","description":"Presentations and discussion by graduate students, postdoctoral fellows, and visiting scientists of current literature and research on the engineering of protein biopharmaceuticals. Topics include combinatorial library construction and screening strategies, antibody engineering, gene therapy, cytokine engineering, and immunotherapy engineering strategies.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"12:00","end":"13:30","room":"76-261D"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.994","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.995","title":"Cellular and Metabolic Engineering","level":"G","description":"Graduate students, postdoctoral fellows, visiting scientists, and guest industrial practitioners to present their own research and highlight important advances from the literature in biochemical and bioprocess engineering. Topics of interest include metabolic engineering, novel microbial pathway design and optimization, synthetic biology, and applications of molecular biology to bioprocess development.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"18:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.995","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.997","title":"Theoretical and Computational Immunology Seminar","level":"G","description":"Presentations and discussions of current literature and research in theoretical and computational immunology. Topics include T cell biology, cell-cell recognition in immunology, polymers and membranes, and statistical mechanics.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"14:00","room":"E25-141"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.997","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"10.998","title":"Seminar in Crystallization Science and Technology","level":"G","description":"Focuses on current topics related to crystallization science and technology in the chemical, pharmaceutical and food industries. Discusses fundamental work on nucleation, polymorphism, impurity crystal interactions and nano-crystal formation, along with industrial applications of crystallization.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"16:00","room":"E17-517"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.998","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.EPE","terms":["fall","spring"],"rating":5.75,"hours":1.75,"inClassHours":1.0,"outOfClassHours":0.75,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"10.UAR","title":"Individual Laboratory Experience","level":"U","description":"Companion subject for students pursuing UROP or other supervised project experience. Instruction in responsible conduct of research and technical communication skills. Concurrent enrollment in an approved UROP or other supervised project required. Limited to Course 10 juniors and seniors; requires advance enrollment application subject to instructor approval.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m10b.html#10.UAR","terms":["fall","spring"],"rating":6.2,"hours":5.36,"inClassHours":1.03,"outOfClassHours":4.33,"prerequisites":"5.310/7.002/(''Coreq: 12 units UROP''/''other approved laboratory subject'', ''permission of instructor'')","corequisites":"","recommendedPreparation":""},{"code":"11.001","title":"Introduction to Urban Design and Development","level":"U","description":"Examines the evolving structure of cities and the way that cities, suburbs, and metropolitan areas can be designed and developed. Surveys the ideas of a wide range of people who have addressed urban problems. Stresses the connection between values and design. Demonstrates how physical, social, political and economic forces interact to shape and reshape cities over time. Introduces links between urban design and urban science.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.001","terms":["fall","spring"],"rating":5.93,"hours":6.77,"inClassHours":3.05,"outOfClassHours":3.72,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.002","title":"Making Public Policy","level":"U","description":"Examines how the struggle among competing advocates shapes the outputs of government. Considers how conditions become problems for government to solve, why some political arguments are more persuasive than others, why some policy tools are preferred over others, and whether policies achieve their goals. Investigates the interactions among elected officials, think tanks, interest groups, the media, and the public in controversies over global warming, urban sprawl, Social Security, health care, education, and other issues.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"W41-1216"}]},{"type":"Recitation","options":[{"days":["R"],"start":"19:00","end":"20:00","room":"W41-1101"},{"days":["R"],"start":"20:00","end":"21:00","room":"W41-1101"},{"days":["F"],"start":"10:00","end":"11:00","room":"W41-1101"},{"days":["F"],"start":"11:00","end":"12:00","room":"W41-1101"},{"days":["F"],"start":"12:00","end":"13:00","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.002","terms":["fall"],"rating":5.88,"hours":8.13,"inClassHours":3.77,"outOfClassHours":4.36,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.003","title":"Methods of Policy Analysis","level":"U","description":"Provides students with an introduction to public policy analysis. Examines various approaches to policy analysis by considering the concepts, tools, and methods used in economics, political science, and other disciplines. Students apply and critique these approaches through case studies of current public policy problems.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.003","terms":["fall"],"rating":6.93,"hours":8.44,"inClassHours":3.0,"outOfClassHours":5.44,"prerequisites":"11.002","corequisites":"14.01","recommendedPreparation":""},{"code":"11.008","title":"Undergraduate Planning Seminar","level":"U","description":"A weekly seminar that includes discussions on topics in cities and urban planning, including guest lectures from DUSP faculty and practicing planners. Topics include urban science, zoning, architecture and urban design, urban sociology, politics and public policy, transportation and mobility, democratic governance, civil rights and social justice, urban economics, affordable housing, environmental policy and planning, real estate and economic development, agriculture and food policy, public health, and international development. Weekly student presentations on local planning issues and current events; occasional walking tours or arranged field trips. May be repeated for credit. Enrollment may be limited; preference to Course 11 and 11-6 sophomores and juniors.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"W41-1119"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.008","terms":["fall"],"rating":6.94,"hours":4.06,"inClassHours":1.6,"outOfClassHours":2.46,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.011","title":"The Art and Science of Negotiation","level":"U","description":"Introduction to negotiation theory and practice. Applications in government, business, and nonprofit settings are examined. Combines a 'hands-on' personal skill-building orientation with a look at pertinent tactical and strategic foundations. Preparation insights, persuasion tools, ethical benchmarks, and institutional influences are examined as they shape our ability to analyze problems, negotiate agreements, and resolve disputes in social, organizational, and political circumstances characterized by interdependent interests. Enrollment limited by lottery; consult class website for information and deadlines.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.011","terms":["fall"],"rating":6.97,"hours":10.71,"inClassHours":3.07,"outOfClassHours":7.64,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.024","title":"Modeling Pedestrian Activity in Cities","level":"U","description":"Investigates the interaction between pedestrian activity, urban form, and land-use patterns in relatively dense urban environments. Informed by recent literature on pedestrian mobility, behavior, and biases, subject takes a practical approach, using software tools and analysis methods to operationalize and model pedestrian activity. Uses simplified yet powerful and scalable network analysis methods that focus uniquely on pedestrians, rather than engaging in comprehensive travel demand modeling across all modes. Emphasizes not only modeling or predicting pedestrian activity in given built settings, but also analyzing and understanding how changes in the built environment — land use changes, density changes, and connectivity changes — can affect pedestrian activity. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.024","terms":["fall"],"rating":6.07,"hours":9.04,"inClassHours":3.12,"outOfClassHours":5.92,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.025","title":"D-Lab: Development","level":"U","description":"Issues in international development, appropriate technology and project implementation addressed through lectures, case studies, guest speakers and laboratory exercises. Students form project teams to partner with community organizations in developing countries, and formulate plans for an optional IAP site visit. (Previous field sites include Ghana, Brazil, Honduras and India.) Recitation sections focus on specific project implementation, and include cultural, social, political, environmental and economic overviews of the target countries as well as an introduction to the local languages. Enrollment limited by lottery; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.025","terms":["fall"],"rating":6.37,"hours":12.05,"inClassHours":5.16,"outOfClassHours":6.89,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.029","title":"Mobility Ventures: Driving Innovation in Transportation Systems","level":"U","description":"Explores technological, behavioral, policy, and systems-wide frameworks for innovation in transportation systems, complemented with case studies across the mobility spectrum, from autonomous vehicles to urban air mobility to last-mile sidewalk robots. Students interact with a series of guest lecturers from CEOs and other business and government executives who are actively reshaping the future of mobility. Interdisciplinary teams of students collaborate to deliver business plans for proposed mobility-focused startups with an emphasis on primary market research. Students taking graduate version complete additional assignments. Preference to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.029","terms":["fall"],"rating":5.82,"hours":6.38,"inClassHours":3.03,"outOfClassHours":3.35,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.041","title":"Introduction to Housing, Community, and Economic Development","level":"U","description":"Provides a critical introduction to the shape and determinants of political, social, and economic inequality in America, with a focus on racial and economic justice. Explores the role of the city in visions of justice. Analyzes the historical, political, and institutional contexts of housing and community development policy in the US, including federalism, municipal fragmentation, and decentralized public financing. Introduces major dimensions in US housing policy, such as housing finance, public housing policy, and state and local housing affordability mechanisms. Reviews major themes in community economic development, including drivers of economic inequality, small business policy, employment policy, and cooperative economics. Expectations and evaluation criteria differ for students taking graduate version.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.041","terms":["fall"],"rating":6.55,"hours":8.41,"inClassHours":3.13,"outOfClassHours":5.28,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.062","title":"Securing Community Voice and Narrative in Times of Repression","level":"U","description":"Delves into how marginalized communities, individuals, and identities adapt mainstream media and communication tools and strategies to preserve their collective voice amidst repression. Explores various global movement areas and examines real-world examples and cases that illustrate these adaptations. Provides an overview of community narrative and storytelling methods, which are crucial for effective planning. Students engage in group projects that enhance their skills in designing narrative strategies. Students taking the graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"W41-2101"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.062","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.074","title":"Cybersecurity Clinic","level":"U","description":"Provides an opportunity for MIT students to become certified in methods of assessing the vulnerability of public agencies (particularly agencies that manage critical urban infrastructure) to the risk of cyberattack. Certification involves completing an 8-hour, self-paced, online set of four modules during the first four weeks of the semester followed by a competency exam. Students who successfully complete the exam become certified. The certified students work in teams with client agencies in various cities around the United States. Through preparatory interactions with the agencies, and short on-site visits, teams prepare vulnerability assessments that client agencies can use to secure the technical assistance and financial support they need to manage the risks of cyberattack they are facing. Students taking graduate version complete additional assignments. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"W41-4101"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.074","terms":["fall"],"rating":5.68,"hours":6.42,"inClassHours":3.14,"outOfClassHours":3.28,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.111","title":"Leadership in Negotiation: Advanced Applications","level":"U","description":"Building on the skills and strategies honed in 11.011, explores advanced negotiation practice. Emphasizes an experiential skill-building approach, underpinned by cutting-edge cases and innovative research. Examines applications in high-stakes management, public policy, social entrepreneurship, international diplomacy, and scientific discovery. Strengthens collaborative decision-making, persuasion, and leadership skills by negotiating across different media and through personalized coaching, enhancing students' ability to proactively engage stakeholders, transform organizations, and inspire communities. Limited by lottery; consult class website for information and deadlines.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"12:00","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.111","terms":["fall"],"rating":6.95,"hours":12.14,"inClassHours":4.29,"outOfClassHours":7.85,"prerequisites":"11.011/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.114","title":"Applied Category Theory for Engineering Design","level":"U","description":"Considers the multiple trade-offs at various abstraction levels and scales when designing complex, multi-component systems. Covers topics from foundational principles to advanced applications, emphasizing the role of compositional thinking in engineering. Introduces category theory as a mathematical framework for abstraction and composition, enabling a unified and modular approach to modeling, analyzing, and designing interconnected systems. Showcases successful applications in areas such as dynamical systems and automated system design optimization, with a focus on autonomous robotics and mobility. Offers students the opportunity to work on their own application through a dedicated project in the second half of the term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-234"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.114","terms":["fall"],"rating":6.5,"hours":8.3,"inClassHours":3.5,"outOfClassHours":4.8,"prerequisites":"(GIR:CAL2, 18.06)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.118","title":"Applied Data Science for Cities","level":"U","description":"Draws on statistics, visualization, and computation to better understand how cities are shaped. Employs a combination of approaches, including qualitative description and quantitative spatial-analysis using R, to create a storytelling approach to cities. Uses data sources, including census data and local administrative data, to describe community characteristics and consider how analysis of quantitative data fits with other forms of data and engagement to fill gaps in knowledge. Students taking graduate version complete additional assignments. Enrollment limited to 30 for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.118","terms":["fall"],"rating":6.8,"hours":8.6,"inClassHours":3.2,"outOfClassHours":5.4,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.122","title":"Law, Technology, and Public Policy","level":"U","description":"Examines how law, economics, and technological change shape public policy, and how law can sway technological change; how the legal system responds to environmental, safety, energy, social, and ethical problems; how law and markets interact to influence technological development; and how law can affect wealth distribution, employment, and social justice. Covers energy/climate change; genetic engineering; telecommunications and role of misinformation; industrial automation; effect of regulation on technological innovation; impacts of antitrust law on innovation and equity; pharmaceuticals; nanotechnology; cost/benefit analysis as a decision tool; public participation in governmental decisions affecting science and technology; corporate influence on technology and welfare; and law and economics as competing paradigms to encourage sustainability. Students taking graduate version explore subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.122","terms":["fall"],"rating":5.89,"hours":10.57,"inClassHours":3.5,"outOfClassHours":7.07,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.124","title":"Introduction to Education: Looking Forward and Looking Back on Education","level":"U","description":"One of two introductory subjects on teaching and learning science and mathematics in a variety of K-12 settings. Topics include education and media, education reform, the history of education, simulations, games, and the digital divide. Students gain practical experience through weekly visits to schools, classroom discussions, selected readings, and activities to develop a critical and broad understanding of past and current forces that shape the goals and processes of education, and explores the challenges and opportunities of teaching. Students work collaboratively and individually on papers, projects, and in-class presentations. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.124","terms":["fall"],"rating":6.07,"hours":9.41,"inClassHours":3.13,"outOfClassHours":6.28,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.129","title":"Educational Theory and Practice I","level":"U","description":"Concentrates on core set of skills and knowledge necessary for teaching in secondary schools. Topics include classroom management, student behavior and motivation, curriculum design, educational reform, and the teaching profession. Classroom observation is a key component. Assignments include readings from educational literature, written reflections on classroom observations, practice teaching and constructing curriculum. The first of the three-course sequence necessary to complete the Teacher Education Program. Limited to 15; preference to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"16:00","end":"17:30","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.129","terms":["fall"],"rating":6.97,"hours":12.71,"inClassHours":3.33,"outOfClassHours":9.38,"prerequisites":"","corequisites":"CMS.586, permission of instructor","recommendedPreparation":""},{"code":"11.138","title":"Crowd Sourced City: Civic Tech Prototyping","level":"U","description":"Investigates the use of social medial and digital technologies for planning and advocacy by working with actual planning and advocacy organizations to develop, implement, and evaluate prototype digital tools. Students use the development of their digital tools as a way to investigate new media technologies that can be used for planning. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.138","terms":["fall"],"rating":4.97,"hours":8.25,"inClassHours":3.0,"outOfClassHours":5.25,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.142","title":"Geography of the Global Economy","level":"U","description":"Analyzes implications of economic globalization for communities, regions, international businesses and economic development organizations. Uses spatial analysis techniques to model the role of energy resources in shaping international political economy. Investigates key drivers of human, physical, and social capital flows and their roles in modern human settlement systems. Surveys contemporary models of industrialization and places them in geographic context. Connects forces of change with their implications for the distribution of wealth and human well-being. Looks backward to understand pre-Covid conditions and then returns to the present to understand how a global pandemic changes the world. Class relies on current literature and explorations of sectors. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.142","terms":["fall"],"rating":5.9,"hours":10.29,"inClassHours":3.0,"outOfClassHours":7.29,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.156","title":"Healthy Cities: Assessing Health Impacts of Policies and Plans","level":"U","description":"Examines the built, psychosocial, economic, and natural environment factors that affect health behaviors and outcomes, including population-level patterns of disease distribution and health disparities. Introduces tools designed to integrate public health considerations into policy-making and planning. Assignments provide students opportunities to develop extensive practical experience bringing a health lens to policy, budgeting, and/or planning debates. Emphasizes health equity and healthy cities, and explores the relationship between health equity and broader goals for social and racial justice. Students taking graduate version complete additional assignments. Limited to 30.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.156","terms":["fall"],"rating":6.43,"hours":9.19,"inClassHours":3.1,"outOfClassHours":6.09,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.158","title":"Behavioral Science, AI, and Urban Mobility","level":"U","description":"Integrates behavioral science, artificial intelligence, and transportation technology to shape travel behavior, design mobility systems and business, and reform transportation policies. Introduces methods to sense travel behavior with new technology and measurements; nudge behavior through perception and preference shaping; design mobility systems and ventures that integrate autonomous vehicles, shared mobility, and public transit; and regulate travel with behavior-sensitive transport policies. Challenges students to pilot behavioral experiments and design creative mobility systems, business and policies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.158","terms":["fall"],"rating":5.76,"hours":7.77,"inClassHours":2.92,"outOfClassHours":4.85,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.164","title":"Human Rights at Home and Abroad","level":"U","description":"Provides a rigorous and critical introduction to the history, foundation, structure, and operation of the human rights movement. Focuses on key ideas, actors, methods and sources, and critically evaluates the field. Addresses current debates in human rights, including the relationship with security, democracy, development and globalization, urbanization, equality (in housing and other economic and social rights; women's rights; ethnic, religious and racial discrimination; and policing/conflict), post-conflict rebuilding and transitional justice, and technology in human rights activism. No prior coursework needed, but work experience, or community service that demonstrates familiarity with global affairs or engagement with ethics and social justice issues, preferred. Students taking graduate version are expected to write a research paper.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.164","terms":["fall"],"rating":6.97,"hours":8.97,"inClassHours":2.97,"outOfClassHours":6.0,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":"No prior coursework needed, but work experience, or community service that demonstrates familiarity with global affairs or engagement with ethics and social justice issues, preferred."},{"code":"11.188","title":"Introduction to Spatial Analysis and GIS Laboratory","level":"U","description":"An introduction to Geographic Information Systems (GIS), a tool for visualizing and analyzing spatial data. Explores how GIS can make maps, guide decisions, answer questions, and advocate for change. Class builds toward a project in which students critically apply GIS techniques to an area of interest. Students build data discovery, cartography, and spatial analysis skills while learning to reflect on their positionality within the research design process. Because maps and data are never neutral, the class incorporates discussions of power, ethics, and data throughout as part of a reflective practice. Instruction and practice in oral and written communication provided.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"3-133"}]},{"type":"Lab","options":[{"days":["F"],"start":"13:00","end":"16:00","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.188","terms":["fall","spring"],"rating":6.52,"hours":9.83,"inClassHours":4.98,"outOfClassHours":4.85,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.200","title":"Gateway: Urban Studies and Planning 1","level":"G","description":"Introduces the theory and practice of planning and urban studies through exploration of the history of the field, case studies, and criticisms of traditional practice.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"W41-1216"}]},{"type":"Recitation","options":[{"days":["R"],"start":"09:00","end":"10:00","room":"W41-1101"},{"days":["R"],"start":"14:30","end":"15:30","room":"W41-1101"},{"days":["R"],"start":"15:30","end":"16:30","room":"W41-1101"},{"days":["F"],"start":"14:30","end":"15:30","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.200","terms":["fall"],"rating":4.97,"hours":10.67,"inClassHours":4.4,"outOfClassHours":6.27,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.205","title":"Introduction to Spatial Analysis and GIS","level":"G","description":"An introduction to Geographic Information Systems (GIS): a tool for visualizing and analyzing data representing locations and their attributes. GIS is invaluable for planners, scholars, and professionals who shape cities and a political instrument with which activists advocate for change. Class includes exercises to make maps, query databases, and analyze spatial data. Because maps and data are never neutral, the class incorporates discussions of power, ethics, and data throughout as part of a reflective practice. Limited enrollment; preference to first-year MCP students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"3-133"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:30","end":"18:30","room":"W41-1219"},{"days":["T"],"start":"16:30","end":"18:30","room":"W41-1219"},{"days":["R"],"start":"16:30","end":"18:30","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.205","terms":["fall","spring"],"rating":5.88,"hours":11.82,"inClassHours":5.95,"outOfClassHours":5.87,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.214","title":"Applied Category Theory for Engineering Design","level":"G","description":"Considers the multiple trade-offs at various abstraction levels and scales when designing complex, multi-component systems. Covers topics from foundational principles to advanced applications, emphasizing the role of compositional thinking in engineering. Introduces category theory as a mathematical framework for abstraction and composition, enabling a unified and modular approach to modeling, analyzing, and designing interconnected systems. Showcases successful applications in areas such as dynamical systems and automated system design optimization, with a focus on autonomous robotics and mobility. Offers students the opportunity to work on their own application through a dedicated project in the second half of the term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-234"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.214","terms":["fall"],"rating":6.5,"hours":8.3,"inClassHours":3.5,"outOfClassHours":4.8,"prerequisites":"(GIR:CAL2, 18.06)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.218","title":"Applied Data Science for Cities","level":"G","description":"Draws on statistics, visualization, and computation to better understand how cities are shaped. Employs a combination of approaches, including qualitative description and quantitative spatial-analysis using R, to create a storytelling approach to cities. Uses data sources, including census data and local administrative data, to describe community characteristics and consider how analysis of quantitative data fits with other forms of data and engagement to fill gaps in knowledge. Students taking graduate version complete additional assignments. Enrollment limited to 30 for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.218","terms":["fall"],"rating":6.8,"hours":8.6,"inClassHours":3.2,"outOfClassHours":5.4,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.220","title":"Quantitative Reasoning and Statistical Methods for Planning I","level":"G","description":"Develops logical, empirically based arguments using statistical techniques and analytic methods. Covers elementary statistics, probability, and other types of quantitative reasoning useful for description, estimation, comparison, and explanation. Emphasizes the use and limitations of analytical techniques in planning practice. Restricted to MCP students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"W41-1306"}]},{"type":"Recitation","options":[{"days":["T"],"start":"15:30","end":"16:30","room":"W41-1119"},{"days":["T"],"start":"17:30","end":"18:30","room":"W41-1119"},{"days":["W"],"start":"13:00","end":"14:00","room":"W41-1119"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.220","terms":["fall"],"rating":4.85,"hours":7.89,"inClassHours":4.0,"outOfClassHours":3.89,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.222","title":"Introduction to Critical Qualitative Methods","level":"G","description":"Introduces qualitative methods as an approach to critical inquiry in urban planning research and practice. Emphasizes the importance of historical context, place-specificity, and the experiences and views of individuals as ways of knowing relationships of power and privilege between people, in place, and over time. Explores a range of critical qualitative methods including those used in archival, interview, observational, visual, and case study analysis.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"W41-1306"}]},{"type":"Recitation","options":[{"days":["T"],"start":"15:30","end":"16:30","room":"W41-1119"},{"days":["T"],"start":"16:30","end":"17:30","room":"W41-1119"},{"days":["T"],"start":"18:00","end":"19:00","room":"W41-3101"},{"days":["F"],"start":"13:30","end":"14:30","room":"W41-4214"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.222","terms":["fall"],"rating":4.93,"hours":7.41,"inClassHours":3.6,"outOfClassHours":3.81,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.229","title":"Wanderings in Psychogeography","level":"G","description":"Discussion-based seminar exploring the history, present, and future landscapes of psychogeography, an invented and inventive inquiry into the interaction of place, memory, experience, and human consciousness. Maps the center and edges of this elusive field and explores potential new directions for the principles discovered or invented in class. Readings include classic and more recent texts, novels, essays, poems, reviews, films, and other works of creative nonfiction and speculative fiction. Students undertake their own psychogeographic wanderings and complete a final 'carto-imagino-synthetic' project to document, describe, map, and otherwise 'make sense of place' through these techniques.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"W41-4507"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.229","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.233","title":"Research Design for Policy Analysis and Planning","level":"G","description":"Develops skills in research design for policy analysis and planning. Emphasizes the logic of the research process and its constituent elements. Topics include philosophy of science, question formulation, hypothesis generation and theory construction, data collection techniques (e.g. experimental, survey, interview), ethical issues in research, and research proposal preparation. Limited to doctoral students in Course 11.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:30","end":"12:30","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.233","terms":["fall"],"rating":5.49,"hours":16.56,"inClassHours":3.2,"outOfClassHours":13.36,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.235","title":"What We Think About When We Think About Cities","level":"G","description":"Using a critical reading of Italo Calvino's Invisible Cities, facilitates a deeper understanding and appreciation of cities and the urban planning and policymaking processes that form them. Concepts such as Kevin Lynch's 'Good City Form' and Henri Lefebvre's 'The Right to the City' ? along with case studies of Boston and Paris, and readings and reflections on a wide range of cities around the world ? are used to approach the overarching and fundamental question of what makes a city. Explores the important roles of historic preservation, urban renewal, and the topic of urban adaptation (particularly in the post-pandemic 21st century context).","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"11:00","room":"W41-5101"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.235","terms":["fall"],"rating":6.4,"hours":5.8,"inClassHours":2.0,"outOfClassHours":3.8,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.236","title":"Participatory Action Research: Theory and Application","level":"G","description":"Provides a comprehensive introduction to core concepts and applications of Participatory Action Research (PAR), an approach to research and inquiry that transforms the traditional 'expert' role by bringing together community, researchers, and academics to investigate important societal problems. Explores theoretical aspects of PAR through the history, aims, ethical concerns, and theoretical and methodological foundations of PAR, while simultaneously building practical applications through core tools and best practices. Students are invited to bring own projects as application cases into the class. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.236","terms":["fall"],"rating":6.4,"hours":5.73,"inClassHours":3.01,"outOfClassHours":2.72,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.242","title":"The Role of History in Planning the Just City","level":"G","description":"Explores a series of diverse urban landscapes as public history, with a focus on cases of African-American landscapes and landscapes of other racial or ethnic minorities and the stories they hold. To deepen an understanding and discussion of these cases, an author/leader of each case joins the class session. Topics include: the relationship between history and memory; as well as how overlooked or silenced histories can be unearthed, honored, and told through urban design and planning.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-4214"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.242","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.250","title":"Transportation Research Design","level":"G","description":"Seminar dissects ten transportation studies from head to toe to illustrate how research ideas are initiated, framed, analyzed, evidenced, written, presented, criticized, revised, extended, and published, quoted and applied. Students learn by mimicking and learn by doing, and design and execute their own transportation research. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:30","end":"11:00","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.250","terms":["fall","spring"],"rating":6.12,"hours":12.33,"inClassHours":1.87,"outOfClassHours":10.46,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.251","title":"Frontier of Transportation Research","level":"G","description":"Surveys the frontier of transportation research offered by 12 MIT faculty presenting their latest findings, ideas, and innovations. Students write weekly memos to reflect on these talks, make connections to their own research, and give short presentations.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"W41-1303"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.251","terms":["fall","spring"],"rating":6.08,"hours":2.15,"inClassHours":1.04,"outOfClassHours":1.11,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.258","title":"Sustainable Urbanization Research Seminar","level":"G","description":"Reviews the seminal as well as latest research on the driving forces of urbanization, real estate markets, urban sustainability in both developed and developing economies. Examines the tensions as well as synergies between urbanization and sustainability, and designs and evaluates policies and business strategies that can enhance the synergies while reduce the tensions. Covers various research topics under the umbrella of urbanization under three modules (sustainable urbanization; sustainable real estate; urbanization in emerging economies) where students study the initiation of an idea to its publication, including but not limited to, analyzing, framing, writing and critiquing as parts of the process. Sessions are organized as a semi-structured dialogue.","groups":[{"type":"Lecture","options":[{"days":["M","F"],"start":"12:30","end":"14:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.258","terms":["fall"],"rating":6.07,"hours":4.41,"inClassHours":2.04,"outOfClassHours":2.37,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.268","title":"Laws of the Land: Land Use and Environmental Law and Policy","level":"G","description":"Environmental justice and climate change are pressing contemporary concerns.  Crucial dimensions of the exposure of households to environmental harms and benefits are determined by land use and environmental laws.  Land use and environmental laws are also central to reducing carbon emissions and building environmentally sustainable and resilient communities.  Introduces students to the legal and social science dimension of these two crucial areas of law that is well-covered in the current curriculum. Enrollment limited to 30.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.268","terms":["fall"],"rating":6.2,"hours":6.8,"inClassHours":3.0,"outOfClassHours":3.8,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.274","title":"Cybersecurity Clinic","level":"G","description":"Provides an opportunity for MIT students to become certified in methods of assessing the vulnerability of public agencies (particularly agencies that manage critical urban infrastructure) to the risk of cyberattack. Certification involves completing an 8-hour, self-paced, online set of four modules during the first four weeks of the semester followed by a competency exam. Students who successfully complete the exam become certified. The certified students work in teams with client agencies in various cities around the United States. Through preparatory interactions with the agencies, and short on-site visits, teams prepare vulnerability assessments that client agencies can use to secure the technical assistance and financial support they need to manage the risks of cyberattack they are facing. Students taking graduate version complete additional assignments. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"W41-4101"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.274","terms":["fall"],"rating":5.68,"hours":6.42,"inClassHours":3.14,"outOfClassHours":3.28,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.305","title":"","level":"G","description":"Seminar studies how the messy and complex forces of politics, planning and the real estate market have collectively shaped Boston's urban fabric and skyline in the last two decades. Using some of the city's most important real estate development proposals as case studies, students dissect and analyze Boston's negotiated development review and permitting process to understand what it takes beyond a great development concept and a sound financial pro forma to earn community and political support. Throughout the term, students identify strategies for success and pitfalls for failure within this intricate approval process, as well as how these lessons can be generalized and applied to other cities and real estate markets.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"18:00","end":"20:00","room":"9-451"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.305","terms":["fall"],"rating":6.5,"hours":3.66,"inClassHours":2.52,"outOfClassHours":1.14,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.309","title":"Sensing Place: Photography as Inquiry","level":"G","description":"Explores photography as a disciplined way of seeing, and as a medium of inquiry and of expressing ideas. Readings, observations, and photographs form the basis of discussions on landscape, light, significant detail, place, poetics, narrative, and how photography can inform research, design and planning, among other issues. Recommended for students who want to employ visual methods in their theses.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"W41-1303"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.309","terms":["fall"],"rating":6.15,"hours":8.38,"inClassHours":3.09,"outOfClassHours":5.29,"prerequisites":"","corequisites":"","recommendedPreparation":"Recommended for students who want to employ visual methods in their theses."},{"code":"11.313","title":"Advanced Research Workshop in Landscape and Urbanism","level":"G","description":"In-depth research workshop on pressing socio-economic and environmental design issue of our time, includes discussion and practices with real-world stakeholders experimenting with new development typologies and technologies. The goal is to generate well-grounded, design-based solutions and landscape infrastructural responses to the physical design problem being addressed. Specific focus and practicum status is adjusted on a year-to-year basis.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"16:00","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.313","terms":["fall"],"rating":6.0,"hours":7.72,"inClassHours":3.11,"outOfClassHours":4.61,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.324","title":"Modeling Pedestrian Activity in Cities","level":"G","description":"Investigates the interaction between pedestrian activity, urban form, and land-use patterns in relatively dense urban environments. Informed by recent literature on pedestrian mobility, behavior, and biases, subject takes a practical approach, using software tools and analysis methods to operationalize and model pedestrian activity. Uses simplified yet powerful and scalable network analysis methods that focus uniquely on pedestrians, rather than engaging in comprehensive travel demand modeling across all modes. Emphasizes not only modeling or predicting pedestrian activity in given built settings, but also analyzing and understanding how changes in the built environment — land use changes, density changes, and connectivity changes — can affect pedestrian activity. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.324","terms":["fall"],"rating":6.07,"hours":9.04,"inClassHours":3.12,"outOfClassHours":5.92,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.325","title":"Technological Change & Innovation for Real Estate and Cities","level":"G","description":"Seeks to examine the technological change and innovation that is disrupting the foundation of how we create the built environment. Through a series of educational workshops, students scout, catalog, and track technologies by looking at new real estate uses, products, processes, and organizational strategies at MIT labs and around the globe. Participants contribute to an interactive web tool, 'The Tech Tracker,' which provides technology intelligence to students and real estate professionals to enhance their understanding of technological progress.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"10:30","end":"12:30","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.325","terms":["fall"],"rating":6.05,"hours":5.18,"inClassHours":2.47,"outOfClassHours":2.71,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.328","title":"Urban Design Skills: Observing, Interpreting, and Representing the City","level":"G","description":"Introduces methods for observing, interpreting, and representing the urban environment. Students draw on their senses and develop their ability to deduce, question, and test conclusions about how the built environment is designed, used, and valued. The interrelationship of built form, circulation networks, open space, and natural systems are a key focus. Supplements existing classes that cover theory and history of city design and urban planning and prepares students without design backgrounds with the fundamentals of physical planning. Intended as a foundation for 11.329.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"13:00","room":"W41-3102"}]},{"type":"Recitation","options":[{"days":["W"],"start":"17:00","end":"19:30","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m11b.html#11.328","terms":["fall"],"rating":5.7,"hours":15.38,"inClassHours":6.76,"outOfClassHours":8.62,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.329","title":"Advanced Urban Design Skills: Observing, Interpreting, and Representing the City","level":"G","description":"Through a studio-based course in planning and urban design, builds on the foundation acquired in 11.328 to engage in creative exploration of how design contributes to resilient, just, and vibrant urban places. Through the planning and design of two projects, students creatively explore spatial ideas and utilize various digital techniques to communicate their design concepts, giving form to strategic thinking. Develops approaches and techniques to evaluate the plural structure of the built environment and offer propositions that address policies and regulations as well as the values, behaviors, and wishes of the different users.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"13:00","room":"W41-3102"}]},{"type":"Recitation","options":[{"days":["W"],"start":"17:00","end":"19:30","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.329","terms":["fall"],"rating":6.1,"hours":15.37,"inClassHours":6.81,"outOfClassHours":8.56,"prerequisites":"11.328/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.332","title":"Urban Design Studio","level":"G","description":"The design of urban environments. Strategies for change in large areas of cities, to be developed over time, involving different actors. Fitting forms into natural, man-made, historical, and cultural contexts; enabling desirable activity patterns; conceptualizing built form; providing infrastructure and service systems; guiding the sensory character of development. Involves architecture and planning students in joint work; requires individual designs or design and planning guidelines.","groups":[{"type":"Design","options":[{"days":["T","F"],"start":"13:00","end":"17:00","room":"W41-5219"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.332","terms":["fall","spring"],"rating":3.8,"hours":22.3,"inClassHours":8.14,"outOfClassHours":14.16,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.345","title":"Entrepreneurship in the Built Environment","level":"G","description":"Introduction to entrepreneurship and how it shapes the world we live in. Through experiential learning in a workshop setting, students start to develop entrepreneurial mindset and skills. Through a series of workshops, students are introduced to the concept of Venture Design to create new venture proposals for the built environment as a method to understand the role of the entrepreneur in the fields of design, planning, real estate, and other related industries.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"11:00","room":"W41-1401"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.345","terms":["fall"],"rating":6.48,"hours":5.21,"inClassHours":2.14,"outOfClassHours":3.07,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.348","title":"Urbanism Proseminar: Theory and Representation","level":"G","description":"Critical introduction to key contemporary positions in urbanism to the ends of researching, representing, and designing territories that respond to the challenges of the 21st century. Provides an overview of contemporary urban issues, situates them in relation to a genealogy of urban precedents, and constructs a theoretical framework that engages the allied fields of architecture, landscape architecture, political ecology, geography, territorial planning, and environmental humanities. Comprised of three sections, first section articulates a framework on the urban as both process and form, shifting the emphasis from city to territory. Second section engages a series of related urban debates, such as density/sprawl, growth/shrinkage, and codes/exception. Third section calls upon urban agency in the age of environment through the object of infrastructures of trash, water, oil, and food. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:30","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.348","terms":["fall"],"rating":6.37,"hours":14.67,"inClassHours":3.07,"outOfClassHours":11.6,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.351","title":"Real Estate Ventures I: Negotiating Development-Phase Agreements","level":"G","description":"Focuses on key business and legal issues within the principal agreements used to control, entitle, capitalize, and construct a mixed-use real estate development. Through the lens of the real estate developer and its counter-parties, students identify, discuss, and negotiate the most important business issues in right of entry, purchase and sale, development, and joint-venture agreements, as well as a construction contract and construction loan agreement. Students work closely with attorneys who specialize in the construction of such agreements and with students from area law schools and Columbia University and New York University. Enrollment limited to approximately 25; preference to MSRED students. No listeners.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"18:00","end":"21:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.351","terms":["fall"],"rating":6.79,"hours":11.41,"inClassHours":3.09,"outOfClassHours":8.32,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.356","title":"Healthy Cities: Assessing Health Impacts of Policies and Plans","level":"G","description":"Examines the built, psychosocial, economic, and natural environment factors that affect health behaviors and outcomes, including population-level patterns of disease distribution and health disparities. Introduces tools designed to integrate public health considerations into policy-making and planning. Assignments provide students opportunities to develop experience bringing a health lens to policy, budgeting, and/or planning debates. Emphasizes health equity and healthy cities, and explores the relationship between health equity and broader goals for social and racial justice. Students taking graduate version complete additional assignments. Limited to 30.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.356","terms":["fall"],"rating":6.43,"hours":9.19,"inClassHours":3.1,"outOfClassHours":6.09,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.360","title":"Community Growth and Land Use Planning","level":"G","description":"Seminar, workshops, and fieldwork on strategies to use municipal land use regulations to shape urban growth and equity. Practicum workshop builds skills in civic engagement, policy-relevant research, zoning regulations, and physical design and planning. The workshop begins with implementation of qualitative and quantitative research into the existing built environment, social, economic, and political context. It continues with the planning, design, and implementation of community engagement strategies to shape goals and vision for the projects. The practicum then explores land use scenarios, design and innovative zoning and regulatory techniques, to improve equity in the areas of housing, environment, economic development, mobility, and the public realm. Projects arranged with small teams serving municipal clients experiencing pressures of urban growth and change in Massachusetts. Preference to MCP second year students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"W41-4101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.360","terms":["fall"],"rating":5.99,"hours":9.08,"inClassHours":3.15,"outOfClassHours":5.93,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.362","title":"Securing Community Voice and Narrative in Times of Repression","level":"G","description":"Delves into how marginalized communities, individuals, and identities adapt mainstream media and communication tools and strategies to preserve their collective voice amidst repression. Explores various global movement areas and examines real-world examples and cases that illustrate these adaptations. Provides an overview of community narrative and storytelling methods, which are crucial for effective planning. Students engage in group projects that enhance their skills in designing narrative strategies. Students taking the graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"W41-2101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.362","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.371","title":"Sustainable Energy","level":"G","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal) energy types, along with storage, transmission, and conservation issues. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"10-250"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.371","terms":["fall"],"rating":5.65,"hours":8.07,"inClassHours":3.13,"outOfClassHours":4.94,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.381","title":"Infrastructure Systems in Theory and Practice","level":"G","description":"Examines theories of infrastructure from science and technology studies, history, economics, and anthropology in order to understand the prospects for change for many new and existing infrastructure systems. Examines how these theories are then implemented within systems in the modern city, including but not limited to, energy, water, transportation, and telecommunications infrastructure. Seminar is conducted with intensive group research projects, in-class discussions and debates.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"12:00","room":"W41-4519"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.381","terms":["fall"],"rating":6.57,"hours":11.9,"inClassHours":3.0,"outOfClassHours":8.9,"prerequisites":"(14.01, (11.202/11.203))/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.383","title":"People and Profits: Shaping  the Future of Work","level":"G","description":"Examines managing work in the 21st century in the interests of both people and profits through the context of rising inequality, technological change, globalization, and the growth of the gig economy. Students evaluate various business and policy interventions intended to improve work through critical analysis of the evidence, interviews with workers and evaluations of firms, and guest speakers. Guests include business leaders at leading-edge firms and labor leaders experimenting with new ways of providing workers a voice in the workplace. Draws on materials from the MIT Task Force on Work of the Future and the online course Shaping Work of the Future.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-315"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-233"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.383","terms":["fall"],"rating":6.37,"hours":6.16,"inClassHours":3.03,"outOfClassHours":3.13,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.401","title":"Introduction to Housing, Community, and Economic Development","level":"G","description":"Provides a critical introduction to the shape and determinants of political, social, and economic inequality in America, with a focus on racial and economic justice. Explores the role of the city in visions of justice. Analyzes the historical, political, and institutional contexts of housing and community development policy in the US, including federalism, municipal fragmentation, and decentralized public financing. Introduces major dimensions in US housing policy, such as housing finance, public housing policy, and state and local housing affordability mechanisms. Reviews major themes in community economic development, including drivers of economic inequality, small business policy, employment policy, and cooperative economics. Expectations and evaluation criteria differ for students taking graduate version.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.401","terms":["fall"],"rating":6.54,"hours":8.45,"inClassHours":3.13,"outOfClassHours":5.32,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.408","title":"Housing and Racial Capitalism","level":"G","description":"Examines critical issues in US housing (most notably, gentrification) through the lens of Black Marxist thought. Introduces core writings on racial capitalism. Explores the material and ideological bases of class relations as enacted through housing. Contrasts these class relations with those of production by highlighting class struggle between groups of residents. Relates these ideas to alternative theories of development and the urban process. Discusses these issues in the context of gentrification and other topics, including suburbanization, infrastructure investment, public and private disinvestment, and predatory inclusion. Offers grounding in classic theoretical accounts of racial capitalism and of the urban process, a framework for bringing to bear the former upon the latter, and insight into the unique role of housing in the social reproduction of a White Middle Class.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"12:30","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.408","terms":["fall"],"rating":7.0,"hours":12.7,"inClassHours":3.0,"outOfClassHours":9.7,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.409","title":"The Institutions of Modern Capitalism: States and Markets","level":"G","description":"Investigates the relationship between states and markets in the evolution of modern capitalism. Critically assesses the rise of what Karl Polanyi and Albert Hirschman have referred to as 'market society:' a powerful conceptual framework that views the development of modern capitalism not as an outcome of deterministic economic and technological forces, but rather as the result of contingent social and political processes. Exposes students to a range of conceptual tools and analytic frameworks through which to understand the politics of economic governance and to consider the extent to which societal actors can challenge its limits and imagine alternative possibilities. Sub-themes vary from year to year and have focused on racial capitalism, markets and morality, urban futures, and the global financial crisis. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"16:00","room":"W41-1303"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.409","terms":["fall"],"rating":6.58,"hours":10.2,"inClassHours":2.15,"outOfClassHours":8.05,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.422","title":"Law, Technology, and Public Policy","level":"G","description":"Examines how law, economics, and technological change shape public policy, and how law can sway technological change; how the legal system responds to environmental, safety, energy, social, and ethical problems; how law and markets interact to influence technological development; and how law can affect wealth distribution, employment, and social justice. Covers energy/climate change; genetic engineering; telecommunications and the role of misinformation; industrial automation; effect of regulation on technological innovation; impacts of antitrust law on innovation and equity; pharmaceuticals; nanotechnology; cost/benefit analysis as a decision tool; public participation in governmental decisions affecting science and technology; corporate influence on technology and welfare; and law and economics as competing paradigms to encourage sustainability. Students taking graduate version explore subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.422","terms":["fall"],"rating":5.89,"hours":10.57,"inClassHours":3.5,"outOfClassHours":7.07,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.427","title":"Labor Markets and Employment Policy","level":"G","description":"Research-based examination of how labor markets work — and how they have evolved over time — through trends such as rising income inequality, technological change, globalization, falling worker power, and the fissuring of the workplace. Through reading and engaging with economics research papers, students use theoretical frameworks and rigorous empirical evidence to analyze public policy interventions in the labor market, including unemployment insurance, minimum wage, unions, family leave, anti-discrimination policies, and workforce development. Preference to graduate and PhD students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"16:00","room":"E62-346"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.427","terms":["fall"],"rating":6.88,"hours":7.44,"inClassHours":3.06,"outOfClassHours":4.38,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.428","title":"PropTech Ventures","level":"G","description":"Showcases the real estate technology, or PropTech, landscape, through the presentation of recent disruptions in the real estate industry. Through a better understanding of the sector, students begin to develop entrepreneurial ideas and skills necessary to produce the PropTech ventures of the future. Focuses on PropTech that improves the way we buy, rent, sell, manage, construct, and design real estate to help make better investment and development decisions.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"11:00","end":"12:30","room":"3-133"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.428","terms":["fall"],"rating":6.07,"hours":4.37,"inClassHours":2.4,"outOfClassHours":1.97,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.431","title":"Real Estate Finance and Investment","level":"G","description":"Concepts and techniques for analyzing financial decisions in commercial property development and investment. Topics include property income streams, discounted cash flow, equity valuation, leverage and income tax considerations, development projects, and joint ventures. An introduction to real estate capital markets as a source of financing is also provided. Limited to graduate students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"9-354"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.431","terms":["fall"],"rating":5.01,"hours":7.96,"inClassHours":3.78,"outOfClassHours":4.18,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.433","title":"Real Estate Economics","level":"G","description":"Develops an understanding of the fundamental economic factors that shape the market for real property, as well as the influence of capital markets in asset pricing. Analyzes of housing as well as commercial real estate. Covers demographic analysis, regional growth, construction cycles, urban land markets, and location theory as well as recent technology impacts. Exercises and modeling techniques for measuring and predicting property demand, supply, vacancy, rents, and prices.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"9-354"}]},{"type":"Recitation","options":[{"days":["W"],"start":"16:30","end":"18:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.433","terms":["fall"],"rating":6.3,"hours":9.53,"inClassHours":4.09,"outOfClassHours":5.44,"prerequisites":"14.01/15.010/15.011","corequisites":"","recommendedPreparation":""},{"code":"11.442","title":"Geography of the Global Economy","level":"G","description":"Analyzes implications of economic globalization for communities, regions, international businesses and economic development organizations. Uses spatial analysis techniques to model the role of energy resources in shaping international political economy. Investigates key drivers of human, physical, and social capital flows and their roles in modern human settlement systems. Surveys contemporary models of industrialization and places them in geographic context. Connects forces of change with their implications for the distribution of wealth and human well-being. Looks backward to understand pre-Covid conditions and then returns to the present to understand how a global pandemic changes the world. Class relies on current literature and explorations of sectors. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.442","terms":["fall"],"rating":5.9,"hours":10.3,"inClassHours":3.0,"outOfClassHours":7.3,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.450","title":"Real Estate Development Building Systems","level":"G","description":"Provides students with a concise overview of the range of building systems that are encountered in professional commercial real estate development practice in the USA. Focuses on the relationship between real estate product types, building systems, and the factors that real estate development professionals must consider when evaluating these products and systems for a specific development project. Surveys commercial building technology including Foundation, Structural, MEP/FP, Envelope, and Interiors systems and analyzes the factors that lead development professionals to select specific systems for specific product types. One or more field trips to active construction sites may be scheduled during non-class hours based on student availability.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"18:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.450","terms":["fall"],"rating":5.3,"hours":2.5,"inClassHours":2.12,"outOfClassHours":0.38,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.458","title":"Crowd Sourced City: Civic Tech Prototyping","level":"G","description":"Investigates the use of social medial and digital technologies for planning and advocacy by working with actual planning and advocacy organizations to develop, implement, and evaluate prototype digital tools. Students use the development of their digital tools as a way to investigate new media technologies that can be used for planning. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.458","terms":["fall"],"rating":4.97,"hours":8.27,"inClassHours":3.0,"outOfClassHours":5.27,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.466","title":"Technology, Globalization, and Sustainable Development","level":"G","description":"Investigates sustainable development, taking a broad view to include not only a healthy economic base, but also a sound environment, stable and rewarding employment, adequate purchasing power and earning capacity, distributional equity, national self-reliance, and maintenance of cultural integrity. Explores national, multinational, and international political and legal mechanisms to further sustainable development through transformation of the industrial state. Addresses the importance of technological innovation and the financial crisis of 2008 and the emergence of the Covid-19 pandemic, Russia's invasion of Ukraine, and inflation, as well as governmental interventions to reduce inequality.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"18:30","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.466","terms":["fall"],"rating":5.58,"hours":8.25,"inClassHours":2.62,"outOfClassHours":5.63,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.472","title":"D-Lab: Development","level":"G","description":"Issues in international development, appropriate technology and project implementation addressed through lectures, case studies, guest speakers and laboratory exercises. Students form project teams to partner with community organizations in developing countries, and formulate plans for an optional IAP site visit. (Previous field sites include Ghana, Brazil, Honduras and India.) Recitation sections focus on specific project implementation, and include cultural, social, political, environmental and economic overviews of the target countries as well as an introduction to the local languages. Enrollment limited by lottery; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.472","terms":["fall"],"rating":6.37,"hours":12.05,"inClassHours":5.16,"outOfClassHours":6.89,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.478","title":"Behavioral Science, AI, and Urban Mobility","level":"G","description":"Integrates behavioral science, artificial intelligence, and transportation technology to shape travel behavior, design mobility systems and business, and reform transportation policies. Introduces methods to sense travel behavior with new technology and measurements; nudge behavior through perception and preference shaping; design mobility systems and ventures that integrate autonomous vehicles, shared mobility, and public transit; and regulate travel with behavior-sensitive transport policies. Challenges students to pilot behavioral experiments and design creative mobility systems, business and policies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.478","terms":["fall"],"rating":5.76,"hours":7.77,"inClassHours":2.92,"outOfClassHours":4.85,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.485","title":"Southern Urbanisms","level":"G","description":"Guides students in examining implicit and explicit values of diversity offered in 'Southern' knowledge bases, theories, and practices of urban production. With a focus on Sub-Saharan Africa, considers why the South-centered location of the estimated global urban population boom obligates us to examine how cities work as they do, and why Western-informed urban theory and planning scholarship may be ill-suited to provide guidance on urban development there. Examines the 'rise of the rest' and its implications for the making and remaking of expertise and norms in planning practice. Students engage with seminal texts from leading authors of Southern urbanism and critical themes, including the rise of Southern theory, African urbanism, Chinese international cooperation, Brazilian urban diplomacy, and the globally-driven commodification of urban real estate.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.485","terms":["fall"],"rating":6.59,"hours":8.26,"inClassHours":2.17,"outOfClassHours":6.09,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.493","title":"Property and Land Use Law for Planners","level":"G","description":"Examines legal and institutional arrangements for the establishment, transfer, and control over property and land under American and selected comparative systems, including India and South Africa. Focuses on key issues of property and land use law regarding planning and economic development. Emphasizes just and efficient resource use; institutional, entitlement and social relational approaches to property; distributional and other social aspects; and the relationship between property, culture, and democracy.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.493","terms":["fall"],"rating":6.94,"hours":12.85,"inClassHours":3.0,"outOfClassHours":9.85,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.497","title":"Human Rights at Home and Abroad","level":"G","description":"Provides a rigorous and critical introduction to the history, foundation, structure, and operation of the human rights movement. Focuses on key ideas, actors, methods and sources, and critically evaluates the field. Addresses current debates in human rights, including the relationship with security, democracy, development and globalization, urbanization, equality (in housing and other economic and social rights; women's rights; ethnic, religious and racial discrimination; and policing/conflict), post-conflict rebuilding and transitional justice, and technology in human rights activism. Students taking graduate version expected to write a research paper.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.497","terms":["fall"],"rating":6.97,"hours":8.97,"inClassHours":2.97,"outOfClassHours":6.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.520","title":"Workshop on Geographic Information Systems (GIS)","level":"G","description":"Includes spatial analysis exercises using real-world data sets, building toward an independent project in which students critically apply GIS techniques to an area of interest. Students build data discovery, cartography, and spatial analysis skills while learning to reflect on power and positionality within the research design process. Tailored to GIS applications within planning and design and emphasizes the role of reflective practice in GIS. Enrollment limited; preference to MCP students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"3-133"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:30","end":"18:30","room":"W41-1219"},{"days":["T"],"start":"16:30","end":"18:30","room":"W41-1219"},{"days":["R"],"start":"16:30","end":"18:30","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.520","terms":["fall","spring"],"rating":6.21,"hours":9.11,"inClassHours":4.64,"outOfClassHours":4.47,"prerequisites":"11.205/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.529","title":"Mobility Ventures: Driving Innovation in Transportation Systems","level":"G","description":"Explores technological, behavioral, policy, and systems-wide frameworks for innovation in transportation systems, complemented with case studies across the mobility spectrum, from autonomous vehicles to urban air mobility to last-mile sidewalk robots. Students interact with a series of guest lecturers from CEOs and other business and government executives who are actively reshaping the future of mobility. Interdisciplinary teams of students collaborate to deliver business plans for proposed mobility-focused startups with an emphasis on primary market research. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.529","terms":["fall"],"rating":5.82,"hours":6.38,"inClassHours":3.03,"outOfClassHours":3.35,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.540","title":"Urban Transportation Planning and Policy","level":"G","description":"Examines transportation policymaking and planning; its relationship to social and environmental justice; and the influences of politics, governance structures, and human and institutional behavior. Explores the pathway to infrastructure, how attitudes are influenced, and how change happens. Examines the tensions and potential synergies among traditional transportation policy values of individual mobility, system efficiency, and 'sustainability.' Explores the roles of the government; analysis of current trends; transport sector decarbonization; land use, placemaking, and sustainable mobility networks; the role of 'mobility as a service;' and the implications of disruptive technology on personal mobility. Assesses traditional planning methods with a critical eye, and through that process considers how to approach transportation planning in a way that responds to contemporary needs and values, with an emphasis on transport justice.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.540","terms":["fall"],"rating":6.23,"hours":8.76,"inClassHours":3.03,"outOfClassHours":5.73,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.601","title":"Theory and Practice of Environmental Planning","level":"G","description":"Required introductory subject for graduate students pursuing the Environmental Planning Certificate. Strongly suggested for MCP students pursuing EPP as their specialization. Also open to other graduate students interested in environmental justice, environmental ethics, environmental dispute resolution, and techniques of environmental problem-solving. Taught comparatively, with numerous references to examples from around the world. Four major areas of focus: national environmental policymaking, environmental ethics, environmental forecasting and analysis techniques, and strategies for collaborative decision-making.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"W41-5101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.601","terms":["fall"],"rating":6.05,"hours":9.95,"inClassHours":3.89,"outOfClassHours":6.06,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.912","title":"Advanced Urbanism Colloquium","level":"G","description":"Introduces critical theories and contemporary practices in the field of urbanism that challenge its paradigms and advance its future. Includes theoretical linkages between ideas about the cultures of urbanization, social and political processes of development, environmental tradeoffs of city making, and the potential of design disciplines to intervene to change the future of built forms. Events and lecture series co-organized by faculty and doctoral students further engage and inform research. Preference to doctoral students in the Advanced Urbanism concentration.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:00","end":"13:30","room":"W41-4101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.912","terms":["fall","spring"],"rating":6.79,"hours":4.29,"inClassHours":2.08,"outOfClassHours":2.21,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.919","title":"PhD Workshop","level":"G","description":"The workshop features doctoral student progress on dissertation formulation and findings across all years, panels of particular interest to doctoral students as identified by their representatives on the PhD Committee, and an intellectual space for the sharing of ideas and initiatives within the doctoral community and across the department, including faculty.  Limited to all doctoral students in residence.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"10:30","room":"W41-1303"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.919","terms":["fall","spring"],"rating":5.47,"hours":2.2,"inClassHours":1.27,"outOfClassHours":0.93,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.930","title":"Advanced Seminar on Planning Theory","level":"G","description":"Introduces students to key debates in the field of planning theory, drawing on historical development of the field of urban/regional/national planning from 1900 to 2020 in both the US and in newly industrializing countries. Class objectives are for students to develop their own theory of action as they become sensitized to issues of racial and gender discrimination in city building, and understand how planning styles are influenced by a range of issues, including the challenge of ethical practice.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"W41-4519"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.930","terms":["fall"],"rating":5.8,"hours":11.8,"inClassHours":3.0,"outOfClassHours":8.8,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.S195","title":"Special Subject: Urban Studies and Planning","level":"U","description":"For undergraduates wishing to pursue further study or fieldwork in specialized areas of urban studies or city and regional planning not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.S199","terms":["fall"],"rating":6.89,"hours":7.05,"inClassHours":2.72,"outOfClassHours":4.33,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.S938","title":"Special Subject: Urban Studies and Planning","level":"G","description":"For graduate students wishing to pursue further study in advanced areas of urban studies and planning not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:00","end":"14:00","room":"W41-5101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S938","terms":["fall","spring"],"rating":6.29,"hours":6.23,"inClassHours":2.74,"outOfClassHours":3.49,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.S939","title":"Special Subject: Urban Studies and Planning","level":"G","description":"For graduate students wishing to pursue further study in advanced areas of urban studies and city and regional planning not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-4214"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S939","terms":["fall"],"rating":6.13,"hours":7.6,"inClassHours":4.03,"outOfClassHours":3.57,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"11.S945","title":"Special Subject: Urban Studies and Planning","level":"G","description":"For graduate students wishing to pursue further study in advanced areas of urban studies and city and regional planning not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S945-11.S949","terms":["fall"],"rating":6.48,"hours":8.11,"inClassHours":3.0,"outOfClassHours":5.11,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.S946","title":"Special Subject: Urban Studies and Planning","level":"G","description":"For graduate students wishing to pursue further study in advanced areas of urban studies and city and regional planning not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:30","end":"20:00","room":"E38-579"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S945-11.S949","terms":["fall"],"rating":6.36,"hours":7.59,"inClassHours":3.03,"outOfClassHours":4.56,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.S947","title":"Special Subject: Urban Studies and Planning","level":"G","description":"For graduate students wishing to pursue further study in advanced areas of urban studies and city and regional planning not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"10:00","end":"12:00","room":"W41-5101"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S945-11.S949","terms":["fall"],"rating":6.2,"hours":8.93,"inClassHours":3.0,"outOfClassHours":5.93,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.S965","title":"Special Subject: Real Estate","level":"G","description":"Small group study of advanced subjects under staff supervision. For graduate students wishing to pursue further study in advanced areas of real estate not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"18:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S965","terms":["fall"],"rating":6.17,"hours":3.88,"inClassHours":2.87,"outOfClassHours":1.01,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.S967","title":"Special Subject: Real Estate","level":"G","description":"Small group study of advanced subjects under staff supervision. For graduate students wishing to pursue further study in advanced areas of real estate not covered in regular subjects of instruction.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"12:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S967","terms":["fall"],"rating":6.51,"hours":7.44,"inClassHours":3.05,"outOfClassHours":4.39,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.S969","title":"Special Seminar: Real Estate","level":"G","description":"Small group study of advanced subjects under staff supervision. For graduate students wishing to pursue further study in advanced areas of real estate not covered in regular subjects of instruction.","groups":[{"type":"Design","options":[{"days":["T"],"start":"16:00","end":"19:00","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.S969","terms":["fall","spring"],"rating":5.94,"hours":3.79,"inClassHours":2.18,"outOfClassHours":1.61,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.THG","title":"Graduate Thesis","level":"G","description":"Program of research and writing of thesis; to be arranged by the student with supervising committee.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:30","end":"11:00","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m11c.html#11.THG","terms":["fall","spring"],"rating":4.44,"hours":5.55,"inClassHours":1.16,"outOfClassHours":4.39,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"11.THT","title":"Thesis Research Design Seminar","level":"U","description":"Designed for students writing a thesis in Urban Studies and Planning or Architecture. Develop research topics, review relevant research and scholarship, frame research questions and arguments, choose an appropriate methodology for analysis, and draft introductory and methodology sections.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m11a.html#11.THT","terms":["fall"],"rating":3.75,"hours":10.11,"inClassHours":2.92,"outOfClassHours":7.19,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.000","title":"Solving Complex Problems","level":"U","description":"Provides an opportunity for entering freshmen to gain firsthand experience in integrating the work of small teams to develop effective solutions to complex problems in Earth system science and engineering. Each year's class explores a different problem in detail through the study of complementary case histories and the development of creative solution strategies. Includes exercises in website development, written and oral communication, and team building. Subject required for students in the Terrascope freshman program, but participation in Terrascope is not required of all 12.000 students. Students who pass 12.000 are eligible to participate in the Terrascope field trip the following spring. Limited to freshmen.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"15:30","room":"55-108"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.000","terms":["fall","spring"],"rating":5.26,"hours":6.0,"inClassHours":2.94,"outOfClassHours":3.06,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.001","title":"Introduction to Geology","level":"U","description":"Major minerals and rock types, rock-forming processes, and time scales. Temperatures, pressures, compositions, structure of the Earth, and measurement techniques. Geologic structures and relationships observable in the field. Sediment movement and landform development by moving water, wind, and ice. Crustal processes and planetary evolution in terms of global plate tectonics with an emphasis on ductile and brittle processes. Includes laboratory exercises on minerals, rocks, mapping, plate tectonics, rheology, glaciers. Two one-day field trips (optional).","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"54-819"}]},{"type":"Lab","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"54-819"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.001","terms":["fall"],"rating":6.29,"hours":10.82,"inClassHours":6.29,"outOfClassHours":4.53,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.004","title":"Introduction to the Global Carbon Cycle","level":"U","description":"Introduction to the chemical and biological mechanisms controlling Earth's global carbon and related elemental cycles across atmospheric, aquatic, and terrestrial systems. Fundamental principles of redox, equilibria, and acid/base reactions are explored via their links in the Earth system and with respect to climate feedbacks and ecosystem dynamics, providing perspectives for climate interventions and the future of our planet. Students create individual 'toy' global carbon cycle models to investigate how natural and anthropogenic perturbations to the carbon cycle modify Earth's climate.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"54-819"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.004","terms":["fall"],"rating":6.1,"hours":8.8,"inClassHours":3.0,"outOfClassHours":5.8,"prerequisites":"GIR:CHEM","corequisites":"","recommendedPreparation":""},{"code":"12.006","title":"Nonlinear Dynamics: Chaos","level":"U","description":"Introduction to nonlinear dynamics and chaos in dissipative systems. Forced and parametric oscillators. Phase space. Periodic, quasiperiodic, and aperiodic flows. Sensitivity to initial conditions and strange attractors. Lorenz attractor. Period doubling, intermittency, and quasiperiodicity. Scaling and universality. Analysis of experimental data: Fourier transforms, Poincare sections, fractal dimension, and Lyapunov exponents. Applications to mechanical systems, fluid dynamics, physics, geophysics, and chemistry. See 12.207J/18.354J for Nonlinear Dynamics: Continuum Systems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-361"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.006","terms":["fall"],"rating":6.01,"hours":9.5,"inClassHours":2.81,"outOfClassHours":6.69,"prerequisites":"GIR:PHY2, (18.03/18.032)","corequisites":"","recommendedPreparation":""},{"code":"12.010","title":"Computational Methods of Scientific Programming","level":"U","description":"Introductory subject exposes students to modern programming methods and techniques used in practice by physical scientists today. Emphasis on code design, algorithm development/verification, and comparative advantages/disadvantages of different languages (including Python, Julia and C/C++) and tools (including Jupyter, machine-learning from data or models, cloud and high-performance computing workflows). Students are introduced to and work with common programming tools, types of problems, and techniques for solving a variety of data analytic and equation modeling scenarios from real research: examination visualization techniques; basic numerical analysis; methods of dissemination and verification; practices for reproducible work, version control, documentation, and sharing/publication. No prior programming experience is required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"54-517"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.010","terms":["fall"],"rating":6.17,"hours":7.87,"inClassHours":3.01,"outOfClassHours":4.86,"prerequisites":"GIR:CAL2, GIR:PHY1","corequisites":"","recommendedPreparation":""},{"code":"12.012","title":"MatLab, Statistics, Regression, Signal Processing","level":"U","description":"Introduces the basic tools needed for data analysis and interpretation in the Geosciences, as well as other sciences. Composed of four modules, targeted at introducing students to the basic concepts and applications in each module. MatLab: Principles and practice in its uses, script and function modules, basic approaches to solving problems. Statistics: Correlation, means, dispersion, precision, accuracy, distributions, central limit theorem, skewness, probability, Chi-Square, Gaussian and other common distributions used in hypothesis testing. Regression: Random and grid search methods, basic least squares and algorithms applicable to regression, inversion and parameter estimation. Signal Processing: Analog and digital signals, Z-transform, Fourier series, fast Fourier transforms, spectral analysis leakage and bias, digital filtering. Students taking the graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"54-517"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.012","terms":["fall"],"rating":6.34,"hours":15.46,"inClassHours":5.35,"outOfClassHours":10.11,"prerequisites":"","corequisites":"18.06","recommendedPreparation":""},{"code":"12.031","title":"Fundamentals of Ecology","level":"U","description":"Fundamentals of ecology, considering Earth as an integrated dynamic living system. Coevolution of the biosphere and geosphere, biogeochemical cycles, metabolic diversity, primary productivity, competition and the niche, trophic dynamics and food webs, population growth and limiting factors. Population modeling, global carbon cycle, climate change, geoengineering, theories of resource competition and mutualism, allometric scaling, ecological genomics, niche theory, human population growth. Applied ecology.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"48-316"}]},{"type":"Recitation","options":[{"days":["M"],"start":"15:00","end":"16:00","room":"48-316"},{"days":["F"],"start":"11:00","end":"12:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.031","terms":["fall"],"rating":6.18,"hours":7.11,"inClassHours":3.44,"outOfClassHours":3.67,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.031A","title":"Fundamentals of Ecology I","level":"U","description":"Fundamentals of ecology, considering Earth as an integrated dynamic living system. Coevolution of the biosphere and geosphere, biogeochemical cycles, metabolic diversity, primary productivity, competition and the niche, trophic dynamics and food webs, population growth and limiting factors. Combination of 1.018A and 1.018B counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"1-242"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"48-316"},{"days":["R"],"start":"16:00","end":"17:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.031A","terms":["fall"],"rating":5.06,"hours":9.07,"inClassHours":4.06,"outOfClassHours":5.01,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.031B","title":"Fundamentals of Ecology II","level":"U","description":"Advanced topics in Ecology. Population modeling, global carbon cycle, climate change, geoengineering, theories of resource competition and mutualism, allometric scaling, ecological genomics, niche theory, human population growth. Applied ecology. Combination of 1.018A and 1.018B counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"1-242"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"48-316"},{"days":["R"],"start":"16:00","end":"17:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.031B","terms":["fall"],"rating":5.7,"hours":8.94,"inClassHours":4.27,"outOfClassHours":4.67,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.178","title":"The Phylogenomic Planetary Record","level":"U","description":"Introduces the tools of sequence-based phylogenetic analysis and molecular evolution in the context of studying events in Earth's deep past that have been preserved by genomes. Topics include basic concepts of cladistics, phylogeny and sequence evolution, construction of phylogenetic trees of genes and microbial lineages, molecular clocks, dating, and ancestral sequence reconstruction. Special attention to the evolutionary history of microbial metabolisms and their relationship to global biogeochemical cycles across Earth's history. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-1623"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.178","terms":["fall"],"rating":6.94,"hours":9.9,"inClassHours":3.1,"outOfClassHours":6.8,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.203","title":"Mechanics of Earth","level":"U","description":"Covers topics in the deformation and fracture of solids and the flow of viscous fluids. Explores spatial scales from molecular to planetary, and time scales from fractions of a second to millions of years, to understand how and why natural materials on Earth and other terrestrial bodies respond to applied forces. Introduces anelasticity, granular mechanics, poroelasticity, rate-and-state friction, transport properties of Earth materials (Darcy's law, Fick's law), brittle-ductile transitions, creep of polycrystalline materials, stored energy and dissipation, and convection. Prepares students to gather, analyze and interpret data using existing theoretical models. Through a significant laboratory component, students obtain practical experience with experimental measurements and test their acquired theoretical knowledge. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"12:00","room":"54-819"}]},{"type":"Lab","options":[{"days":["M"],"start":"09:00","end":"11:00","room":"54-819"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.203","terms":["fall"],"rating":6.96,"hours":12.08,"inClassHours":4.96,"outOfClassHours":7.12,"prerequisites":"GIR:CAL2, GIR:PHY1","corequisites":"","recommendedPreparation":"Through a significant laboratory component, students obtain practical experience with experimental measurements and test their acquired theoretical knowledge."},{"code":"12.214","title":"Essentials of Field Geophysics","level":"U","description":"Introduces students to the practical field application of various geophysical methods to the study of Earth's near-surface. Prepares students to undertake fieldwork that uses these methods. Designed to prepare students to continue their studies in geophysics and data analysis. The methods covered vary and may include: measuring seismic waves, gravity, precise positions (commonly referred to as GPS, but formally known as GNSS), and topography using drones. Lab time devoted to local fieldwork to gain experience with the methods being taught and to prepare for field geophysics. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"54-819"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.214","terms":["fall"],"rating":6.8,"hours":6.3,"inClassHours":4.5,"outOfClassHours":1.8,"prerequisites":"GIR:PHY2, 6.100A, 18.03","corequisites":"","recommendedPreparation":"Lab time devoted to local fieldwork to gain experience with the methods being taught and to prepare for field geophysics."},{"code":"12.301","title":"Climate Science","level":"U","description":"Introduction to climate studies, including beginnings of the solar system, time scales, and climate in human history; methods for detecting climate change, including proxies, ice cores, instrumental records, and time series analysis; physical and chemical processes in climate, including primordial atmosphere, ozone chemistry, carbon and oxygen cycles, and heat and water budgets; internal feedback mechanisms, including ice, aerosols, water vapor, clouds, and ocean circulation; climate forcing, including orbital variations, volcanism, plate tectonics, and solar variability; climate models and mechanisms of variability, including energy balance, coupled models, and global ocean and atmosphere models; and outstanding problems. Students taking the graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"15:00","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.301","terms":["fall"],"rating":6.4,"hours":8.08,"inClassHours":3.11,"outOfClassHours":4.97,"prerequisites":"(GIR:CAL2, GIR:CHEM, GIR:PHY2)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.321","title":"Modeling the Earth System and Climate","level":"U","description":"Introduces the foundations of Earth System Models used in climate research and assessments such as those of the Intergovernmental Panel on Climate Change (IPCC). Examines the major components of the climate system ? atmosphere, ocean, land, and cryosphere ? and how their processes are represented and coupled in global simulations. Provides experience configuring and running a fully coupled model and analyzing model output. Covers model evaluation, uncertainty, and applications to historical climate and future projections. Culminates in a student-designed modeling experiment and research proposal. Students taking graduate version complete additional work and are expected to submit more detailed proposals.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.321","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"(8.01, 18.01)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.335","title":"Experimental Atmospheric Chemistry","level":"U","description":"Introduces the atmospheric chemistry involved in climate change, air pollution, and ozone depletion using a combination of interactive laboratory and field studies and simple computer models. Uses instruments for trace gas and aerosol measurements and methods for inferring fundamental information from these measurements. Provides instruction and practice in written and oral communication. Students taking the graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"E25-605"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"E25-650"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.335","terms":["fall"],"rating":3.81,"hours":8.18,"inClassHours":3.26,"outOfClassHours":4.92,"prerequisites":"GIR:CHEM","corequisites":"","recommendedPreparation":""},{"code":"12.372","title":"Elements of Modern Oceanography","level":"U","description":"Examines a series of crosscutting topics that exemplify current directions in interdisciplinary oceanography. Focuses on current themes in oceanography, their interdisciplinary nature, and the role of ocean sciences in society. Introduces core concepts across the disciplines of biological, physical, and chemical oceanography as well as marine geology. Emphasizes the interdisciplinary aspects of these core concepts, the kinds of approaches and modes of thinking common to all of the disciplines, and the technological developments underpinning current advances. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","F"],"start":"10:30","end":"12:00","room":"54-1623"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.372","terms":["fall"],"rating":6.38,"hours":7.0,"inClassHours":3.01,"outOfClassHours":3.99,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.387","title":"People and the Planet: Environmental Governance and Science","level":"U","description":"Introduces governance and science aspects of complex environmental problems and approaches to solutions. Introduces quantitative analyses and methodological tools to analyze environmental issues that have human and natural components. Demonstrates concepts through a series of in-depth case studies of environmental governance and science problems. Students develop writing, quantitative modeling, and analytical skills in assessing environmental systems problems and developing solutions. Through experiential activities, such as modeling and policy exercises, students engage with the challenges and possibilities of governance in complex, interacting systems, including biogeophysical processes and societal and stakeholder interactions.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"12:30","room":"54-820"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.387","terms":["fall"],"rating":6.65,"hours":6.97,"inClassHours":3.0,"outOfClassHours":3.97,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.390","title":"Fluid Dynamics of the Atmosphere and Ocean","level":"U","description":"Introduction to fluid dynamics. Students acquire an understanding of some of the basic concepts of fluid dynamics that are needed as a foundation for advanced coursework in atmospheric science, physical oceanography, ocean engineering, climate science, etc. Emphasizes fluid fundamentals, with an atmosphere/ocean twist. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"10:30","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.390","terms":["fall"],"rating":5.25,"hours":12.2,"inClassHours":3.97,"outOfClassHours":8.23,"prerequisites":"12.003","corequisites":"","recommendedPreparation":""},{"code":"12.410","title":"Observational Techniques of Optical Astronomy","level":"U","description":"Fundamental physical and optical principles used for astronomical measurements at visible wavelengths and practical methods of astronomical observations. Topics: astronomical coordinates, time, optics, telescopes, photon counting, signal-to-noise ratios, data analysis (including least-squares model fitting), limitations imposed by the Earth's atmosphere on optical observations, CCD detectors, photometry, spectroscopy, astrometry, and time variability. Project at Wallace Astrophysical Observatory. Written and oral project reports. Limited to 18; preference to Course 8 and Course 12 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"55-110"}]},{"type":"Lab","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"54-527"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.410","terms":["fall"],"rating":6.43,"hours":13.26,"inClassHours":6.5,"outOfClassHours":6.76,"prerequisites":"8.282/12.409/''other introductory astronomy course''","corequisites":"","recommendedPreparation":""},{"code":"12.420","title":"Essentials of Planetary Science","level":"U","description":"Advanced applications of physical and chemical principles to the study of the solar system. Topics include terrestrial and giant planets, meteorites, asteroids, comets, Kuiper belt objects, rings, impact craters, interiors, surfaces, atmospheres, geomagnetism, cosmochemistry, remote sensing, formation and evolution of the solar system.","groups":[{"type":"Lecture","options":[{"days":["W","F"],"start":"10:00","end":"11:30","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.420","terms":["fall"],"rating":4.54,"hours":13.19,"inClassHours":2.92,"outOfClassHours":10.27,"prerequisites":"(8.03, 12.002, 18.03)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.421","title":"Remote Sensing: Physical Principles and Techniques","level":"U","description":"Introduction to the physics of remote sensing, with applications to the study of Earth, the Moon, and other planets and solar system bodies, as well as to emerging industrial applications. Covers the physical principles of optical, thermal, radar, and lidar remote sensing with an emphasis on the fundamental properties of electromagnetic waves; the principles of electromagnetic scattering from real and idealized materials, including various types of surfaces and vegetation; the interaction of electromagnetic radiation with the atmosphere; and thermal and microwave emission from various media. Discusses remote sensing platforms along with the essentials of orbital mechanics and data processing methods and tools. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.421","terms":["fall"],"rating":5.94,"hours":9.52,"inClassHours":3.14,"outOfClassHours":6.38,"prerequisites":"GIR:PHY2/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.425","title":"Extrasolar Planets: Physics and Detection Techniques","level":"U","description":"Presents basic principles of planet atmospheres and interiors applied to the study of extrasolar planets. Focuses on fundamental physical processes related to observable extrasolar planet properties. Provides a quantitative overview of detection techniques. Introduction to the feasibility of the search for Earth-like planets, biosignatures and habitable conditions on extrasolar planets. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-209"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.425","terms":["fall"],"rating":6.74,"hours":7.88,"inClassHours":3.09,"outOfClassHours":4.79,"prerequisites":"8.03, 18.03","corequisites":"","recommendedPreparation":""},{"code":"12.43","title":"Space Systems Engineering","level":"U","description":"Design of a complete space system, including systems analysis, trajectory analysis, entry dynamics, propulsion and power systems, structural design, avionics, thermal and environmental control, human factors, support systems, and weight and cost estimates. Students participate in teams, each responsible for an integrated vehicle design, providing experience in project organization and interaction between disciplines. Includes several aspects of team communication including three formal presentations, informal progress reports, colleague assessments, and written reports. Course 16 students are expected to complete two professional or concentration subjects from the departmental program before taking this capstone. Offered alternate fall and spring terms.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"33-218"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"16:00","end":"17:00","room":"33-218"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.43","terms":["fall"],"rating":4.93,"hours":10.02,"inClassHours":3.42,"outOfClassHours":6.6,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.444","title":"MatLab, Statistics, Regression, Signal Processing","level":"G","description":"Introduces the basic tools needed for data analysis and interpretation in the Geosciences, as well as other sciences. Composed of four modules, targeted at introducing students to the basic concepts and applications in each module. MatLab: Principles and practice in its uses, script and function modules, basic approaches to solving problems. Statistics: Correlation, means, dispersion, precision, accuracy, distributions, central limit theorem, skewness, probability, Chi-Square, Gaussian and other common distributions used in hypothesis testing. Regression: Random and grid search methods, basic least squares and algorithms applicable to regression, inversion and parameter estimation. Signal Processing: Analog and digital signals, Z-transform, Fourier series, fast Fourier transforms, spectral analysis leakage and bias, digital filtering. Students taking the graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"54-517"}]}],"url":"http://student.mit.edu/catalog/m12b.html#12.444","terms":["fall"],"rating":6.34,"hours":15.46,"inClassHours":5.35,"outOfClassHours":10.11,"prerequisites":"18.06","corequisites":"","recommendedPreparation":""},{"code":"12.478","title":"The Phylogenomic Planetary Record","level":"G","description":"Introduces the tools of sequence-based phylogenetic analysis and molecular evolution in the context of studying events in Earth's deep past that have been preserved by genomes. Topics include basic concepts of cladistics, phylogeny and sequence evolution, construction of phylogenetic trees of genes and microbial lineages, molecular clocks, dating, and ancestral sequence reconstruction. Special attention to the evolutionary history of microbial metabolisms and their relationship to global biogeochemical cycles across Earth's history. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-1623"}]}],"url":"http://student.mit.edu/catalog/m12b.html#12.478","terms":["fall"],"rating":6.94,"hours":9.9,"inClassHours":3.1,"outOfClassHours":6.8,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.493","title":"Microbial Genetics and Evolution","level":"G","description":"Covers aspects of microbial genetic and genomic analyses, central dogma, horizontal gene transfer, and evolution.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:30","room":"66-160"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m12b.html#12.493","terms":["fall"],"rating":6.36,"hours":9.65,"inClassHours":4.23,"outOfClassHours":5.42,"prerequisites":"7.03/7.05/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.503","title":"Mechanics of Earth","level":"G","description":"Covers topics in the deformation and fracture of solids and the flow of viscous fluids. Explores spatial scales from molecular to planetary, and time scales from fractions of a second to millions of years, to understand how and why natural materials on Earth and other terrestrial bodies respond to applied forces. Introduces anelasticity, granular mechanics, poroelasticity, rate-and-state friction, transport properties of Earth materials (Darcy's law, Fick's law), brittle-ductile transitions, creep of polycrystalline materials, stored energy and dissipation, and convection. Prepares students to gather, analyze and interpret data using existing theoretical models. Through a significant laboratory component, students obtain practical experience with experimental measurements and test their acquired theoretical knowledge. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"12:00","room":"54-819"}]},{"type":"Lab","options":[{"days":["M"],"start":"09:00","end":"11:00","room":"54-819"}]}],"url":"http://student.mit.edu/catalog/m12b.html#12.503","terms":["fall"],"rating":6.96,"hours":12.08,"inClassHours":4.96,"outOfClassHours":7.12,"prerequisites":"GIR:CAL2, GIR:PHY1","corequisites":"","recommendedPreparation":"Through a significant laboratory component, students obtain practical experience with experimental measurements and test their acquired theoretical knowledge."},{"code":"12.507","title":"Essentials of Field Geophysics","level":"G","description":"Introduces students to the practical field application of various geophysical methods to the study of Earth's near-surface. Prepares students to undertake fieldwork that uses these methods. Designed to prepare students to continue their studies in geophysics and data analysis. The methods covered vary and may include: measuring seismic waves, gravity, precise positions (commonly referred to as GPS, but formally known as GNSS), and topography using drones. Lab time devoted tolocal fieldwork to gain experience with the methods being taught and to prepare for field geophysics. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"54-819"}]}],"url":"http://student.mit.edu/catalog/m12b.html#12.507","terms":["fall"],"rating":6.8,"hours":6.3,"inClassHours":4.5,"outOfClassHours":1.8,"prerequisites":"GIR:PHY2, 6.100A, 18.03","corequisites":"","recommendedPreparation":"Lab time devoted tolocal fieldwork to gain experience with the methods being taught and to prepare for field geophysics."},{"code":"12.571","title":"Seminar in Earth Science","level":"G","description":"Problems of current interest in geobiology, geochemistry, geology, and geophysics; subject matter varying from term to term.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:00","end":"13:00","room":"55-109"}]},{"type":"Recitation","options":[{"days":["M"],"start":"13:00","end":"15:00","room":"54-517"}]}],"url":"http://student.mit.edu/catalog/m12b.html#12.571","terms":["fall","spring"],"rating":6.73,"hours":6.45,"inClassHours":2.92,"outOfClassHours":3.53,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.601","title":"Essentials of Planetary Science","level":"G","description":"Reviews fundamental physical concepts pertaining to the study of the solar system, and highlights recent spacecraft results. Topics include: meteorites, orbital dynamics, asteroids, impact craters, surfaces, atmospheres, atmospheric dynamics, interiors, magnetospheres, rings, comets, formation of the solar system.","groups":[{"type":"Lecture","options":[{"days":["W","F"],"start":"10:00","end":"11:30","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.601","terms":["fall"],"rating":4.54,"hours":13.19,"inClassHours":2.92,"outOfClassHours":10.27,"prerequisites":"(8.03, 12.002, 18.03)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.621","title":"Remote Sensing: Physical Principles and Techniques","level":"G","description":"Introduction to the physics of remote sensing, with applications to the study of Earth, the Moon, and other planets and solar system bodies, as well as to emerging industrial applications. Covers the physical principles of optical, thermal, radar, and lidar remote sensing with an emphasis on the fundamental properties of electromagnetic waves; the principles of electromagnetic scattering from real and idealized materials, including various types of surfaces and vegetation; the interaction of electromagnetic radiation with the atmosphere; and thermal and microwave emission from various media. Discusses remote sensing platforms along with the essentials of orbital mechanics and data processing methods and tools. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.621","terms":["fall"],"rating":5.94,"hours":9.52,"inClassHours":3.14,"outOfClassHours":6.38,"prerequisites":"GIR:PHY2/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.625","title":"Extrasolar Planets: Physics and Detection Techniques","level":"G","description":"In-depth study of current topics in exoplanets, such as exoplanet transits, radial velocity curves, current survey missions, the mass-radius relation, and super Earths. Class activities consist of reading the current literature, problem sets, and a term project. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-209"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.625","terms":["fall"],"rating":6.74,"hours":7.88,"inClassHours":3.09,"outOfClassHours":4.79,"prerequisites":"8.03, 18.03","corequisites":"","recommendedPreparation":""},{"code":"12.702","title":"Elements of Modern Oceanography","level":"G","description":"Examines a series of crosscutting topics that exemplify current directions in interdisciplinary oceanography. Focuses on current themes in oceanography, their interdisciplinary nature, and the role of ocean sciences in society. Introduces core concepts across the disciplines of biological, physical, and chemical oceanography as well as marine geology. Emphasizes the interdisciplinary aspects of these core concepts, the kinds of approaches and modes of thinking common to all of the disciplines, and the technological developments underpinning current advances. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","F"],"start":"10:30","end":"12:00","room":"54-1623"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.702","terms":["fall"],"rating":6.38,"hours":7.03,"inClassHours":3.02,"outOfClassHours":4.01,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.703","title":"Presenting Scientific Research","level":"G","description":"Presenting scientific research geared toward a scientific audience.  Each student gives one 30-minute talk, one AGU-style 15-minute talk, and one poster presentation.  Students present their ongoing research and use the class as a forum to practice for upcoming talks in more formal settings.  Abstracts are prepared for each presentation and discussed in class.  Students provide comments, questions, encouragement, critiques, etc. on their peers' presentations.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:30","end":"12:00","room":"WHOI CAMPUS"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.703","terms":["fall"],"rating":6.2,"hours":4.54,"inClassHours":2.0,"outOfClassHours":2.54,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.708","title":"Topics in Paleoceanography","level":"G","description":"Seminar focusing on areas of current interest in paleoceanography and paleoclimatology. Includes discussion of current and classic literature. Topics vary from year to year.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"10:30","end":"12:00","room":"54-820"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.708","terms":["fall"],"rating":6.59,"hours":5.28,"inClassHours":2.0,"outOfClassHours":3.28,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.710","title":"Geological Oceanography","level":"G","description":"Provides a high level survey of a broad range of active science topics in Geological Oceanography. Presents background material that graduate students are expected to know in the disciplines of solid-earth geophysics, geochemistry, sedimentology and stratigraphy, coastal processes, and climate, including a representative set of canonical science papers, and builds on this material to give a sense of the current state of the science in these fields. Broad topics include the formation of the earth, petrogenesis, volcanism, plate tectonics, geodynamics, sedimentation in the oceans, coastal morphodynamics, paleo-oceanography, and climate. The interconnectedness of and feedbacks between processes discussed under these various topics is emphasized.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"16:00","end":"17:30","room":"54-820"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.710","terms":["fall"],"rating":4.52,"hours":7.81,"inClassHours":3.04,"outOfClassHours":4.77,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.742","title":"Marine Chemistry","level":"G","description":"An introduction to chemical oceanography. Reservoir models and residence time. Major ion composition of seawater. Inputs to and outputs from the ocean via rivers, the atmosphere, and the sea floor. Biogeochemical cycling within the oceanic water column and sediments, emphasizing the roles played by the formation, transport, and alteration of oceanic particles and the effects that these processes have on seawater composition. Cycles of carbon, nitrogen, phosphorus, oxygen, and sulfur. Uptake of anthropogenic carbon dioxide by the ocean. Material presented through lectures and student-led presentation and discussion of recent papers.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.742","terms":["fall"],"rating":6.11,"hours":11.71,"inClassHours":4.0,"outOfClassHours":7.71,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.746","title":"Marine Organic Geochemistry","level":"G","description":"Provides an understanding of the distribution of organic carbon (OC) in marine sediments from a global and molecular-level perspective. Surveys the mineralization and preservation of OC in the water column and within anoxic and oxic marine sediments. Topics include: OC composition, reactivity and budgets within, and fluxes through, major reservoirs; microbial recycling pathways for OC; models for OC degradation and preservation; role of anoxia in OC burial; relationships between dissolved and particulate (sinking and suspended) OC; methods for characterization of sedimentary organic matter; application of biological markers as tools in oceanography. Both structural and isotopic aspects are covered.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"54-820"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.746","terms":["fall"],"rating":6.1,"hours":5.86,"inClassHours":3.0,"outOfClassHours":2.86,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.757","title":"Seminar in Oceanography at Woods Hole","level":"G","description":"Topics in marine geology and geophysics, physical, dynamical, and chemical oceanography. Content varies from term to term. 12.754, 12.755, and 12.756 are letter-graded.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"17:30","room":"54-827"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.759","terms":["fall"],"rating":6.48,"hours":4.97,"inClassHours":2.23,"outOfClassHours":2.74,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.800","title":"Fluid Dynamics of the Atmosphere and Ocean","level":"G","description":"Introduction to fluid dynamics. Students acquire an understanding of some of the basic concepts of fluid dynamics that are needed as a foundation for advanced coursework in atmospheric science, physical oceanography, ocean engineering, climate science, etc. Emphasizes fluid fundamentals, with an atmosphere/ocean twist. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"10:30","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.800","terms":["fall"],"rating":5.25,"hours":12.21,"inClassHours":3.97,"outOfClassHours":8.24,"prerequisites":"8.03, 18.04","corequisites":"","recommendedPreparation":""},{"code":"12.807","title":"Atmospheric Chemistry","level":"G","description":"Provides a detailed overview of the chemical transformations that control the abundances of key trace species in the Earth's atmosphere. Emphasizes the effects of human activity on air quality and climate. Topics include photochemistry, kinetics, and thermodynamics important to the chemistry of the atmosphere; stratospheric ozone depletion; oxidation chemistry of the troposphere; photochemical smog; aerosol chemistry; and sources and sinks of greenhouse gases and other climate forcers.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"35-308"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.807","terms":["fall"],"rating":6.85,"hours":11.11,"inClassHours":3.01,"outOfClassHours":8.1,"prerequisites":"5.601, 5.602","corequisites":"","recommendedPreparation":""},{"code":"12.808","title":"Introduction to Observational Physical Oceanography","level":"G","description":"Results and techniques of observations of the ocean in the context of its physical properties and dynamical constraints. Emphasis on large-scale steady circulation and the time-dependent processes that contribute to it. Includes the physical setting of the ocean, atmospheric forcing, application of conservation laws, description of wind-driven and thermohaline circulation, eddy processes, and interpretive techniques.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.808","terms":["fall"],"rating":5.87,"hours":10.64,"inClassHours":3.14,"outOfClassHours":7.5,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.812","title":"The General Circulation of the Atmosphere and Climate Change","level":"G","description":"Describes the general circulation of Earth's atmosphere and its maintenance. Second half of the course explores the response of the general circulation to climate change.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.812","terms":["fall"],"rating":6.52,"hours":6.55,"inClassHours":2.97,"outOfClassHours":3.58,"prerequisites":"12.810/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.835","title":"Experimental Atmospheric Chemistry","level":"G","description":"Introduces the atmospheric chemistry involved in climate change, air pollution, and ozone depletion using a combination of interactive laboratory and field studies and simple computer models. Uses instruments for trace gas and aerosol measurements and methods for inferring fundamental information from these measurements. Students taking the graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"E25-605"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"E25-650"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.835","terms":["fall"],"rating":3.81,"hours":8.18,"inClassHours":3.26,"outOfClassHours":4.92,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.842","title":"Climate Science","level":"G","description":"Introduction to climate studies, including beginnings of the solar system, time scales, and climate in human history; methods for detecting climate change, including proxies, ice cores, instrumental records, and time series analysis; physical and chemical processes in climate, including primordial atmosphere, ozone chemistry, carbon and oxygen cycles, and heat and water budgets; internal feedback mechanisms, including ice, aerosols, water vapor, clouds, and ocean circulation; climate forcing, including orbital variations, volcanism, plate tectonics, and solar variability; climate models and mechanisms of variability, including energy balance, coupled models, and global ocean and atmosphere models; and outstanding problems. Students taking the graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"15:00","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.842","terms":["fall"],"rating":6.4,"hours":8.08,"inClassHours":3.11,"outOfClassHours":4.97,"prerequisites":"(GIR:CAL2, GIR:CHEM, GIR:PHY2)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.843","title":"Large-scale Atmosphere and Ocean Dynamics","level":"G","description":"Project-based with lectures covering the relevant theory. Students work in groups on four projects. Each of these comprises a numerical part, to illuminate and illustrate the theory, and a data part (drawn from laboratory tank experiments, atmospheric, or ocean observations), to illustrate the phenomena. Topics include: barotropic vorticity dynamics including inversion and evolution, geostrophic and higher order balance, baroclinic dynamics and the evolution of balanced flows, and stability with emphasis on the mutual interaction of disturbances. Projects include a verbal presentation and writeup covering both the numerical and geophysical parts plus additional derivations as needed.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"54-1623"}]},{"type":"Lab","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"54-1623"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.843","terms":["fall"],"rating":6.39,"hours":14.32,"inClassHours":4.89,"outOfClassHours":9.43,"prerequisites":"12.801/12.810/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.860","title":"Climate Variability and Diagnostics","level":"G","description":"Explores climate variability and change, focusing on the atmosphere and ocean, while building experience applying diagnostic analyses to a range of modern observations and models. Provides practical insight, from regional to global scale, with applications to past and future climates. Emphasizes salient features of the mean climate system and modes of natural variability, as well as observed and projected manifestations of anthropogenic climate change. Students gain experience accessing, analyzing, and visualizing a wide range of gridded observational-based datasets, as well as output from global climate model simulations. Develops the tools necessary to apply climate diagnostic analysis to one's own research, as well as the interdisciplinary edge to critically assess and interpret the observational and model results underpinning the Fifth Assessment Reports of the Intergovernmental Panel on Climate Change.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-1623"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.860","terms":["fall"],"rating":6.3,"hours":12.19,"inClassHours":3.0,"outOfClassHours":9.19,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.862","title":"Coastal Physical Oceanography","level":"G","description":"Introduction to the dynamics of flow over the continental shelf, nearshore, and estuaries, emphasizing both theory and observations.  Content varies somewhat according to student and staff interests. Possible topics include fronts, buoyant plumes, surface and bottom boundary layers, wind-driven upwelling, coastal-trapped waves, internal waves, quasi-steady flows, high-latitude shelf processes, tides, and shelf-open ocean interactions.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.862","terms":["fall"],"rating":4.24,"hours":12.03,"inClassHours":3.0,"outOfClassHours":9.03,"prerequisites":"12.800","corequisites":"","recommendedPreparation":""},{"code":"12.900","title":"EAPS First Year Graduate Seminar","level":"G","description":"Provides a shared experience for first-year graduate students in EAPS and the MIT/ WHOI Joint Program. Facilitates opportunities to interact with senior graduate students and to meet a wide range of faculty.  Familiarizes students with departmental research within the themes of Earth, planets, climate, and life.  Discusses resources, graduate life at MIT, and the path to PhD.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"54-517"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.900","terms":["fall"],"rating":6.49,"hours":4.14,"inClassHours":1.06,"outOfClassHours":3.08,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.910","title":"Communicating Ocean Science","level":"G","description":"For students interested in improving their ability to teach science, the focus is on inquiry-based instructional methods and application to various audiences. Includes an opportunity to teach in a course at a local college or university and in a supervised elementary school classroom. The undergraduate lesson is arranged in consultation with the institution's faculty. Outreach in local school classrooms involves one session observing and several sessions teaching. Class meets twice a week for 11 sessions, and episodically thereafter.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"54-827"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.910","terms":["fall"],"rating":5.83,"hours":6.55,"inClassHours":3.0,"outOfClassHours":3.55,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.921","title":"Modeling the Earth System and Climate","level":"G","description":"Introduces the foundations of Earth System Models used in climate research and assessments such as those of the Intergovernmental Panel on Climate Change (IPCC). Examines the major components of the climate system ? atmosphere, ocean, land, and cryosphere ? and how their processes are represented and coupled in global simulations. Provides experience configuring and running a fully coupled model and analyzing model output. Covers model evaluation, uncertainty, and applications to historical climate and future projections. Culminates in a student-designed modeling experiment and research proposal. Students taking graduate version complete additional work and are expected to submit more detailed proposals.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.921","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"(8.01, 18.01)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"12.C25","title":"Real World Computation with Julia","level":"U","description":"Focuses on algorithms and techniques for writing and using modern technical software in a job, lab, or research group environment that may consist of interdisciplinary teams, where performance may be critical, and where the software needs to be flexible and adaptable. Topics include automatic differentiation, matrix calculus, scientific machine learning, parallel and GPU computing, and performance optimization with introductory applications to climate science, economics, agent-based modeling, and other areas. Labs and projects focus on performant, readable, composable algorithms, and software. Programming will be in Julia. Expects students to have some familiarity with Python, Matlab, or R. No Julia experience necessary.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.C25","terms":["fall"],"rating":6.3,"hours":7.33,"inClassHours":3.1,"outOfClassHours":4.23,"prerequisites":"6.100A, 18.03, 18.06","corequisites":"","recommendedPreparation":"Expects students to have some familiarity with Python, Matlab, or R."},{"code":"12.S501","title":"Special Seminar in Earth, Atmospheric, and Planetary Sciences","level":"G","description":"Organized lecture or laboratory subject on an aspect of the earth sciences, planetary sciences, or astronomy not normally covered in regularly scheduled subjects. 12.592 is letter-graded.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:00","end":"13:30","room":"55-108"}]}],"url":"http://student.mit.edu/catalog/m12c.html#12.S501","terms":["fall","spring"],"rating":7.0,"hours":3.0,"inClassHours":2.0,"outOfClassHours":1.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"12.TIP","title":"Thesis Preparation","level":"U","description":"Definition of and early-stage work on the thesis project. Students develop a written research proposal and begin writing the supporting text of the thesis concurrent with conducting research for the thesis project. Supervision of the writing continues into the spring term which concludes with an oral presentation of the research results.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"54-827"}]}],"url":"http://student.mit.edu/catalog/m12a.html#12.TIP","terms":["fall","spring"],"rating":5.93,"hours":5.32,"inClassHours":1.0,"outOfClassHours":4.32,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.003","title":"Microeconomic Theory and Public Policy","level":"G","description":"Students master and apply economic theory, causal inference, and contemporary evidence to analyze policy challenges. These include the effect of minimum wages on employment, the value of healthcare, the power and limitations of free markets, the benefits and costs of international trade, the causes and remedies of externalities, the consequences of adverse selection in insurance markets, the impacts of labor market discrimination, and the application of machine learning to supplement to decision-making. Class attendance and participation are mandatory. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"E52-164"},{"days":["F"],"start":"10:00","end":"11:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.003","terms":["fall","spring"],"rating":6.2,"hours":9.43,"inClassHours":3.86,"outOfClassHours":5.57,"prerequisites":"14.01/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.01","title":"Principles of Microeconomics","level":"U","description":"Introduces microeconomic concepts and analysis, supply and demand analysis, theories of the firm and individual behavior, competition and monopoly, and welfare economics. Applications to problems of current economic policy.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:00","room":"32-123"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"4-163"},{"days":["F"],"start":"12:00","end":"13:00","room":"4-163"},{"days":["F"],"start":"13:00","end":"14:00","room":"4-163"},{"days":["F"],"start":"11:00","end":"12:00","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.01","terms":["fall","spring"],"rating":4.95,"hours":7.65,"inClassHours":2.67,"outOfClassHours":4.98,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.02","title":"Principles of Macroeconomics","level":"U","description":"Provides an overview of macroeconomic issues including the determination of national income, economic growth, unemployment, inflation, interest rates, and exchange rates. Introduces basic macroeconomic models and illustrates key principles through applications to the experience of the US and other economies. Explores a range of current policy debates, such as the economic effects of monetary and fiscal policy, the causes of and policy responses to financial crises, the burden of the national debt, and the government policies that affect long-term growth in living standards. Lectures are recorded and available for students with scheduling conflicts.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:00","room":"54-100"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"4-237"},{"days":["F"],"start":"14:00","end":"15:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.02","terms":["fall","spring"],"rating":5.33,"hours":6.36,"inClassHours":2.16,"outOfClassHours":4.2,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.03","title":"Microeconomic Theory and Public Policy","level":"U","description":"Students master and apply economic theory, causal inference, and contemporary evidence to analyze policy challenges. These include the effect of minimum wages on employment, the value of healthcare, the power and limitations of free markets, the benefits and costs of international trade, the causes and remedies of externalities, the consequences of adverse selection in insurance markets, the impacts of labor market discrimination, and the application of machine learning to supplement to decision-making. Class attendance and participation are mandatory. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"E52-164"},{"days":["F"],"start":"10:00","end":"11:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.03","terms":["fall","spring"],"rating":6.2,"hours":9.43,"inClassHours":3.86,"outOfClassHours":5.57,"prerequisites":"14.01/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.04","title":"Intermediate Microeconomic Theory","level":"U","description":"Analysis of consumer and producer decisions including analysis of competitive and monopolistic markets. Price-based partial and general equilibrium analysis. Introduction to game theory as a foundation for the strategic analysis of economic situations. Imperfect competition, dynamic games among firms. Failures of general equilibrium theory and their resolutions: externalities, public goods, incomplete information settings, signaling, screening, insurance, alternative market mechanisms, auctions, design of markets.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-361"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.04","terms":["fall"],"rating":4.92,"hours":8.61,"inClassHours":3.66,"outOfClassHours":4.95,"prerequisites":"GIR:CAL2, 14.01","corequisites":"","recommendedPreparation":""},{"code":"14.05","title":"Intermediate Macroeconomics","level":"U","description":"Uses the tools of macroeconomics to investigate various macroeconomic issues in depth. Topics range from economic growth and inequality in the long run to economic stability and financial crises in the short run. Surveys many economic models used today. Requires a substantial research paper on the economics of long-run economic growth.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-372"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.05","terms":["fall"],"rating":5.78,"hours":8.98,"inClassHours":3.69,"outOfClassHours":5.29,"prerequisites":"14.01, (14.02/''permission of instructor'')","corequisites":"","recommendedPreparation":""},{"code":"14.12","title":"Economic Applications of Game Theory","level":"U","description":"Analysis of strategic behavior in multi-person economic settings. Introduction to solution concepts, such as rationalizability, backwards induction, Nash equilibrium, subgame-perfect equilibrium, and sequential equilibrium. Strong emphasis on dynamic games, such as repeated games. Introduction to Bayesian games, focusing on Bayesian Nash Equilibrium, Perfect Bayesian Equilibrium, and signaling games. Applications drawn from microeconomics: imperfect competition, implicit cartels, bargaining, and auctions.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"4-237"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-376"},{"days":["F"],"start":"11:00","end":"12:00","room":"E51-395"},{"days":["F"],"start":"14:00","end":"15:00","room":"E51-361"},{"days":["F"],"start":"15:00","end":"16:00","room":"E51-361"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.12","terms":["fall"],"rating":5.89,"hours":8.14,"inClassHours":2.99,"outOfClassHours":5.15,"prerequisites":"14.01, (6.041B/14.04/14.30/18.05/''permission of instructor'')","corequisites":"","recommendedPreparation":""},{"code":"14.121","title":"Microeconomic Theory I","level":"G","description":"Covers consumer and producer theory, markets and competition, general equilibrium and the welfare theorems; featuring applications, uncertainty, identification and restrictions models place on data. Enrollment limited; preference to PhD students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-151"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.121","terms":["fall"],"rating":6.06,"hours":13.51,"inClassHours":4.33,"outOfClassHours":9.18,"prerequisites":"14.04, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.122","title":"Microeconomic Theory II","level":"G","description":"Introduction to game theory. Topics include normal form and extensive form games, and games with incomplete information. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-151"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.122","terms":["fall"],"rating":6.32,"hours":11.34,"inClassHours":4.24,"outOfClassHours":7.1,"prerequisites":"14.121, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.125","title":"Market Design","level":"G","description":"Theory and practice of market design, building on ideas from microeconomics, game theory and mechanism design. Prominent case studies include auctions, labor markets, school choice, prediction markets, financial markets, and organ exchange clearinghouses.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E52-532"}]},{"type":"Recitation","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"E52-532"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.125","terms":["fall"],"rating":6.3,"hours":12.17,"inClassHours":3.92,"outOfClassHours":8.25,"prerequisites":"14.124","corequisites":"","recommendedPreparation":""},{"code":"14.13","title":"Psychology and Economics","level":"U","description":"Introduces the theoretical and empirical literature of behavioral economics. Examines important and systematic departures from the standard models in economics by incorporating insights from psychology and other social sciences. Covers theory and evidence on time, risk, and social preferences; beliefs and learning; emotions; limited attention; and frames, defaults, and nudges. Studies applications to many different areas, such as credit card debt, procrastination, retirement savings, addiction, portfolio choice, poverty, labor supply, happiness, and government policy. Students participate in surveys and experiments in class, review evidence from lab experiments, examine how the results can be integrated into models, and test models using field and lab data. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-100"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"56-114"},{"days":["F"],"start":"12:00","end":"13:00","room":"56-114"},{"days":["F"],"start":"15:00","end":"16:00","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.13","terms":["fall"],"rating":6.42,"hours":7.04,"inClassHours":3.16,"outOfClassHours":3.88,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.130","title":"Reading Economic Theory","level":"G","description":"Class will read and discuss current research in economic theory with a focus on game theory, decision theory, and behavioral economics. Students will be expected to make one presentation and to read and post comments on every paper by the day before the paper is presented. Permission of the instructor required, and auditors are not allowed.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"15:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.130","terms":["fall"],"rating":6.94,"hours":7.09,"inClassHours":2.0,"outOfClassHours":5.09,"prerequisites":"14.121, 14.451","corequisites":"","recommendedPreparation":""},{"code":"14.131","title":"Psychology and Economics","level":"G","description":"Introduces the theoretical and empirical literature of behavioral economics. Examines important and systematic departures from the standard models in economics by incorporating insights from psychology and other social sciences. Covers theory and evidence on time, risk, and social preferences; beliefs and learning; emotions; limited attention; and frames, defaults, and nudges. Studies applications to many different areas, such as credit card debt, procrastination, retirement savings, addiction, portfolio choice, poverty, labor supply, happiness, and government policy. Students participate in surveys and experiments in class, review evidence from lab experiments, examine how the results can be integrated into models, and test models using field and lab data.  Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-100"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"56-114"},{"days":["F"],"start":"12:00","end":"13:00","room":"56-114"},{"days":["F"],"start":"15:00","end":"16:00","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.131","terms":["fall"],"rating":6.42,"hours":7.03,"inClassHours":3.16,"outOfClassHours":3.87,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.147","title":"Topics in Economic Theory","level":"G","description":"Advanced subject on topics of current research interest. First half emphasizes information in dynamic games. Second half focuses on learning and some of the associated probability theory, including proofs of some of the theorems used in the first half.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E52-314"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"E51-385"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.147","terms":["fall"],"rating":6.93,"hours":8.95,"inClassHours":3.42,"outOfClassHours":5.53,"prerequisites":"14.126","corequisites":"","recommendedPreparation":""},{"code":"14.15","title":"Networks","level":"U","description":"Highlights common principles that permeate the functioning of diverse technological, economic and social networks. Utilizes three sets of tools for analyzing networks -- random graph models, optimization, and game theory -- to study informational and learning cascades; economic and financial networks; social influence networks; formation of social groups; communication networks and the Internet; consensus and gossiping; spread and control of epidemics; control and use of energy networks; and biological networks. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-149"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.15","terms":["fall"],"rating":5.0,"hours":7.38,"inClassHours":2.83,"outOfClassHours":4.55,"prerequisites":"6.3700/14.30","corequisites":"","recommendedPreparation":""},{"code":"14.150","title":"Networks","level":"G","description":"Highlights common principles that permeate the functioning of diverse technological, economic and social networks. Utilizes three sets of tools for analyzing networks -- random graph models, optimization, and game theory -- to study informational and learning cascades; economic and financial networks; social influence networks; formation of social groups; communication networks and the Internet; consensus and gossiping; spread and control of epidemics; control and use of energy networks; and biological networks. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-149"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.150","terms":["fall"],"rating":5.01,"hours":7.36,"inClassHours":2.82,"outOfClassHours":4.54,"prerequisites":"6.3700/14.300","corequisites":"","recommendedPreparation":""},{"code":"14.164","title":"Foundations of Behavioral Economics","level":"G","description":"Presents the core concepts of behavioral economics, including: key models and theories, how to run a mechanism experiment in the field and online, and how to effectively read the psychology literature and bring key insights into economics. Models and theories covered include, but are not limited to: non-standard preferences (such as social preferences; reference-dependence; temptation, self-control, and quasi-hyperbolic preferences), non-standard beliefs (selective attention, selective memory, and misspecification; failures of contingent reasoning), and non-standard decision-making (anchoring, complexity aversion, imitation heuristics).","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"E51-361"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.164","terms":["fall"],"rating":7.0,"hours":14.0,"inClassHours":4.5,"outOfClassHours":9.5,"prerequisites":"","corequisites":"14.123","recommendedPreparation":""},{"code":"14.17","title":"Blockchain and Financial System Design","level":"U","description":"Synthesizes computer science technologies underlying cryptocurrency, blockchain, tokenization, platforms, and computational algorithms with economics and its use of contracts, mechanism design, general equilibrium, and monetary theory. Topics include: legacy systems in developed and developing economies; technological change; the impact of distributed ledgers, smart contracts, and encryption; the optimal allocation of risk; market structure; and optimized regulation. Explores new financial designs for industry, digital companies, central banks, and international organizations. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E51-361"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.17","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.170","title":"Blockchain and Financial System Design","level":"G","description":"Synthesizes computer science technologies underlying cryptocurrency, blockchain, tokenization, platforms, and computational algorithms with economics and its use of contracts, mechanism design, general equilibrium, and monetary theory. Topics include: legacy systems in developed and developing economies; technological change; the impact of distributed ledgers, smart contracts, and encryption; the optimal allocation of risk; market structure; and optimized regulation. Explores new financial designs for industry, digital companies, central banks, and international organizations. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E51-361"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.170","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.19","title":"Market Design","level":"U","description":"Covers the design and operation of organized markets, building on ideas from microeconomic and game theory.  Topics may include mechanism design, auctions, matching markets, and other resource allocation problems.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"E51-376"},{"days":["F"],"start":"13:00","end":"14:00","room":"E51-361"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.19","terms":["fall"],"rating":6.22,"hours":8.11,"inClassHours":3.61,"outOfClassHours":4.5,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.192","title":"Advanced Research and Communication","level":"G","description":"Guides second-year Economics PhD students through the process of conducting and communicating economic research. Students choose topics for research projects, develop research strategies, carry out analyses, and write and present research papers. Limited to second year Economics PhD students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:00","end":"10:30","room":"E52-432"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.192","terms":["fall","spring"],"rating":6.76,"hours":8.46,"inClassHours":2.19,"outOfClassHours":6.27,"prerequisites":"14.124, 14.382, 14.454","corequisites":"","recommendedPreparation":""},{"code":"14.20","title":"Industrial Organization: Competitive Strategy and Public Policy","level":"U","description":"Analyzes the current debate over the rise of monopolies, the strategic behavior and performance of firms in imperfectly competitive markets, and the role of competition policy. Topics include monopoly power; pricing, product choice, and innovation decisions by firms in oligopoly markets; static and dynamic measurement of market performance; and incentives in organizations. Requires regular participation in class discussion and teamwork in a competitive strategy game. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.20","terms":["fall"],"rating":6.56,"hours":7.83,"inClassHours":4.17,"outOfClassHours":3.66,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.200","title":"Industrial Organization: Competitive Strategy and Public Policy","level":"G","description":"Analyzes the current debate over the rise of monopolies, the strategic behavior and performance of firms in imperfectly competitive markets, and the role of competition policy. Topics include monopoly power; pricing, product choice, and innovation decisions by firms in oligopoly markets; static and dynamic measurement of market performance; and incentives in organizations. Requires regular participation in class discussion and teamwork in a competitive strategy game. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.200","terms":["fall"],"rating":6.57,"hours":7.83,"inClassHours":4.18,"outOfClassHours":3.65,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.26","title":"Organizational Economics","level":"U","description":"Provides a rigorous, but not overly technical introduction to the economic theory of organization together with a varying set of applications. Addresses incentives, control, relationships, decision processes, and organizational culture and performance. Introduces selected fundamentals of game theory. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E51-057"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-372"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.26","terms":["fall"],"rating":5.57,"hours":8.54,"inClassHours":3.6,"outOfClassHours":4.94,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.260","title":"Organizational Economics","level":"G","description":"Provides a rigorous, but not overly technical introduction to the economic theory of organization together with a varying set of applications. Addresses incentives, control, relationships, decision processes, and organizational culture and performance. Introduces selected fundamentals of game theory. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E51-057"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-372"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.260","terms":["fall"],"rating":5.56,"hours":8.6,"inClassHours":3.61,"outOfClassHours":4.99,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.271","title":"Industrial Organization I","level":"G","description":"Covers theoretical and empirical work dealing with the market structure, firm behavior, and consumer outcomes in imperfectly competitive markets. Topics include: monopoly, price discrimination, product differentiation, consumer search, dynamic oligopoly, entry, platforms, auctions, bounded rationality, and online markets. Theoretical and empirical work are integrated in each area.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"10:30","room":"E51-395"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:30","room":"E51-361"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.271","terms":["fall"],"rating":6.43,"hours":12.18,"inClassHours":3.55,"outOfClassHours":8.63,"prerequisites":"","corequisites":"14.122, 14.381","recommendedPreparation":""},{"code":"14.281","title":"Contract Economics","level":"G","description":"Covers theoretical research on contracts in static as well as dynamic settings. Topics include agency theory, mechanism design, incomplete contracting, information design and costly information acquisition.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-372"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"15:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.281","terms":["fall"],"rating":6.63,"hours":11.93,"inClassHours":3.66,"outOfClassHours":8.27,"prerequisites":"14.124/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.282","title":"Introduction to Organizational Economics","level":"G","description":"Begins with survey of contract theory for organizational economists, then introduces the main areas of the field, including the boundary of the firm; decision-making, employment, structures and processes in organizations; and organizations other than firms.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E62-550"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:30","end":"16:00","room":"E62-550"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.282","terms":["fall"],"rating":6.83,"hours":8.14,"inClassHours":3.49,"outOfClassHours":4.65,"prerequisites":"14.124","corequisites":"","recommendedPreparation":""},{"code":"14.30","title":"Introduction to Statistical Methods in Economics","level":"U","description":"Self-contained introduction to probability and statistics with applications in economics and the social sciences.  Covers elements of probability theory, statistical estimation and inference, regression analysis, causal inference, and program evaluation. Couples methods with applications and with assignments involving data analysis. Uses basic calculus and matrix algebra.  Students taking graduate version complete additional assignments. May not count toward HASS requirement.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-372"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.30","terms":["fall"],"rating":5.32,"hours":7.78,"inClassHours":3.58,"outOfClassHours":4.2,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":""},{"code":"14.300","title":"Introduction to Statistical Methods in Economics","level":"G","description":"Self-contained introduction to probability and statistics with applications in economics and the social sciences. Covers elements of probability theory, statistical estimation and inference, regression analysis, causal inference, and program evaluation. Couples methods with applications and with assignments involving data analysis. Uses basic calculus and matrix algebra. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-372"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.300","terms":["fall"],"rating":5.32,"hours":7.78,"inClassHours":3.58,"outOfClassHours":4.2,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":""},{"code":"14.32","title":"Econometric Data Science","level":"U","description":"Introduces regression and other tools for causal inference and descriptive analysis in empirical economics. Topics include analysis of randomized experiments, instrumental variables methods and regression discontinuity designs, differences-in-differences estimation, and regression with time series data. Develops the skills needed to conduct — and critique — empirical studies in economics and related fields. Empirical applications are drawn from published examples and frontier research. Familiarity with statistical programming languages is helpful. Students taking graduate version complete an empirical project leading to a short paper. No listeners. Limited to 70 total for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E25-111"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.32","terms":["fall","spring"],"rating":6.12,"hours":10.21,"inClassHours":3.77,"outOfClassHours":6.44,"prerequisites":"14.30/15.069/18.650","corequisites":"","recommendedPreparation":"Familiarity with statistical programming languages is helpful."},{"code":"14.320","title":"Econometric Data Science","level":"G","description":"Introduces regression and other tools for causal inference and descriptive analysis in empirical economics. Topics include analysis of randomized experiments, instrumental variables methods and regression discontinuity designs, differences-in-differences estimation, and regress with time series data. Develops the skills needed to conduct — and critique — empirical studies in economics and related fields. Empirical applications are drawn from published examples and frontier research. Familiarity with statistical programming languages is helpful. Students taking graduate version complete an empirical project leading to a short paper. No listeners. Limited to 70 total for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E25-111"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.320","terms":["fall","spring"],"rating":6.12,"hours":10.22,"inClassHours":3.78,"outOfClassHours":6.44,"prerequisites":"14.300/15.069/18.650","corequisites":"","recommendedPreparation":"Familiarity with statistical programming languages is helpful."},{"code":"14.33","title":"Research and Communication in Economics: Topics, Methods, and Implementation","level":"U","description":"Exposes students to the process of conducting independent research in empirical economics and effectively communicating the results of the research. Emphasizes econometric analysis of an assigned economic question and culminates in each student choosing an original topic, performing appropriate analysis, and delivering oral and written project reports. Limited to 20 per section.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.33","terms":["fall","spring"],"rating":6.27,"hours":8.39,"inClassHours":2.33,"outOfClassHours":6.06,"prerequisites":"14.32, (14.01/14.02)","corequisites":"","recommendedPreparation":""},{"code":"14.35","title":"Why Markets Fail","level":"U","description":"Guides students through the process of developing and communicating economic and data analysis. Discusses topics in which markets fail to provide efficient outcomes or economic opportunity. Topics include health insurance, intergenerational mobility, discrimination, climate change, and more. Instruction and practice in oral and written communication provided. Key course activities include the writing of a term paper conducting original economic analysis and an in-class slide presentation of the work. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.35","terms":["fall"],"rating":6.8,"hours":12.5,"inClassHours":3.5,"outOfClassHours":9.0,"prerequisites":"14.04/14.12/14.15/14.19","corequisites":"","recommendedPreparation":""},{"code":"14.380","title":"Statistical Method in Economics","level":"G","description":"Introduction to probability and statistics as background for advanced econometrics. Covers elements of probability theory, sampling theory, asymptotic approximations, hypothesis testing, and maximum-likelihood methods. Illustrations from economics and application of these concepts to economic problems. Limited to 40 PhD students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"E51-372"}]},{"type":"Recitation","options":[{"days":["F"],"start":"16:00","end":"17:30","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.380","terms":["fall"],"rating":6.15,"hours":11.21,"inClassHours":4.02,"outOfClassHours":7.19,"prerequisites":"14.32/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.381","title":"Estimation and Inference for Linear Causal and Structural Models","level":"G","description":"Explains basic econometric ideas and methods, illustrating with empirical applications. Causal inference is emphasized and examples of economic structural models are given. Topics include randomized trials, regression, including discontinuity designs and diffs-in-diffs, and instrumental variables, including local average treatment effects. Basic asymptotic theory for regression is covered and robust standard errors and statistical inference methods are given. Restricted to PhD students from Courses 14 and 15. Instructor approval required for all others.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"E51-372"}]},{"type":"Recitation","options":[{"days":["F"],"start":"16:00","end":"17:30","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.381","terms":["fall"],"rating":6.08,"hours":10.42,"inClassHours":4.0,"outOfClassHours":6.42,"prerequisites":"14.380, 18.06","corequisites":"","recommendedPreparation":""},{"code":"14.384","title":"Time Series Analysis","level":"G","description":"Studies theory and application of time series methods in econometrics, including spectral analysis, estimation with stationary and non-stationary processes, VARs, factor models, unit roots, cointegration, and Bayesian methods. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E51-372"}]},{"type":"Recitation","options":[{"days":["W"],"start":"17:30","end":"19:00","room":"E51-361"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.384","terms":["fall"],"rating":6.37,"hours":10.35,"inClassHours":3.92,"outOfClassHours":6.43,"prerequisites":"14.382/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.385","title":"Nonlinear Econometric Analysis","level":"G","description":"Develops a full understanding of and ability to apply micro-econometric models and methods. Topics include extremum estimators, including minimum distance and simulated moments, identification, partial identification, sensitivity analysis, many weak instruments, nonlinear panel data, de-biased machine learning, discrete choice models, nonparametric estimation, quantile regression, and treatment effects. Methods are illustrated with economic applications. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-361"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.385","terms":["fall"],"rating":6.05,"hours":8.56,"inClassHours":3.19,"outOfClassHours":5.37,"prerequisites":"14.382/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.39","title":"Large-Scale Decision-Making and Inference","level":"U","description":"Covers the use of data to guide decision-making, with a focus on data-rich and high-dimensional environments as are now commonly encountered in both academic and industry applications. Begins with an introduction to statistical decision theory, including Bayesian perspectives. Covers empirical Bayes methods, including related concepts such as false discovery rates, illustrated with economic applications. Requires knowledge of mathematical statistics and regression analysis, as well as programming experience in R or Python. Students taking the graduate version submit additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.39","terms":["fall"],"rating":6.93,"hours":7.64,"inClassHours":2.77,"outOfClassHours":4.87,"prerequisites":"14.32","corequisites":"","recommendedPreparation":"Requires knowledge of mathematical statistics and regression analysis, as well as programming experience in R or Python."},{"code":"14.390","title":"Large-Scale Decision-Making and Inference","level":"G","description":"Covers the use of data to guide decision-making, with a focus on data-rich and high-dimensional environments as are now commonly encountered in both academic and industry applications. Begins with an introduction to statistical decision theory, including Bayesian perspectives. Covers empirical Bayes methods, including related concepts such as false discovery rates, illustrated with economic applications. Requires knowledge of mathematical statistics and regression analysis, as well as programming experience in R or Python. Students taking the graduate version submit additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.390","terms":["fall"],"rating":6.93,"hours":7.64,"inClassHours":2.77,"outOfClassHours":4.87,"prerequisites":"14.320","corequisites":"","recommendedPreparation":"Requires knowledge of mathematical statistics and regression analysis, as well as programming experience in R or Python."},{"code":"14.391","title":"Workshop in Economic Research","level":"G","description":"Develops research ability of students through intensive discussion of dissertation research as it proceeds, individual or group research projects, and critical appraisal of current reported research. Workshops divided into various fields, depending on interest and size.","groups":[{"type":"Recitation","options":[{"days":["M"],"start":"14:30","end":"16:00","room":"E52-324"},{"days":["R"],"start":"16:00","end":"17:30","room":"E51-151"},{"days":["R"],"start":"15:00","end":"16:30","room":"E51-372"},{"days":["R"],"start":"16:00","end":"17:30","room":"E51-395"},{"days":["M"],"start":"16:00","end":"17:30","room":"E51-151"},{"days":["M"],"start":"16:00","end":"17:30","room":"E52-324"},{"days":["M"],"start":"16:00","end":"17:30","room":"E52-432"},{"days":["T"],"start":"14:30","end":"16:00","room":"E62-650"},{"days":["T"],"start":"16:00","end":"17:30","room":"E52-164"},{"days":["T"],"start":"16:00","end":"17:30","room":"E52-432"},{"days":["W"],"start":"16:00","end":"17:30","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.391","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"14.124, 14.454","corequisites":"","recommendedPreparation":""},{"code":"14.393","title":"Seminar in Economic History","level":"G","description":"Approaches the interplay of history and economics with a focus on how economists use history and how historians use economic ideas. Explores methods and topics, including the political economy of empire, poverty, environment, energy, and information. Class sessions include readings, discussion, and guest lectures.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"12:00","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/m14a.html#14.393","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.41","title":"Public Finance and Public Policy","level":"U","description":"Explores the role of government in the economy, applying tools of basic microeconomics to answer important policy questions such as government response to global warming, school choice by K-12 students, Social Security versus private retirement savings accounts, government versus private health insurance, setting income tax rates for individuals and corporations. Students taking the graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-145"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.41","terms":["fall"],"rating":6.39,"hours":9.12,"inClassHours":3.64,"outOfClassHours":5.48,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.410","title":"Public Finance and Public Policy","level":"G","description":"Explores the role of government in the economy, applying tools of basic microeconomics to answer important policy questions such as government response to global warming, school choice by K-12 students, Social Security versus private retirement savings accounts, government versus private health insurance, setting income tax rates for individuals and corporations. Students taking the graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-145"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.410","terms":["fall"],"rating":6.42,"hours":8.84,"inClassHours":3.66,"outOfClassHours":5.18,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"14.416","title":"Asset Pricing","level":"G","description":"Provides a foundation in the neoclassical theory of finance that underlies more advanced study. Covers arbitrage asset pricing, optimal consumption-portfolio choices, neo-classic theory of corporate finance, static equilibrium models of asset pricing, asymmetric information, and dynamic modeling. Prepares students for further study of asset pricing theories, corporate finance and econometric work in finance. Primarily for doctoral students in finance, economics, and accounting.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:00","end":"17:30","room":"E62-650"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E62-350"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.416","terms":["fall"],"rating":6.35,"hours":15.0,"inClassHours":4.06,"outOfClassHours":10.94,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.442","title":"Advanced Asset Pricing","level":"G","description":"Focuses on developing, solving, estimating, and empirically evaluating theoretical models of asset prices and financial markets, as well as their microeconomic foundations and macroeconomic implications. Discusses theory and econometric methods, the state of the literature, and recent developments and empirical evidence. Covers topics such as cross-sectional and time-series models, consumption-based and intermediary-based models, financial institutions, household finance, housing, behavioral finance, financial crises, market structure, and continuous-time tools and applications. Primarily for doctoral students in finance, economics, and accounting.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"16:00","end":"17:30","room":"E62-650"}]},{"type":"Recitation","options":[{"days":["M"],"start":"18:00","end":"19:30","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.442","terms":["fall"],"rating":6.01,"hours":13.24,"inClassHours":3.24,"outOfClassHours":10.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.448","title":"Current Topics in Finance","level":"G","description":"Faculty present their current research in a wide variety of topics in finance. Provides a rapid overview of the literature, an in-depth presentation of selected contributions, and a list of potential research ideas for each topic. Faculty rotate every year to cover new topics. Primarily for doctoral students in accounting, economics, and finance.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:30","end":"12:00","room":"E62-650"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.448","terms":["fall","spring"],"rating":7.0,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.449","title":"Current Research in Financial Economics","level":"G","description":"Advanced seminar intended for PhD students interested in finance. Topics and papers vary by term, following the latest research in academia and in correlation with the weekly finance faculty research seminar. Each week, students will critically review the contributions, method of analysis, and presentation of evidence of existing research; one session is devoted to preparing for the finance seminar, while the other session discusses further work on the same topic. Restricted to doctoral students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:00","end":"13:00","room":"E62-687"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.449","terms":["fall","spring"],"rating":6.02,"hours":4.58,"inClassHours":2.02,"outOfClassHours":2.56,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.45","title":"Climate and Energy in the Global Economy","level":"U","description":"Provides students with a comprehensive understanding of the challenges, opportunities, and policy responses to the global climate and energy transitions. Discusses the role of energy in world economies, paying particular attention to low- and middle-income countries, as well as the impacts of climate change on those economies. Considers how energy access, cost, reliability, and environmental harm drive or hinder economic growth, the political influences on the energy sector, and the role of energy in mitigating future impacts of climate change. Also discusses global climate solutions, including the role of the United Nations Framework Convention on Climate Change process, trade policy, climate finance, business strategies to reduce emissions, and business strategies to help people adapt to a changing climate. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.45","terms":["fall"],"rating":6.43,"hours":6.24,"inClassHours":3.07,"outOfClassHours":3.17,"prerequisites":"14.01/15.0111","corequisites":"","recommendedPreparation":""},{"code":"14.450","title":"Climate and Energy in the Global Economy","level":"G","description":"Provides students with a comprehensive understanding of the challenges, opportunities, and policy responses to the global climate and energy transitions. Discusses the role of energy in world economies, paying particular attention to low- and middle-income countries, as well as the impacts of climate change on those economies. Considers how energy access, cost, reliability, and environmental harm drive or hinder economic growth, the political influences on the energy sector, and the role of energy in mitigating future impacts of climate change. Also discusses global climate solutions, including the role of the United Nations Framework Convention on Climate Change process, trade policy, climate finance, business strategies to reduce emissions, and business strategies to help people adapt to a changing climate. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.450","terms":["fall"],"rating":5.93,"hours":5.56,"inClassHours":3.23,"outOfClassHours":2.33,"prerequisites":"14.01/15.010/15.011/15.024","corequisites":"","recommendedPreparation":""},{"code":"14.451","title":"Dynamic Optimization Methods with Applications","level":"G","description":"Provides an introduction to dynamic optimization methods, including discrete-time dynamic programming in non-stochastic and stochastic environments, and continuous time methods including the Pontryagin maximum principle. Applications may include the Ramsey model, irreversible investment models, and consumption choices under uncertainty. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-151"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:30","end":"16:00","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.451","terms":["fall"],"rating":5.74,"hours":14.19,"inClassHours":4.25,"outOfClassHours":9.94,"prerequisites":"14.06, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.452","title":"Economic Growth","level":"G","description":"Introduces the sources and modeling of economic growth and income differences across nations. Topics include an introduction to dynamic general equilibrium theory, the neoclassical growth model, overlapping generations, determinants of technological progress, endogenous growth models, measurement of technological progress, the role of human capital in economic growth, and growth in a global economy. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-151"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:30","end":"16:00","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.452","terms":["fall"],"rating":5.52,"hours":14.91,"inClassHours":4.29,"outOfClassHours":10.62,"prerequisites":"14.451, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"14.461","title":"Advanced Macroeconomics I","level":"G","description":"Advanced subject in macroeconomics that seeks to bring students to the research frontier. Topics vary from year to year, covering a wide spectrum of classical and recent research. Topics may include business cycles, optimal monetary and tax policy, monetary economics, banking, and financial constraints on investment and incomplete markets.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E52-432"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.461","terms":["fall"],"rating":6.13,"hours":10.6,"inClassHours":3.6,"outOfClassHours":7.0,"prerequisites":"14.122, 14.452","corequisites":"","recommendedPreparation":""},{"code":"14.472","title":"Public Economics II","level":"G","description":"Focuses on government expenditures and policies designed to correct market failures and/or redistribute resources. Key topics include theoretical and empirical analysis of insurance market failures, the optimal design of social insurance programs, and the design of redistributive programs.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-361"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.472","terms":["fall"],"rating":6.17,"hours":9.74,"inClassHours":3.85,"outOfClassHours":5.89,"prerequisites":"14.471","corequisites":"","recommendedPreparation":""},{"code":"14.581","title":"International Economics I","level":"G","description":"Covers a variety of topics, both theoretical and empirical, in international trade, international macroeconomics, and economic geography. Focuses on general equilibrium analysis in neoclassical economies. Considers why countries and regions trade, and what goods they trade; impediments to trade, and why some countries deliberately erect policy to impede; and implications of openness for growth. Also tackles normative issues, such as whether trade openness is beneficial, whether there are winners and losers from trade and, if so, how they can possibly be identified.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"10:30","room":"E51-151"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:30","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.581","terms":["fall"],"rating":6.58,"hours":13.64,"inClassHours":4.22,"outOfClassHours":9.42,"prerequisites":"14.04","corequisites":"","recommendedPreparation":""},{"code":"14.661","title":"Labor Economics I","level":"G","description":"A systematic development of the theory of labor supply, labor demand, and human capital. Topics include wage and employment determination, turnover, search, immigration, unemployment, equalizing differences, and institutions in the labor market. Particular emphasis on the interaction between theoretical and empirical modeling. No listeners.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E52-432"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:30","end":"12:00","room":"E52-432"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.661","terms":["fall"],"rating":6.32,"hours":11.02,"inClassHours":4.2,"outOfClassHours":6.82,"prerequisites":"14.32, (14.03/14.04)","corequisites":"","recommendedPreparation":""},{"code":"14.661A","title":"Labor Economics I","level":"G","description":"Covers the same material as 14.661 but in greater depth. Additional assignments required. Limited to economics PhD students who wish to declare a major field in labor economics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E52-432"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:30","end":"12:00","room":"E52-432"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.661A","terms":["fall"],"rating":6.32,"hours":10.97,"inClassHours":4.19,"outOfClassHours":6.78,"prerequisites":"14.32, (14.03/14.04)","corequisites":"","recommendedPreparation":""},{"code":"14.770","title":"Introduction to Collective Choice and Political Economy","level":"G","description":"Broad introduction to political economy. Covers topics from social choice theory to political agency models, including theories of voter turnout and comparison of political institutions.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E52-532"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.770","terms":["fall"],"rating":6.22,"hours":7.45,"inClassHours":3.19,"outOfClassHours":4.26,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"14.771","title":"Development Economics: Microeconomic Issues","level":"G","description":"A rigorous introduction to core micro-economic issues in economic development, focusing on both key theoretical contributions and empirical applications to understand both why some countries are poor and on how markets function differently in poor economies. Topics include poverty traps; human capital (education and health); labor markets; credit markets; land markets; and the role of the public sector.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-151"}]},{"type":"Recitation","options":[{"days":["T"],"start":"15:00","end":"16:00","room":"E51-372"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.771","terms":["fall"],"rating":6.63,"hours":9.78,"inClassHours":3.71,"outOfClassHours":6.07,"prerequisites":"14.121, 14.122","corequisites":"","recommendedPreparation":""},{"code":"14.775","title":"Comparing Societies","level":"G","description":"Studies the cultural, social, and institutional foundations of societies around the world, emphasizing fundamentals and mechanisms that are outside the scope of traditional models in economics. Topics include social organization, perceptions of reality (e.g., the spiritual and meta-human world), drivers of innovation and technology diffusion, conflict, determinants of fertility and population growth, moral frameworks (e.g., views about right/wrong, fairness, equality, and community membership), religion, objectives and definitions of success, and societal equilibria. Emphasizes how research ranging from economic theory to development and policy design can benefit from an understanding of these vast differences that exist around the world. Also considers how these differences affect and are affected by culture, formal institutions, and development. Open to PhD students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:30","end":"19:00","room":"E52-432"}]}],"url":"http://student.mit.edu/catalog/m14b.html#14.775","terms":["fall"],"rating":6.57,"hours":7.23,"inClassHours":2.9,"outOfClassHours":4.33,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"15.000","title":"Explorations in Management","level":"U","description":"Broad introduction to the various aspects of management including analytics, accounting and finance, operations, marketing, entrepreneurship and leadership, organizations, economics, systems dynamics, and negotiation and communication. Introduces the field of management through a variety of experiences as well as discussions led by faculty or industry experts. Also reviews the three undergraduate majors offered by Sloan as well as careers in management. Subject can count toward the 6-unit discovery-focused credit limit for first year students. Limited to undergraduates; preference to first years.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"15:00","end":"16:30","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.000","terms":["fall","spring"],"rating":6.46,"hours":2.34,"inClassHours":1.81,"outOfClassHours":0.53,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"15.010","title":"Economic Analysis for Business Decisions","level":"G","description":"Introduces principles of microeconomics as a framework for making more informed managerial decisions. Discusses the supply and demand paradigm with applications to digital marketplaces, innovation, sources of market power, and strategic pricing. Provides an introduction to game theory to study competition and cooperation both within and between firms. Restricted to first-year Sloan MBA students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E62-262"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-315"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-325"},{"days":["T","R"],"start":"08:30","end":"10:00","room":"E62-262"},{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-315"},{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-325"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-325"},{"days":["F"],"start":"11:00","end":"12:00","room":"E51-325"},{"days":["F"],"start":"12:00","end":"13:00","room":"E51-325"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.010","terms":["fall"],"rating":5.21,"hours":5.64,"inClassHours":3.27,"outOfClassHours":2.37,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"15.016","title":"Climate and Energy in the Global Economy","level":"G","description":"Provides students with a comprehensive understanding of the challenges, opportunities, and policy responses to the global climate and energy transitions. Discusses the role of energy in world economies, paying particular attention to low- and middle-income countries, as well as the impacts of climate change on those economies. Considers how energy access, cost, reliability, and environmental harm drive or hinder economic growth, the political influences on the energy sector, and the role of energy in mitigating future impacts of climate change. Also discusses global climate solutions, including the role of the United Nations Framework Convention on Climate Change process, trade policy, climate finance, business strategies to reduce emissions, and business strategies to help people adapt to a changing climate. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.016","terms":["fall"],"rating":5.93,"hours":5.56,"inClassHours":3.23,"outOfClassHours":2.33,"prerequisites":"14.01/15.010/15.011/15.024","corequisites":"","recommendedPreparation":""},{"code":"15.0161","title":"Climate and Energy in the Global Economy","level":"U","description":"Provides students with a comprehensive understanding of the challenges, opportunities, and policy responses to the global climate and energy transitions. Discusses the role of energy in world economies, paying particular attention to low- and middle-income countries, as well as the impacts of climate change on those economies. Considers how energy access, cost, reliability, and environmental harm drive or hinder economic growth, the political influences on the energy sector, and the role of energy in mitigating future impacts of climate change. Also discusses global climate solutions, including the role of the United Nations Framework Convention on Climate Change process, trade policy, climate finance, business strategies to reduce emissions, and business strategies to help people adapt to a changing climate. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.0161","terms":["fall"],"rating":6.43,"hours":6.24,"inClassHours":3.07,"outOfClassHours":3.17,"prerequisites":"14.01/15.0111","corequisites":"","recommendedPreparation":""},{"code":"15.021","title":"Real Estate Economics","level":"G","description":"Develops an understanding of the fundamental economic factors that shape the market for real property, as well as the influence of capital markets in asset pricing. Analyzes of housing as well as commercial real estate. Covers demographic analysis, regional growth, construction cycles, urban land markets, and location theory as well as recent technology impacts. Exercises and modeling techniques for measuring and predicting property demand, supply, vacancy, rents, and prices.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"9-354"}]},{"type":"Recitation","options":[{"days":["W"],"start":"16:30","end":"18:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.021","terms":["fall"],"rating":6.3,"hours":9.53,"inClassHours":4.09,"outOfClassHours":5.44,"prerequisites":"14.01/15.010/15.011","corequisites":"","recommendedPreparation":""},{"code":"15.039","title":"Organizational Economics","level":"U","description":"Provides a rigorous, but not overly technical introduction to the economic theory of organization together with a varying set of applications. Addresses incentives, control, relationships, decision processes, and organizational culture and performance. Introduces selected fundamentals of game theory. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"E51-057"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-372"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.039","terms":["fall"],"rating":5.56,"hours":8.6,"inClassHours":3.61,"outOfClassHours":4.99,"prerequisites":"14.01","corequisites":"","recommendedPreparation":""},{"code":"15.054","title":"The Airline Industry","level":"G","description":"Overview of the global airline industry and its economic and operational foundations. Examines interactions among key stakeholders in the aviation system, including airlines, airports, and air traffic management. Introduces fundamentals of airline economics, including demand, cost structures, pricing, competition, and regulatory frameworks. Covers operational and strategic decision-making such as fleet and network planning and airline operations. Considers system-level challenges including safety, environmental sustainability, and evolving global market dynamics. Students analyze industry performance, market developments, and emerging operational challenges in aviation.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.054","terms":["fall"],"rating":6.65,"hours":9.04,"inClassHours":3.04,"outOfClassHours":6.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"15.060","title":"Data, Models, and Decisions","level":"G","description":"Introduces students to the basic tools in using data to make informed management decisions. Covers basic topics in data analytics, including introductory probability, decision analysis, basic statistics, regression, simulation, linear and discrete optimization, and introductory machine learning. Spreadsheet exercises, cases, and examples drawn from marketing, finance, operations management, and other management functions. Restricted to first-year Sloan master's students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E62-262"},{"days":["M","W"],"start":"08:30","end":"10:00","room":"E62-223"},{"days":["M","W"],"start":"08:30","end":"10:00","room":"E51-325"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E62-262"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E62-223"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-325"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.060","terms":["fall"],"rating":5.61,"hours":6.85,"inClassHours":3.32,"outOfClassHours":3.53,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"15.069","title":"Applied Probability and Statistics","level":"U","description":"Presents probability from the perspective of applied mathematics, with strong emphasis on an intuitive overview of key theorems and continuing demonstrations of their usefulness. Covers the laws of probability and numerous important discrete and continuous random variables, both individually and in combination. Introduces simulation. Offers an introduction to statistics that emphasizes its probabilistic foundations and the fact that statistical reasoning is applied common sense. Covers hypothesis testing, statistical sampling, and various forms of regression analysis. Draws applications from economics, finance, engineering, marketing, public policy, operations management, and operations research.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.069","terms":["fall"],"rating":6.13,"hours":10.06,"inClassHours":3.79,"outOfClassHours":6.27,"prerequisites":"GIR:CAL1","corequisites":"","recommendedPreparation":""},{"code":"15.071","title":"The AI Edge","level":"G","description":"Presents methods and applications of data science, artificial intelligence, and generative AI. Covers the core toolkit of machine learning ? regularized regression and classification, time series, tree-based methods ? and deep learning ? neural networks, transformers, large language models, and multi-modal AI. Follows a problem-driven approach using case studies in supply chains, finance, transportation, energy, healthcare, and digital platforms. Intended for students who aim to understand the foundations underpinning the AI revolution, design and deploy designing that create operational and strategic value, and lead AI projects in organizations. Includes a team project focused on designing an end-to-end AI solution and communicating results to technical and executive audiences. Prior familiarity with Python and foundational machine learning concepts recommended. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E51-345"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.071","terms":["fall","spring"],"rating":6.24,"hours":10.28,"inClassHours":4.36,"outOfClassHours":5.92,"prerequisites":"15.060/''permission of instructor''","corequisites":"","recommendedPreparation":"Prior familiarity with Python and foundational machine learning concepts recommended."},{"code":"15.072","title":"Advanced Analytics Edge","level":"G","description":"Covers key topics in data science (in the context of analytics) ranging from descriptive, inferential statistics, and regressions analysis to modern predictive analytics (interpretable machine learning models, trees, rules, and flexible black-box methods). All methods and tools illustrated through real-world applications. Focuses on topics that are most relevant to the practical analysis of managerial decisions. Uses the R and Julia programming languages. Preference to Sloan Master of Business Analytics students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-345"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.072","terms":["fall"],"rating":5.81,"hours":9.07,"inClassHours":3.7,"outOfClassHours":5.37,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"15.081","title":"Introduction to Mathematical Programming","level":"G","description":"Introduction to linear optimization and its extensions emphasizing both methodology and the underlying mathematical structures and geometrical ideas. Covers classical theory of linear programming as well as some recent advances in the field. Topics: simplex method; duality theory; sensitivity analysis; network flow problems; decomposition; robust optimization; integer programming; interior point algorithms for linear programming; and introduction to combinatorial optimization and NP-completeness.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"32-141"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"2-105"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.081","terms":["fall"],"rating":6.33,"hours":13.02,"inClassHours":3.79,"outOfClassHours":9.23,"prerequisites":"18.06","corequisites":"","recommendedPreparation":""},{"code":"15.085","title":"Fundamentals of Probability","level":"G","description":"Introduction to probability theory. Probability spaces and measures. Discrete and continuous random variables. Conditioning and independence. Multivariate normal distribution. Abstract integration, expectation, and related convergence results. Moment generating and characteristic functions. Bernoulli and Poisson process. Finite-state Markov chains. Convergence notions and their relations. Limit theorems. Familiarity with elementary probability and real analysis is desirable.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-230"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"3-333"},{"days":["F"],"start":"14:00","end":"15:00","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.085","terms":["fall"],"rating":6.07,"hours":13.62,"inClassHours":3.39,"outOfClassHours":10.23,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":"Familiarity with elementary probability and real analysis is desirable."},{"code":"15.095","title":"Machine Learning Under a Modern Optimization Lens","level":"G","description":"Develops algorithms for central problems in machine learning from a modern optimization perspective. Topics include sparse, convex, robust and median regression; an algorithmic framework for regression; optimal classification and regression trees, and their relationship with neural networks; how to transform predictive algorithms to prescriptive algorithms; optimal prescriptive trees; and robust classification.  Also covers design of experiments, missing data imputations, mixture of Gaussian models, exact bootstrap, and sparse matrix estimation, including principal component analysis, factor analysis, inverse co-variance matrix estimation, and matrix completion.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:00","end":"17:30","room":"E51-345"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.095","terms":["fall"],"rating":5.19,"hours":14.58,"inClassHours":4.18,"outOfClassHours":10.4,"prerequisites":"6.7210/15.093/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"15.128","title":"Revolutionary Ventures: How to Invent and Deploy Transformative Technologies","level":"G","description":"Seminar on envisioning and building ideas and organizations to accelerate engineering revolutions. Focuses on emerging technology domains, such as neurotechnology, imaging, cryotechnology, gerontechnology, and bio-and-nano fabrication. Draws on historical examples as well as live case studies of existing or emerging organizations, including labs, institutes, startups, and companies. Goals range from accelerating basic science to developing transformative products or therapeutics. Each class is devoted to a specific area, often with invited speakers, exploring issues from the deeply technical through the strategic. Individually or in small groups, students prototype new ventures aimed at inventing and deploying revolutionary technologies.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"16:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.128","terms":["fall"],"rating":6.2,"hours":5.96,"inClassHours":2.07,"outOfClassHours":3.89,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"15.136","title":"Principles and Practice of Drug Development","level":"G","description":"Description and critical assessment of the major issues and stages of developing a pharmaceutical or biopharmaceutical. Drug discovery, preclinical development, clinical investigation, manufacturing and regulatory issues considered for small and large molecules. Economic and financial considerations of the drug development process. Multidisciplinary perspective from faculty in clinical; life; and management sciences; as well as industry guests.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.136","terms":["fall"],"rating":5.31,"hours":7.39,"inClassHours":3.17,"outOfClassHours":4.22,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""}]);
